## File 2: src/data/books.js

```javascript
/**
 * @fileoverview In-memory data storage module for books.
 * 
 * DESIGN DECISIONS:
 * - We use an array instead of a Map because we need to maintain insertion order
 *   and support range-based queries (e.g., "books from year 2000-2010").
 * - Each book has a unique numeric ID generated by incrementing counter.
 * - In production, you would replace this with MongoDB/PostgreSQL.
 */

// Array to store all books in memory
const books = [];

// Counter for generating unique IDs
let nextId = 1;

/**
 * Retrieves all books from the in-memory storage.
 * 
 * @param {Object} [filters] - Optional filtering parameters
 * @param {string} [filters.genre] - Filter by genre (exact match)
 * @param {string} [filters.author] - Filter by author name (case-insensitive partial match)
 * @param {number} [filters.minYear] - Minimum publication year
 * @param {number} [filters.maxYear] - Maximum publication year
 * @param {number} [filters.minRating] - Minimum rating (0-5)
 * @returns {Array<Object>} Array of book objects matching the filters
 * 
 * EXAMPLE USAGE:
 * getAllBooks({ genre: 'Fiction', minYear: 2000 })
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Create a copy to avoid mutating the original array

  // Apply genre filter (exact match, case-insensitive)
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter(book => book.genre.toLowerCase() === genreLower);
  }

  // Apply author filter (case-insensitive partial match)
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book => 
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // Apply year range filters
  if (filters.minYear !== undefined) {
    result = result.filter(book => book.year >= filters.minYear);
  }
  if (filters.maxYear !== undefined) {
    result = result.filter(book => book.year <= filters.maxYear);
  }

  // Apply rating filter
  if (filters.minRating !== undefined) {
    result = result.filter(book => book.rating >= filters.minRating);
  }

  return result;
}

/**
 * Retrieves a single book by its ID.
 * 
 * @param {number} id - The unique identifier of the book
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Creates a new book in the storage.
 * 
 * @param {Object} bookData - Book data to create
 * @param {string} bookData.title - Book title (required)
 * @param {string} bookData.author - Author name (required)
 * @param {number} bookData.year - Publication year (1000-2100)
 * @param {string} [bookData.genre] - Genre of the book
 * @param {number} [bookData.rating=0] - Rating from 0 to 5
 * @returns {Object} The created book object with generated ID
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Increment and assign the current counter value
    title: bookData.title,
    author: bookData.author,
    year: bookData.year,
    genre: bookData.genre || 'Unknown',
    rating: bookData.rating || 0,
    createdAt: new Date().toISOString() // Track when the book was added
  };

  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by its ID.
 * 
 * @param {number} id - The unique identifier of the book to update
 * @param {Object} updates - Fields to update (partial object)
 * @returns {Object|null} The updated book if found, null otherwise
 */
function updateBook(id, updates) {
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) {
    return null; // Book not found
  }

  // Update only the provided fields
  const updatedBook = {
    ...books[bookIndex], // Spread existing properties
    ...updates,          // Override with new values
    updatedAt: new Date().toISOString() // Track modification time
  };

  books[bookIndex] = updatedBook;
  return updatedBook;
}

/**
 * Deletes a book by its ID.
 * 
 * @param {number} id - The unique identifier of the book to delete
 * @returns {boolean} True if deleted, false if not found
 */
function deleteBook(id) {
  const initialLength = books.length;

  // Filter out the book with matching ID
  const filteredBooks = books.filter(book => book.id !== id);

  // If length changed, a book was removed
  const deleted = filteredBooks.length < initialLength;

  if (deleted) {
    books.length = 0; // Clear array
    books.push(...filteredBooks); // Restore remaining books
  }

  return deleted;
}

/**
 * Calculates statistics about the book collection.
 * 
 * @returns {Object} Statistics including total count, average rating, genre distribution, etc.
 */
function getStatistics() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      genres: {},
      mostRecentBook: null,
      oldestBook: null
    };
  }

  // Calculate average rating
  const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = parseFloat((totalRating / totalBooks).toFixed(2));

  // Count books per genre
  const genres = {};
  books.forEach(book => {
    const genre = book.genre || 'Unknown';
    genres[genre] = (genres[genre] || 0) + 1;
  });

  // Find most recent and oldest books by year
  const sortedByYear = [...books].sort((a, b) => a.year - b.year);

  return {
    totalBooks,
    averageRating,
    genres,
    mostRecentBook: sortedByYear[sortedByYear.length - 1], // Latest year
    oldestBook: sortedByYear[0] // Earliest year
  };
}

// Export all functions using CommonJS module syntax
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStatistics
};
```

**Why use an array?** Arrays maintain insertion order and support efficient filtering operations. For a small educational dataset (hundreds of books), arrays are perfectly adequate. In production with millions of records, you would use MongoDB or PostgreSQL for better query performance and persistence.

