## File 3: src/errors/index.js

```javascript
/**
 * @fileoverview Custom error classes for the application.
 * 
 * DESIGN DECISIONS:
 * - We create a base Error class that all custom errors extend from.
 * - Each error includes an HTTP status code for proper API responses.
 * - This pattern allows middleware to catch and handle different error types uniformly.
 */

/**
 * Base error class with HTTP status code support.
 * 
 * All custom errors in this application extend from this base class.
 * This provides a consistent structure for error handling throughout the app.
 */
class AppError extends Error {
  /**
   * Creates an instance of AppError.
   * 
   * @param {string} message - Human-readable error message
   * @param {number} statusCode - HTTP status code (4xx for client errors, 5xx for server errors)
   */
  constructor(message, statusCode) {
    super(message); // Call the parent Error constructor

    // Set the custom properties
    this.statusCode = statusCode;

    // Capture stack trace for debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Error thrown when a requested resource is not found.
 * 
 * Used for 404 responses when an ID doesn't exist in the database.
 */
class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404); // Call parent with message and status code
  }
}

/**
 * Error thrown when request validation fails.
 * 
 * Used for 400 responses when client sends invalid data.
 */
class ValidationError extends AppError {
  constructor(message = 'Validation failed') {
    super(message, 400); // Call parent with message and status code
  }
}

/**
 * Error thrown when a book already exists with the same title/author combination.
 * 
 * Used for 409 (Conflict) responses to prevent duplicate entries.
 */
class DuplicateError extends AppError {
  constructor(message = 'Duplicate entry') {
    super(message, 409); // Call parent with message and status code
  }
}

// Export all error classes
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DuplicateError
};
```

**Why custom error classes?** Custom errors allow us to attach additional metadata (like HTTP status codes) to exceptions. This enables centralized error handling middleware that can automatically return the correct HTTP response without checking error types in every route handler.

