## File 5: src/routes/books.js

```javascript
/**
 * @fileoverview Route handlers for book management endpoints.
 * 
 * DESIGN DECISIONS:
 * - We use Express Router to create a modular set of routes.
 * - Each route handler is an async function that uses try/catch for error handling.
 * - Query parameters are validated before being used in filtering logic.
 */

const express = require('express');
const router = express.Router(); // Create a new router instance

// Import our data layer and error classes
const { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStatistics } = require('../data/books');
const { NotFoundError, ValidationError } = require('../errors');

/**
 * GET /books - List all books with optional filtering.
 * 
 * QUERY PARAMETERS:
 * - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 * - author: Filter by author name (case-insensitive partial match, e.g., ?author=tolkien)
 * - minYear: Minimum publication year (e.g., ?minYear=2000)
 * - maxYear: Maximum publication year (e.g., ?maxYear=2010)
 * - minRating: Minimum rating from 0-5 (e.g., ?minRating=4)
 * 
 * EXAMPLE REQUESTS:
 * GET /books
 * GET /books?genre=Fiction&minYear=2000
 * GET /books?author=tolkien&minRating=4.5
 */
router.get('/', (req, res) => {
  try {
    // Extract query parameters from the URL
    const filters = {
      genre: req.query.genre,
      author: req.query.author,
      minYear: req.query.minYear ? parseInt(req.query.minYear) : undefined,
      maxYear: req.query.maxYear ? parseInt(req.query.maxYear) : undefined,
      minRating: req.query.minRating ? parseFloat(req.query.minRating) : undefined
    };

    // Validate numeric parameters
    if (filters.minYear !== undefined && (isNaN(filters.minYear) || filters.minYear < 1000 || filters.minYear > 2100)) {
      throw new ValidationError('minYear must be between 1000 and 2100');
    }

    if (filters.maxYear !== undefined && (isNaN(filters.maxYear) || filters.maxYear < 1000 || filters.maxYear > 2100)) {
      throw new ValidationError('maxYear must be between 1000 and 2100');
    }

    if (filters.minRating !== undefined && (isNaN(filters.minRating) || filters.minRating < 0 || filters.minRating > 5)) {
      throw new ValidationError('minRating must be between 0 and 5');
    }

    // Get filtered books from data layer
    const books = getAllBooks(filters);

    // Return successful response with 200 OK status
    res.json({
      success: true,
      count: books.length,
      data: books
    });
  } catch (error) {
    // Pass error to global error handler middleware
    next(error);
  }
});

/**
 * GET /books/stats - Return statistics about the book collection.
 * 
 * This endpoint provides aggregate information about all books in the system.
 */
router.get('/stats', (req, res) => {
  try {
    const stats = getStatistics();

    res.json({
      success: true,
      data: stats
    });
  } catch (error) {
    next(error);
  }
});

/**
 * GET /books/:id - Get a single book by its ID.
 * 
 * @param {string} id - The numeric ID of the book (from URL parameter)
 */
router.get('/:id', (req, res) => {
  try {
    // Parse the ID from the URL and convert to number
    const id = parseInt(req.params.id);

    // Validate that ID is a valid number
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format');
    }

    // Retrieve the book from data layer
    const book = getBookById(id);

    // If not found, throw NotFoundError (will be caught by error handler)
    if (!book) {
      throw new NotFoundError('Book');
    }

    // Return successful response with 200 OK status
    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error);
  }
});

/**
 * POST /books - Create a new book.
 * 
 * REQUEST BODY EXAMPLE:
 * {
 *   "title": "The Hobbit",
 *   "author": "J.R.R. Tolkien",
 *   "year": 1937,
 *   "genre": "Fantasy",
 *   "rating": 4.8
 * }
 */
router.post('/', (req, res) => {
  try {
    // Extract book data from request body
    const { title, author, year, genre, rating } = req.body;

    // Validate required fields
    if (!title || !author || !year) {
      throw new ValidationError('Title, author, and year are required');
    }

    // Validate year is a valid number in reasonable range
    const yearNum = parseInt(year);
    if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
      throw new ValidationError('Year must be between 1000 and 2100');
    }

    // Validate rating if provided
    const ratingNum = parseFloat(rating);
    if (rating !== undefined && (isNaN(ratingNum) || ratingNum < 0 || ratingNum > 5)) {
      throw new ValidationError('Rating must be between 0 and 5');
    }

    // Create the book in data layer
    const newBook = createBook({
      title,
      author,
      year: yearNum,
      genre,
      rating: rating !== undefined ? ratingNum : 0
    });

    // Return successful response with 201 Created status
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    next(error);
  }
});

/**
 * PUT /books/:id - Update an existing book.
 * 
 * REQUEST BODY EXAMPLE:
 * {
 *   "title": "The Lord of the Rings",
 *   "rating": 5.0
 * }
 */
router.put('/:id', (req, res) => {
  try {
    // Parse the ID from the URL
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format');
    }

    // Check if book exists before attempting update
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book');
    }

    // Extract updates from request body
    const updates = req.body;

    // Validate year if provided
    if (updates.year !== undefined) {
      const yearNum = parseInt(updates.year);
      if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
        throw new ValidationError('Year must be between 1000 and 2100');
      }
      updates.year = yearNum;
    }

    // Validate rating if provided
    if (updates.rating !== undefined) {
      const ratingNum = parseFloat(updates.rating);
      if (isNaN(ratingNum) || ratingNum < 0 || ratingNum > 5) {
        throw new ValidationError('Rating must be between 0 and 5');
      }
      updates.rating = ratingNum;
    }

    // Perform the update in data layer
    const updatedBook = updateBook(id, updates);

    // Return successful response with 200 OK status
    res.json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

/**
 * DELETE /books/:id - Delete a book by its ID.
 */
router.delete('/:id', (req, res) => {
  try {
    // Parse the ID from the URL
    const id = parseInt(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format');
    }

    // Check if book exists before attempting deletion
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book');
    }

    // Delete the book from data layer
    const deleted = deleteBook(id);

    // Return successful response with 204 No Content status
    // (204 means success but no content in response body)
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

**Why async/await?** While these handlers don't use database calls (which would be async), using async functions prepares the code for future migration to a real database. It also makes error handling cleaner with try/catch blocks instead of promise chains.

