## File 6: src/server.js

```javascript
/**
 * @fileoverview Main server entry point for the Express application.
 * 
 * DESIGN DECISIONS:
 * - We use express.json() middleware to parse JSON request bodies.
 * - Routes are mounted on the /api/v1 prefix for future versioning.
 * - The error handler is registered last to catch all errors.
 */

const express = require('express');
const path = require('path');

// Import our route handlers and error middleware
const bookRoutes = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');

// Create Express application instance
const app = express();

// Set port for the server (default to 3000 if not specified in environment)
const PORT = process.env.PORT || 3000;

/**
 * MIDDLEWARE CONFIGURATION:
 * 
 * Middleware functions are executed in the order they are registered.
 * Each middleware has access to req, res, and next parameters.
 */

// Parse JSON request bodies (required for POST/PUT requests)
app.use(express.json());

// Log every request for debugging (in production, use a proper logging service)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

/**
 * ROUTE MOUNTING:
 * 
 * We mount book routes on /api/v1/books to allow for future API versioning.
 * If we later create v2 of the API, we can use /api/v2/books without breaking existing clients.
 */
app.use('/api/v1/books', bookRoutes);

// Root endpoint for health checks
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book Management API is running',
    endpoints: {
      books: '/api/v1/books',
      stats: '/api/v1/books/stats'
    }
  });
});

/**
 * ERROR HANDLING MIDDLEWARE:
 * 
 * This must be registered AFTER all routes and other middleware.
 * Express recognizes error-handling middleware by its 4-parameter signature.
 */
app.use(errorHandler);

// Start the server and listen on the specified port
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`API available at http://localhost:${PORT}/api/v1/books`);
});

module.exports = app; // Export for testing purposes
```

**Why mount routes on /api/v1?** Versioning your API allows you to make breaking changes in the future without disrupting existing clients. The `/v1/` prefix makes this explicit and professional.

