```javascript
/**
 * ============================================================
 * MODEL: Livro (Armazenamento em Memória)
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ---------------------------------
 * Para este exemplo educacional, optamos por armazenar os livros
 * em um array simples dentro do módulo. Isso nos permite focar nos
 * conceitos de REST, roteamento e tratamento de erros sem a
 * complexidade adicional de um banco de dados. Em uma aplicação
 * real, substituiríamos esta camada por um ORM (como Sequelize ou
 * Prisma) conectado a PostgreSQL, MongoDB, etc.
 *
 * POR QUE USAR LET AO INVÉS DE CONST PARA O ARRAY?
 * -------------------------------------------------
 * O array em si é reatribuído raramente, mas usamos 'let' porque
 * queremos que as funções do módulo possam modificar o conteúdo
 * do array (push, splice) sem precisar reatribuir a variável.
 * Na prática, poderíamos usar const + métodos mutadores do array,
 * mas let deixa mais explícito que o estado interno é mutável.
 *
 * POR QUE CADA LIVRO TEM UM ID NUMÉRICO AUTOMÁTICO?
 * -------------------------------------------------
 * IDs numéricos autoincrementais são simples de entender e gerar.
 * Em produção, UUIDs ou ObjectId seriam preferíveis para evitar
 * colisões em sistemas distribuídos. Aqui, mantemos a simplicidade.
 */

// Array que armazena todos os livros em memória.
// Inicializamos vazio; os dados serão populados via POST.
let livros = [];

// Contador interno para gerar IDs únicos e sequenciais.
// Usamos let porque este valor será incrementado a cada novo livro criado.
let proximoId = 1;

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de todos os livros.
 */
function listarTodos() {
  return livros;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * Utilizamos Array.prototype.find(), que percorre o array e retorna
 * o PRIMEIRO elemento cuja função de teste retornar true. É mais
 * eficiente que filter + [0] porque para quando encontra o primeiro
 * match, em vez de criar um novo array com todos os matches.
 *
 * @param {number} id - O ID numérico do livro a ser buscado.
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir.
 */
function buscarPorId(id) {
  return livros.find(livro => livro.id === id);
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * A função gera automaticamente um ID único usando o contador
 * interno, garantindo que cada livro tenha um identificador
 * exclusivo sem necessidade de validação externa.
 *
 * @param {Object} dadosLivro - Objeto contendo título, autor e ano do livro.
 * @param {string} dadosLivro.titulo - Título do livro (obrigatório).
 * @param {string} dadosLivro.autor - Autor do livro (obrigatório).
 * @param {number} dadosLivro.ano - Ano de publicação (opcional, padrão 0).
 * @returns {Object} O novo livro criado com ID atribuído.
 */
function criarLivro(dadosLivro) {
  const novoLivro = {
    id: proximoId++,          // Atribui o ID atual e incrementa para o próximo
    titulo: dadosLivro.titulo,
    autor: dadosLivro.autor,
    ano: dadosLivro.ano || 0  // Fallback para 0 se não fornecido
  };

  livros.push(novoLivro);     // Adiciona ao final do array (O(1))
  return novoLivro;
}

/**
 * Atualiza um livro existente pelo seu ID.
 *
 * Utilizamos Object.assign() para mesclar as propriedades existentes
 * com os novos valores, permitindo atualizações parciais (PATCH-like).
 * Se o livro não existir, retornamos undefined.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} dadosAtualizados - Campos a serem atualizados.
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado.
 */
function atualizarLivro(id, dadosAtualizados) {
  const indice = livros.findIndex(livro => livro.id === id);

  if (indice === -1) {
    return undefined;         // Livro não encontrado
  }

  // Mescla os dados existentes com os novos (atualização parcial)
  livros[indice] = {
    ...livros[indice],        // Espalha as propriedades existentes
    ...dadosAtualizados       // Sobrescreve com os novos valores
  };

  return livros[indice];
}

/**
 * Remove um livro do array pelo seu ID.
 *
 * Utilizamos Array.prototype.splice() para remover o elemento na
 * posição encontrada. splice é preferível a filter aqui porque
 * remove o elemento no lugar (in-place), evitando a criação de
 * um novo array completo.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} True se o livro foi encontrado e removido, false caso contrário.
 */
function removerLivro(id) {
  const indice = livros.findIndex(livro => livro.id === id);

  if (indice === -1) {
    return false;             // Livro não encontrado
  }

  livros.splice(indice, 1);   // Remove 1 elemento na posição encontrada
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * Utilizamos Array.prototype.reduce() para percorrer o array uma
 * única vez e acumular todas as métricas desejadas. Esta é a forma
 * mais eficiente de calcular múltiplas estatísticas simultaneamente,
 * pois evita múltiplos loops (map/reduce separados).
 *
 * @returns {Object} Estatísticas do acervo: total, média de anos, livros por autor.
 */
function calcularEstatisticas() {
  return livros.reduce(
    (acumulador, livro) => {
      // Incrementa o contador total
      acumulador.total++;

      // Acumula os anos para cálculo da média posterior
      acumulador.somaAnos += livro.ano;

      // Conta quantos livros cada autor tem
      if (!acumulador.porAutor[livro.autor]) {
        acumulador.porAutor[livro.autor] = 0;
      }
      acumulador.porAutor[livro.autor]++;

      return acumulador;        // Retorna o acumulador para a próxima iteração
    },
    {                          // Valor inicial do acumulador
      total: 0,
      somaAnos: 0,
      porAutor: {}
    }
  );
}

/**
 * Exporta todas as funções do módulo usando CommonJS.
 *
 * Usamos exports em vez de module.exports = {...} porque queremos
 * permitir que outros módulos importem apenas as funções de que
 * precisam (importação seletiva), tornando o código mais legível.
 */
module.exports = {
  listarTodos,
  buscarPorId,
  criarLivro,
  atualizarLivro,
  removerLivro,
  calcularEstatisticas
};
