## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Tratamento de Erros Personalizado
 * ============================================================
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ---------------------------------------
 * Classes de erro personalizadas permitem que diferenciamos tipos
 * específicos de erros (404, 400, 500) e retornemos respostas JSON
 * consistentes com mensagens claras. Isso é fundamental para APIs
 * REST, onde o cliente precisa entender exatamente o que deu errado.
 *
 * POR QUE UM MIDDLEWARE DE ERRO COM 4 PARÂMETROS?
 * -----------------------------------------------
 * Express identifica middlewares de erro pela assinatura:
 * (err, req, res, next) => {...}. Os 4 parâmetros são obrigatórios;
 * se você omitir o 'next', Express trata como middleware normal.
 * Este middleware deve estar SEMPRE no final da cadeia de uso,
 * após todas as rotas, para capturar erros não tratados.
 */

/**
 * Classe base para erros personalizados da API.
 *
 * Estendemos Error para herdar o stack trace nativo do JavaScript,
 * mas adicionamos propriedades customizadas (statusCode e isOperacional)
 * que nos permitem classificar o erro no middleware de tratamento.
 *
 * @param {string} message - Mensagem descritiva do erro.
 * @param {number} statusCode - Código HTTP a ser retornado ao cliente.
 */
class ApiError extends Error {
  constructor(message, statusCode) {
    super(message);           // Chama o construtor da classe Error pai

    this.statusCode = statusCode;
    this.isOperacional = true;  // Marca como erro esperado da aplicação (não bug)

    // Mantém o stack trace correto mesmo com a herança customizada
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Middleware principal de tratamento de erros.
 *
 * Este middleware captura todos os erros que passam para o next(err)
 * e retorna uma resposta JSON padronizada. Ele deve ser registrado
 * APÓS todas as rotas para funcionar corretamente.
 *
 * @param {Error} err - O erro capturado.
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função next do Express (não usada aqui).
 */
function errorHandler(err, req, res, next) {
  // Se for um erro operacional da API, retorna o status e mensagem definidos
  if (err.isOperacional) {
    return res.status(err.statusCode).json({
      status: 'erro',
      codigo: err.statusCode,
      mensagem: err.message
    });
  }

  // Para erros não previstos (bugs), logamos no servidor e retornamos 500
  console.error('❌ ERRO NÃO TRATADO:', err);
  return res.status(500).json({
    status: 'erro',
    codigo: 500,
    mensagem: 'Erro interno do servidor. Tente novamente mais tarde.'
  });
}

/**
 * Exporta a classe de erro e o middleware.
 */
module.exports = { ApiError, errorHandler };
```

