## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS: Gerenciamento de Livros (RESTful)
 * ============================================================
 *
 * POR QUE USAR EXPRESS.ROUTER()?
 * ------------------------------
 * O Express.Router() permite agrupar rotas relacionadas em um
 * módulo separado, mantendo o app principal limpo e organizado.
 * Cada rota é uma função que recebe (req, res, next), seguindo
 * o padrão de middlewares do Express.
 *
 * POR QUE USAR ASYNC/AWAIT?
 * -------------------------
 * Async/await torna o código assíncrono mais legível, evitando
 * o "callback hell" e facilitando o fluxo linear de leitura.
 * Mesmo que as operações em memória sejam síncronas neste exemplo,
 * usamos async/await para demonstrar o padrão que seria usado
 * com banco de dados (onde as operações são naturalmente assíncronas).
 *
 * POR QUE PADRÃO REST?
 * --------------------
 * - GET    /books      → Listar todos (com filtragem opcional)
 * - GET    /books/:id   → Obter um específico
 * - POST   /books       → Criar novo
 * - PUT    /books/:id   → Atualizar completo (substituição)
 * - DELETE /books/:id   → Remover
 * - GET    /stats       → Estatísticas agregadas
 *
 * Cada método HTTP tem um significado semântico claro:
 * GET = leitura segura, POST = criação, PUT = atualização total,
 * DELETE = remoção. Isso permite que qualquer desenvolvedor entenda
 * a API apenas olhando para as URLs e métodos HTTP.
 */

const express = require('express');
const router = express.Router();  // Cria um roteador independente

// Importa o modelo de dados (camada de persistência)
const {
  listarTodos,
  buscarPorId,
  criarLivro,
  atualizarLivro,
  removerLivro,
  calcularEstatisticas
} = require('../models/book');

// Importa a classe de erro personalizada
const { ApiError } = require('../middleware/errorHandler');

// ============================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================
/**
 * Lista todos os livros com suporte a filtragem por query parameters.
 *
 * Filtros disponíveis:
 *   - ?autor=nome        → Filtra por autor (case-insensitive)
 *   - ?ano=2020          → Filtra por ano exato de publicação
 *   - ?titulo=palavra    → Busca parcial no título
 *
 * Exemplo de uso:
 *   curl http://localhost:3000/books?autor=Machado&ano=1881
 *
 * @route GET /books
 * @access Public
 */
router.get('/books', (req, res, next) => {
  try {
    // Obtém todos os livros do modelo
    let resultado = listarTodos();

    // Aplica filtragem por autor se o parâmetro for fornecido
    if (req.query.autor) {
      const autorBusca = req.query.autor.toLowerCase();
      resultado = resultado.filter(
        livro => livro.autor.toLowerCase().includes(autorBusca)
      );
    }

    // Aplica filtragem por ano se o parâmetro for fornecido
    if (req.query.ano) {
      const anoBusca = parseInt(req.query.ano, 10);
      resultado = resultado.filter(livro => livro.ano === anoBusca);
    }

    // Aplica filtragem por título (busca parcial) se o parâmetro for fornecido
    if (req.query.titulo) {
      const tituloBusca = req.query.titulo.toLowerCase();
      resultado = resultado.filter(
        livro => livro.titulo.toLowerCase().includes(tituloBusca)
      );
    }

    // Retorna os livros filtrados com status 200 (OK)
    res.json({
      status: 'sucesso',
      total: resultado.length,
      dados: resultado
    });
  } catch (erro) {
    next(erro);  // Passa o erro para o middleware de tratamento
  }
});

// ============================================================
// GET /books/stats — Estatísticas do acervo
// ============================================================
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * As estatísticas incluem:
 *   - total: quantidade total de livros
 *   - mediaAnos: média dos anos de publicação
 *   - porAutor: distribuição de livros por autor
 *
 * Exemplo de uso:
 *   curl http://localhost:3000/books/stats
 *
 * @route GET /books/stats
 * @access Public
 */
router.get('/books/stats', (req, res, next) => {
  try {
    const stats = calcularEstatisticas();

    // Calcula a média dos anos, evitando divisão por zero
    const mediaAnos = stats.total > 0
      ? Math.round(stats.somaAnos / stats.total)
      : 0;

    res.json({
      status: 'sucesso',
      dados: {
        totalLivros: stats.total,
        mediaAnosPublicacao: mediaAnos,
        livrosPorAutor: stats.porAutor
      }
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// GET /books/:id — Obter livro por ID
// ============================================================
/**
 * Busca um livro específico pelo seu ID numérico.
 *
 * Exemplo de uso:
 *   curl http://localhost:3000/books/1
 *
 * @route GET /books/:id
 * @access Public
 */
router.get('/books/:id', (req, res, next) => {
  try {
    // Converte o ID da URL para número (strings de URL são sempre strings)
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ApiError('ID inválido. Deve ser um número.', 400);
    }

    // Busca o livro no modelo
    const livro = buscarPorId(id);

    // Se não encontrado, lança erro 404 personalizado
    if (!livro) {
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 404);
    }

    res.json({
      status: 'sucesso',
      dados: livro
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// POST /books — Criar novo livro
// ============================================================
/**
 * Cria um novo livro no acervo.
 *
 * O corpo da requisição deve conter:
 *   - titulo (string, obrigatório)
 *   - autor (string, obrigatório)
 *   - ano (number, opcional, padrão 0)
 *
 * Exemplo de uso com curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"titulo":"Dom Casmurro","autor":"Machado de Assis","ano":1899}'
 *
 * @route POST /books
 * @access Public
 */
router.post('/books', (req, res, next) => {
  try {
    const { titulo, autor, ano } = req.body;

    // Validação: título é obrigatório
    if (!titulo || titulo.trim() === '') {
      throw new ApiError('O campo "titulo" é obrigatório.', 400);
    }

    // Validação: autor é obrigatório
    if (!autor || autor.trim() === '') {
      throw new ApiError('O campo "autor" é obrigatório.', 400);
    }

    // Validação: ano, se fornecido, deve ser um número válido
    if (ano !== undefined && (isNaN(ano) || ano < 0)) {
      throw new ApiError('O campo "ano" deve ser um número positivo.', 400);
    }

    // Cria o livro no modelo
    const novoLivro = criarLivro({ titulo, autor, ano: ano || 0 });

    // Retorna 201 (Created) com o livro criado — padrão REST para criação
    res.status(201).json({
      status: 'sucesso',
      mensagem: 'Livro criado com sucesso!',
      dados: novoLivro
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// PUT /books/:id — Atualizar livro existente
// ============================================================
/**
 * Atualiza completamente um livro existente pelo seu ID.
 *
 * Todos os campos devem ser fornecidos na requisição:
 *   - titulo (string, obrigatório)
 *   - autor (string, obrigatório)
 *   - ano (number, opcional)
 *
 * Exemplo de uso com curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"titulo":"Memórias Póstumas","autor":"Machado de Assis","ano":1899}'
 *
 * @route PUT /books/:id
 * @access Public
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ApiError('ID inválido. Deve ser um número.', 400);
    }

    const { titulo, autor, ano } = req.body;

    // Validação: todos os campos obrigatórios
    if (!titulo || titulo.trim() === '') {
      throw new ApiError('O campo "titulo" é obrigatório.', 400);
    }
    if (!autor || autor.trim() === '') {
      throw new ApiError('O campo "autor" é obrigatório.', 400);
    }

    // Busca o livro antes de atualizar (para verificar existência)
    const livroExistente = buscarPorId(id);
    if (!livroExistente) {
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 400);
    }

    // Atualiza o livro no modelo
    const livroAtualizado = atualizarLivro(id, { titulo, autor, ano: ano || 0 });

    res.json({
      status: 'sucesso',
      mensagem: 'Livro atualizado com sucesso!',
      dados: livroAtualizado
    });
  } catch (erro) {
    next(erro);
  }
});

// ============================================================
// DELETE /books/:id — Excluir livro
// ============================================================
/**
 * Remove um livro do acervo pelo seu ID.
 *
 * Exemplo de uso com curl:
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * @route DELETE /books/:id
 * @access Public
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ApiError('ID inválido. Deve ser um número.', 400);
    }

    // Tenta remover o livro no modelo
    const removido = removerLivro(id);

    // Se não foi encontrado, retorna 404
    if (!removido) {
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 404);
    }

    // Retorna 204 (No Content) — padrão REST para remoção bem-sucedida
    res.status(204).end();
  } catch (erro) {
    next(erro);
  }
});

// Exporta o roteador para ser usado no app principal
module.exports = router;
```

