## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * APP PRINCIPAL: Configuração e Inicialização da API
 * ============================================================
 *
 * POR QUE SEPARAR ROTEAMENTO DO APP?
 * ----------------------------------
 * Manter as rotas em um arquivo separado (routes/books.js) permite
 * que o app principal se concentre na configuração global (middlewares,
 * CORS, body-parser) enquanto as rotas ficam organizadas por domínio.
 * Esta separação de responsabilidades é um princípio fundamental do
 * design de software: cada módulo deve ter uma única razão para mudar.
 *
 * POR QUE USAR express.json() E express.urlencoded()?
 * ---------------------------------------------------
 * O Express não faz parsing automático do corpo das requisições.
 * express.json() parseia bodies com Content-Type: application/json,
 * enquanto express.urlencoded() lida com formulários HTML (form-data).
 * Sem esses middlewares, req.body seria undefined em requisições POST/PUT.
 */

const express = require('express');
const app = express();               // Cria a instância do aplicativo Express
const PORTA = 3000;                  // Porta padrão para o servidor

// ============================================================
// MIDDLEWARES GLOBAIS (executados antes de qualquer rota)
// ============================================================

/**
 * Middleware: Parser do corpo da requisição.
 *
 * express.json() converte automaticamente bodies JSON em objetos
 * JavaScript acessíveis via req.body. Sem este middleware, não
 * conseguiríamos acessar os dados enviados nos métodos POST e PUT.
 */
app.use(express.json());

/**
 * Middleware: Parser de formulários (x-www-form-urlencoded).
 *
 * Permite que requisições com Content-Type: application/x-www-form-urlencoded
 * tenham seu corpo parseado corretamente. Útil para testes com formulários HTML.
 */
app.use(express.urlencoded({ extended: true }));

/**
 * Middleware: CORS (Cross-Origin Resource Sharing).
 *
 * Habilita requisições de qualquer origem (*). Em produção, substitua '*'
 * pela lista específica de domínios autorizados por segurança.
 * Sem este middleware, navegadores bloqueariam requisições da API
 * vindas de origens diferentes (ex: frontend rodando em porta diferente).
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Middleware: Log de requisições.
 *
 * Registra no console o método HTTP, URL e timestamp de cada requisição.
 * Esta é uma prática essencial para debugging e monitoramento.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Rota raiz: informa que a API está no ar.
 *
 * @route GET /
 */
app.get('/', (req, res) => {
  res.json({
    status: 'sucesso',
    mensagem: 'API de Livros — exemplo educacional Node.js + Express.js',
    endpoints: {
      'GET    /books':        'Listar todos os livros (com filtragem opcional)',
      'GET    /books/stats':  'Estatísticas do acervo',
      'GET    /books/:id':    'Obter livro por ID',
      'POST   /books':        'Criar novo livro',
      'PUT    /books/:id':    'Atualizar livro existente',
      'DELETE /books/:id':    'Excluir livro'
    }
  });
});

/**
 * Importa e registra o roteador de livros.
 *
 * Todas as rotas definidas em routes/books.js ficam disponíveis
 * sob o prefixo '/books'. Esta abordagem permite ter múltiplos
 * roteadores (ex: /usuarios, /autores) no futuro sem conflitos.
 */
const rotasLivros = require('./routes/books');
app.use('/books', rotasLivros);

// ============================================================
// ROTA 404 — Tratamento de rotas inexistentes
// ============================================================
/**
 * Middleware: Responde com 404 para qualquer rota não definida.
 *
 * Este middleware deve vir APÓS todas as rotas definidas, caso contrário
 * capturaria todas as requisições antes que chegassem às rotas reais.
 */
app.use((req, res) => {
  res.status(404).json({
    status: 'erro',
    codigo: 404,
    mensagem: `Rota ${req.method} ${req.url} não encontrada.`
  });
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// ============================================================
/**
 * Middleware de tratamento de erros global.
 *
 * Deve ser o ÚLTIMO middleware registrado. Express identifica middlewares
 * de erro pela assinatura de 4 parâmetros (err, req, res, next).
 * Qualquer erro passado para next(err) será capturado aqui.
 */
const { errorHandler } = require('./middleware/errorHandler');
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================
app.listen(PORTA, () => {
  console.log(`\n✅ Servidor rodando em http://localhost:${PORTA}`);
  console.log(`📚 API de Livros — exemplo educacional\n`);
});
