## File 2: `errors.js` — Custom Error Classes & Middleware

```javascript
/**
 * errors.js
 *
 * This module defines custom error classes that extend JavaScript's built-in
 * Error class, and an Express middleware function that catches all errors and
 * returns a consistent JSON response.
 *
 * WHY custom error classes?
 *   - They carry extra metadata (statusCode, isOperational) so the error handler
 *     can differentiate between programmer bugs (500) and client mistakes (4xx).
 *   - They make debugging easier: `error instanceof NotFoundError` is clearer than
 *     checking string messages.
 *
 * WHY a centralized error middleware?
 *   - Express allows you to define an error-handling function with 4 parameters
 *     (err, req, res, next). Placing it last in the middleware stack ensures ALL
 *     unhandled errors — whether thrown synchronously or passed via next(err) —
 *     flow through one place. This prevents leaking stack traces to clients.
 */

/**
 * AppError — Base class for all application-level errors.
 *
 * Extends Error so it integrates with JavaScript's native error system (try/catch,
 * instanceof checks, etc.). We add `statusCode` and `isOperational` as custom
 * properties. "Operational" means the error was expected (e.g., user sent bad data)
 * rather than a programming bug.
 */
class AppError extends Error {
  /**
   * @param {string} message — Human-readable description of the error.
   * @param {number} statusCode — HTTP status code to return (default: 400).
   */
  constructor(message, statusCode = 400) {
    super(message); // Call parent Error constructor with the message.

    this.statusCode = statusCode;
    // isOperational = true means this error was caused by external input or
    // expected conditions (not a bug in our code). We log these but don't alert.
    this.isOperational = true;

    // Capture the stack trace for debugging, but we won't send it to clients.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * NotFoundError — Thrown when a requested resource doesn't exist.
 *
 * Extends AppError with a default status code of 404 (Not Found).
 */
class NotFoundError extends AppError {
  constructor(resource) {
    // "resource" is a string like 'Book' or 'User' — we interpolate it into the message.
    super(`${resource} not found`, 404);
  }
}

/**
 * ValidationError — Thrown when client input fails validation.
 *
 * Extends AppError with a default status code of 422 (Unprocessable Entity).
 * We also store `details` so the client knows exactly which fields failed.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message — General error description.
   * @param {Array<{field: string, message: string}>} details — Specific field errors.
   */
  constructor(message, details = []) {
    super(message, 422);
    this.details = details; // Array of {field, message} objects for the client.
  }
}

/**
 * InternalError — Thrown for unexpected server-side failures.
 *
 * Extends AppError with a default status code of 500 (Internal Server Error).
 * These are logged fully but only a generic message is sent to clients.
 */
class InternalError extends AppError {
  constructor(message) {
    super(message, 500);
    // isOperational = false means this is a bug — we should alert the team.
    this.isOperational = false;
  }
}

/**
 * errorHandler — Express middleware that catches all errors and returns JSON.
 *
 * WHY 4 parameters? Express identifies error middleware by its signature:
 *   function (err, req, res, next) => { ... }
 * If you omit any parameter, Express treats it as a regular middleware.
 *
 * WHAT this does:
 *   1. If the error is operational (client-side), return its statusCode + message.
 *   2. If the error is NOT operational (server bug), log the full stack trace and
 *      return a generic 500 response to avoid leaking internals.
 *   3. For validation errors, include the `details` array so clients can fix fields.
 */
function errorHandler(err, req, res, next) {
  // Log the error with its status code for server-side debugging.
  console.error(`[ERROR] ${err.statusCode || 500} — ${err.message}`);

  // Build a consistent JSON response shape regardless of error type.
  const response = {
    success: false,
    error: {
      message: err.isOperational ? err.message : 'Internal server error',
    },
  };

  // Include validation details if this is a ValidationError.
  if (err.details && Array.isArray(err.details)) {
    response.error.details = err.details;
  }

  // Send the appropriate status code and JSON body.
  res.status(err.statusCode || 500).json(response);
}

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  InternalError,
  errorHandler,
};
```

