## File 3: `data.js` — In-Memory Data Store

```javascript
/**
 * data.js
 *
 * This module manages the in-memory array that acts as our "database."
 *
 * WHY an in-memory array?
 *   - For an educational example, it keeps the code simple and runnable without
 *     installing a database. In production, you'd replace this with MongoDB,
 *     PostgreSQL, etc., but the route logic would look nearly identical.
 *   - Arrays are fast for small datasets and make filtering/sorting easy to demonstrate.
 *
 * WHY seed data?
 *   - So the API isn't empty when you first start it. Real apps load from a DB;
 *     here we simulate that with a few sample books.
 */

/**
 * Book schema (what each book object looks like):
 * {
 *   id: number,          // Unique identifier (auto-incremented)
 *   title: string,       // Book title (required)
 *   author: string,      // Author name (required)
 *   year: number,        // Publication year (required, 1000–current year)
 *   genre: string,       // Genre category (required, one of predefined values)
 *   available: boolean   // Whether the book is currently check-out-able
 * }
 */

// Start with an auto-incrementing ID counter.
let nextId = 4;

/**
 * books — The in-memory array storing all book records.
 *
 * We use `let` (not `const`) because we may reassign the entire array in a
 * reset function, but more importantly, we mutate it via push/splice/filter.
 */
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    year: 1925,
    genre: 'Fiction',
    available: true,
  },
  {
    id: 2,
    title: 'Clean Code',
    author: 'Robert C. Martin',
    year: 2008,
    genre: 'Technology',
    available: false,
  },
  {
    id: 3,
    title: 'Dune',
    author: 'Frank Herbert',
    year: 1965,
    genre: 'Science Fiction',
    available: true,
  },
];

/**
 * getAllBooks — Returns a copy of the entire books array.
 *
 * WHY return a copy? Returning the original array would let external code mutate
 * our internal state directly. A shallow copy (spread operator) prevents this.
 */
function getAllBooks() {
  return [...books];
}

/**
 * getBookById — Finds a book by its numeric ID.
 *
 * @param {number} id — The unique identifier of the book to find.
 * @returns {object|null} The book object if found, null otherwise.
 */
function getBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * addBook — Creates a new book and pushes it into the array.
 *
 * @param {object} bookData — The book object to add (without an `id` field).
 * @returns {object} The newly created book with its assigned ID.
 */
function addBook(bookData) {
  const newBook = {
    id: nextId++, // Assign the current counter value, then increment for next time.
    ...bookData,  // Spread in all provided fields (title, author, etc.).
  };
  books.push(newBook);
  return newBook;
}

/**
 * updateBook — Replaces a book's data by ID.
 *
 * @param {number} id — The ID of the book to update.
 * @param {object} updates — Fields to overwrite (partial update).
 * @returns {object|null} The updated book, or null if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Create a new object with old data + overwritten fields.
  // This is safer than mutating in place because it avoids reference issues.
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * deleteBook — Removes a book from the array by ID.
 *
 * @param {number} id — The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove exactly one element at the given index.
  return true;
}

/**
 * getStats — Computes aggregate statistics about the current book collection.
 *
 * @returns {object} Statistics including total count, available count, average year, and genre distribution.
 */
function getStats() {
  const total = books.length;
  const available = books.filter((b) => b.available).length;
  const avgYear =
    total > 0
      ? Math.round(books.reduce((sum, b) => sum + b.year, 0) / total)
      : 0;

  // Count how many books exist per genre.
  const genres = {};
  books.forEach((b) => {
    genres[b.genre] = (genres[b.genre] || 0) + 1;
  });

  return {
    total,
    available,
    unavailable: total - available,
    averageYear: avgYear,
    genreDistribution: genres,
  };
}

module.exports = {
  getAllBooks,
  getBookById,
  addBook,
  updateBook,
  deleteBook,
  getStats,
};
```

