## File 4: `routes/books.js` — Book Routes

```javascript
/**
 * routes/books.js
 *
 * This module defines all REST endpoints for the /books resource.
 *
 * WHY separate route file? Keeping routes in their own file makes the main
 * server.js lean and lets you scale to multiple resources (authors, users) easily.
 *
 * WHAT is REST?
 *   - GET    /books       → List all books (with optional query filters)
 *   - GET    /books/:id   → Get one book by ID
 *   - POST   /books       → Create a new book
 *   - PUT    /books/:id   → Fully replace a book's data
 *   - DELETE /books/:id   → Remove a book
 *
 * WHY async/await? Even though this is in-memory, using async functions:
 *   1. Makes the code ready for database integration later (DB calls are async).
 *   2. Keeps error handling clean with try/catch instead of .catch() chains.
 *   3. Is the modern JavaScript standard — it's what you'll see in real projects.
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler.

// Import our data layer and error classes.
const { getAllBooks, getBookById, addBook, updateBook, deleteBook } = require('../data');
const { NotFoundError, ValidationError } = require('../errors');

/**
 * Valid genre values — used for input validation.
 */
const VALID_GENRES = ['Fiction', 'Non-Fiction', 'Science Fiction', 'Fantasy', 'Mystery', 'Technology', 'Biography', 'History'];

/**
 * validateBookInput — Checks that a book object has all required fields with correct types.
 *
 * @param {object} data — The incoming request body.
 * @returns {Array<{field: string, message: string}>} Array of validation errors (empty if valid).
 */
function validateBookInput(data) {
  const errors = [];

  // Title must be a non-empty string.
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string.' });
  }

  // Author must be a non-empty string.
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string.' });
  }

  // Year must be a number within a reasonable range.
  const year = Number(data.year);
  if (!data.year || isNaN(year) || year < 1000 || year > new Date().getFullYear()) {
    errors.push({ field: 'year', message: `Year is required and must be between 1000 and ${new Date().getFullYear()}.` });
  }

  // Genre must be one of the predefined values.
  if (!data.genre || !VALID_GENRES.includes(data.genre)) {
    errors.push({ field: 'genre', message: `Genre is required and must be one of: ${VALID_GENRES.join(', ')}.` });
  }

  return errors;
}

// ============================================================
// GET /books — List all books with optional filtering
// ============================================================
/**
 * @route   GET /books
 * @desc    Retrieve a list of all books, optionally filtered by query parameters.
 * @access  Public
 *
 * QUERY PARAMETERS (all optional):
 *   - genre      : Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author     : Filter by author name substring (case-insensitive)
 *   - available  : Filter by availability ("true" or "false")
 *   - yearFrom   : Minimum publication year (inclusive)
 *   - yearTo     : Maximum publication year (inclusive)
 *
 * EXAMPLE: GET /books?genre=Technology&available=true
 */
router.get('/', async (req, res, next) => {
  try {
    // Destructure query parameters with defaults.
    const { genre, author, available, yearFrom, yearTo } = req.query;

    // Start with the full list, then apply filters one by one.
    let result = getAllBooks();

    if (genre) {
      result = result.filter((book) => book.genre === genre);
    }
    if (author) {
      const lowerAuthor = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(lowerAuthor));
    }
    if (available !== undefined) {
      const isAvailable = available === 'true';
      result = result.filter((book) => book.available === isAvailable);
    }
    if (yearFrom) {
      result = result.filter((book) => book.year >= Number(yearFrom));
    }
    if (yearTo) {
      result = result.filter((book) => book.year <= Number(yearTo));
    }

    // Return 200 with the filtered list.
    res.json({ success: true, count: result.length, data: result });
  } catch (error) {
    next(error); // Pass to our centralized error handler.
  }
});

// ============================================================
// GET /books/:id — Get a single book by ID
// ============================================================
/**
 * @route   GET /books/:id
 * @desc    Retrieve a single book by its numeric ID.
 * @access  Public
 *
 * PATH PARAMETER:
 *   - id (number) : The unique identifier of the book.
 *
 * EXAMPLE: GET /books/1
 */
router.get('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Validate that the ID is a valid number.
    if (isNaN(id)) {
      return next(new ValidationError('Invalid book ID. Must be a number.', [{ field: 'id', message: 'ID must be a numeric value.' }]));
    }

    const book = getBookById(id);
    if (!book) {
      // Throw a NotFoundError so the error middleware handles it consistently.
      return next(new NotFoundError('Book'));
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// POST /books — Create a new book
// ============================================================
/**
 * @route   POST /books
 * @desc    Create a new book with the provided details.
 * @access  Public
 *
 * REQUEST BODY (JSON):
 *   - title  (string, required) : Book title
 *   - author (string, required) : Author name
 *   - year   (number, required) : Publication year
 *   - genre  (string, required) : Genre category
 *   - available (boolean, optional, default: true) : Availability status
 *
 * EXAMPLE: POST /books with body { "title": "1984", "author": "George Orwell", "year": 1949, "genre": "Fiction" }
 */
router.post('/', async (req, res, next) => {
  try {
    // Validate the incoming request body.
    const validationErrors = validateBookInput(req.body);
    if (validationErrors.length > 0) {
      return next(new ValidationError('Invalid book data.', validationErrors));
    }

    // Build the new book object, defaulting available to true if not provided.
    const newBook = addBook({
      ...req.body,
      available: req.body.available !== undefined ? req.body.available : true,
    });

    // 201 Created is the correct status for a newly created resource.
    res.status(201).json({ success: true, data: newBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// PUT /books/:id — Fully update an existing book
// ============================================================
/**
 * @route   PUT /books/:id
 * @desc    Replace all fields of an existing book.
 * @access  Public
 *
 * PATH PARAMETER:
 *   - id (number) : The unique identifier of the book to update.
 *
 * REQUEST BODY (JSON): Same schema as POST /books.
 *
 * NOTE: PUT is a FULL replacement — all required fields must be present.
 *       For partial updates, use PATCH instead (not implemented here).
 *
 * EXAMPLE: PUT /books/1 with body { "title": "The Great Gatsby (Updated)", "author": "F. Scott Fitzgerald", "year": 1925, "genre": "Fiction" }
 */
router.put('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return next(new ValidationError('Invalid book ID.', [{ field: 'id', message: 'ID must be a numeric value.' }]));
    }

    // Validate the incoming data before attempting update.
    const validationErrors = validateBookInput(req.body);
    if (validationErrors.length > 0) {
      return next(new ValidationError('Invalid book data.', validationErrors));
    }

    const updatedBook = updateBook(id, req.body);
    if (!updatedBook) {
      return next(new NotFoundError('Book'));
    }

    // 200 OK with the updated resource.
    res.json({ success: true, data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================
// DELETE /books/:id — Delete a book
// ============================================================
/**
 * @route   DELETE /books/:id
 * @desc    Remove a book by its ID.
 * @access  Public
 *
 * PATH PARAMETER:
 *   - id (number) : The unique identifier of the book to delete.
 *
 * EXAMPLE: DELETE /books/2
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return next(new ValidationError('Invalid book ID.', [{ field: 'id', message: 'ID must be a numeric value.' }]));
    }

    const deleted = deleteBook(id);
    if (!deleted) {
      return next(new NotFoundError('Book'));
    }

    // 204 No Content is standard for successful DELETE (no body to return).
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

