 *     total: number,              // Total number of books
 *     available: number,          // Books currently available
 *     unavailable: number,        // Books currently checked out
 *     averageYear: number,        // Average publication year (rounded)
 *     genreDistribution: object   // Count per genre
 *   }
 * }
 *
 * EXAMPLE: GET /stats
 */
router.get('/', async (req, res, next) => {
  try {
    const stats = getStats();
    res.json({ success: true, data: stats });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
