## File 6: `server.js` — Application Entry Point

```javascript
/**
 * server.js
 *
 * This is the main entry point of our Express application. It wires together
 * all middleware, routes, and error handling into a single running server.
 *
 * WHY this order matters:
 *   1. Security middleware (helmet) first — protects headers immediately.
 *   2. Body parsing (express.json) before routes — so req.body is available.
 *   3. Routes after middleware — they can access parsed bodies and secure headers.
 *   4. Error handler LAST — it must be the final middleware in the stack.
 *
 * WHY async/await on route handlers? Even for simple operations, using async:
 *   - Makes the code consistent with future database integration.
 *   - Allows us to use try/catch cleanly instead of .catch() chains.
 *   - Is the modern standard expected by all Node.js developers.
 */

const express = require('express');
const helmet = require('helmet');       // Sets secure HTTP headers (X-Content-Type-Options, etc.)
const cors = require('cors');           // Enables Cross-Origin Resource Sharing
const compression = require('compression'); // Compresses responses with gzip

const app = express();
const PORT = process.env.PORT || 3000;  // Use env var if set, otherwise default to 3000.

// ============================================================
// Middleware Stack (order matters!)
// ============================================================

/**
 * helmet — Adds security-related HTTP headers:
 *   - X-Content-Type-Options: nosniff
 *   - X-Frame-Options: SAMEORIGIN
 *   - Strict-Transport-Security
 *   These protect against common attacks like MIME-type sniffing and clickjacking.
 */
app.use(helmet());

/**
 * cors — Allows cross-origin requests (useful for frontend apps).
 * In production, restrict this to your actual frontend domain.
 */
app.use(cors());

/**
 * compression — Gzip-compresses response bodies to reduce bandwidth.
 * Especially helpful for JSON responses on slower connections.
 */
app.use(compression());

/**
 * express.json() — Parses incoming JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests.
 * limit: '10kb' prevents abnormally large payloads (DoS protection).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Request logger — Simple middleware that logs method, URL, and timestamp.
 * In production, you'd use a library like morgan for more detailed logging.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler.
});

// ============================================================
// Routes
// ============================================================

/**
 * Import route modules. Each module exports an Express Router instance.
 */
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

/**
 * Mount routes under their respective paths.
 * All book-related endpoints live under /books.
 * Stats endpoint lives under /stats.
 */
app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

// ============================================================
// Root endpoint — Health check
// ============================================================
/**
 * @route   GET /
 * @desc    Simple health check to verify the server is running.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API is running!',
    endpoints: {
      books: '/books',
      stats: '/stats',
    },
  });
});

// ============================================================
// 404 Handler — Catch-all for undefined routes
// ============================================================
/**
 * If a request hits a route that doesn't exist, return 404.
 * This must come AFTER all defined routes but BEFORE the error handler.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./errors');
  next(new NotFoundError('Endpoint'));
});

// ============================================================
// Centralized Error Handler (MUST be last middleware)
// ============================================================
const { errorHandler } = require('./errors');
app.use(errorHandler);

// ============================================================
// Start the server
// ============================================================
app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: GET  http://localhost:${PORT}/books`);
  console.log(`        POST http://localhost:${PORT}/books`);
  console.log(`        GET  http://localhost:${PORT}/stats`);
});
```

