## Arquivo 2: `src/models/bookStore.js`

```javascript
/**
 * @fileoverview bookStore.js
 *
 * Armazenamento em memória para a API de livros.
 *
 * ESCOLHA DA ESTRUTURA DE DADOS:
 *
 * Optamos por um ARRAY em vez de um MAP/Objeto porque:
 *   1. Arrays preservam a ordem de inserção, o que é intuitivo para listagens.
 *   2. Para uma API educacional com poucos registros, a complexidade O(n) do
 *      Array.prototype.find() é perfeitamente aceitável.
 *   3. Arrays facilitam operações como filtragem e ordenação sem necessidade
 *      de iterar sobre chaves de objeto.
 *
 * Em produção real, usaríamos um banco de dados (MongoDB, PostgreSQL, etc.)
 * com índices adequados para buscas por ID e campos de filtro.
 */

/**
 * @typedef {Object} Book
 * @property {number} id - Identificador único do livro (auto-incremento).
 * @property {string} title - Título do livro (obrigatório, 1-200 caracteres).
 * @property {string} author - Autor do livro (obrigatório, 1-150 caracteres).
 * @property {number} [year] - Ano de publicação (opcional, 1000-2099).
 * @property {string} [genre] - Gênero literário (opcional, ex: "Ficção", "Não-ficção").
 * @property {boolean} [available] - Disponibilidade para empréstimo (padrão: true).
 * @property {string} createdAt - Data de criação no formato ISO 8601.
 * @property {string} updatedAt - Data da última atualização no formato ISO 8601.
 */

/**
 * Armazenamento em memória dos livros.
 * @type {Book[]}
 */
const books = [];

/**
 * Contador para geração de IDs auto-incrementáveis.
 * Usamos uma variável simples porque:
 *   - Evita colisões de ID mesmo com exclusões (IDs nunca se repetem).
 *   - É mais seguro que usar Date.now() como ID, que poderia colidir em alta carga.
 * @type {number}
 */
let nextId = 1;

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Book[]} Lista de todos os livros.
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - O ID do livro a ser encontrado.
 * @returns {Book | undefined} O livro encontrado, ou undefined se não existir.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao armazenamento.
 *
 * @param {Omit<Book, 'id' | 'createdAt' | 'updatedAt'>} bookData - Dados do livro a criar.
 * @returns {Book} O livro criado com ID, createdAt e updatedAt preenchidos.
 */
function createBook(bookData) {
  const now = new Date().toISOString();

  const newBook = {
    id: nextId++, // Incrementa o contador ANTES de atribuir (prefixo ++ garante IDs únicos)
    ...bookData,
    available: bookData.available ?? true, // Padrão: disponível se não especificado
    createdAt: now,
    updatedAt: now,
  };

  books.push(newBook); // push() é O(1) — eficiente para adição ao final
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - O ID do livro a atualizar.
 * @param {Partial<Book>} updates - Campos a serem atualizados (partial = subset dos campos).
 * @returns {Book | undefined} O livro atualizado, ou undefined se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return undefined; // Livro não encontrado
  }

  // Mescla os dados existentes com as atualizações
  books[index] = {
    ...books[index], // Preserva campos que não estão sendo atualizados
    ...updates,      // Sobrescreve com os novos valores
    id: books[index].id, // Garante que o ID não seja alterado
    updatedAt: new Date().toISOString(), // Registra a data da atualização
  };

  return books[index];
}

/**
 * Remove um livro do armazenamento pelo ID.
 *
 * @param {number} id - O ID do livro a remover.
 * @returns {boolean} true se o livro foi removido, false caso contrário.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false; // Livro não encontrado
  }

  books.splice(index, 1); // splice() remove o elemento na posição index
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas incluindo total, por gênero, disponibilidade e média de ano.
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para aggregação
  const byGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero'; // Categoria padrão para livros sem gênero
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Contagem de disponíveis vs indisponíveis
  const availableCount = books.filter((book) => book.available).length;

  // Média do ano de publicação (ignorando livros sem ano)
  const booksWithYear = books.filter((b) => b.year);
  const averageYear =
    booksWithYear.length > 0
      ? Math.round(
          booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length,
          1
        )
      : null;

  return {
    total,
    byGenre,
    available: availableCount,
    unavailable: total - availableCount,
    averagePublicationYear: averageYear,
  };
}

/**
 * Exporta todas as funções como um módulo CommonJS.
 * Usamos exports em vez de export default porque:
 *   - CommonJS é o padrão do Node.js para projetos sem bundler.
 *   - Permite named imports ({ getBookById }) que são mais explícitos.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

