## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview errorHandler.js
 *
 * Middleware de tratamento de erros personalizado.
 *
 * PADRÃO ESCOLHIDO:
 *
 * Em Express.js, middlewares de erro têm 4 parâmetros (err, req, res, next).
 * O framework os identifica automaticamente pela assinatura da função.
 * Isso permite centralizar o tratamento de erros em um único lugar,
 * evitando repetição de código em cada rota.
 */

/**
 * Classe base para erros personalizados da API.
 *
 * Herdar de Error garante que instanceof Error funcione corretamente
 * e que a pilha de execução (stack trace) seja preservada.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível para o cliente.
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500).
   * @param {string[]} [errors] - Detalhes adicionais dos erros de validação.
   */
  constructor(message, statusCode = 500, errors = null) {
    super(message); // Chama o construtor da classe Error pai

    this.statusCode = statusCode;
    this.errors = errors;

    // Captura a pilha de execução para depuração
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Erro para recursos não encontrados.
 * Convenção REST: usar 404 Not Found para recursos inexistentes.
 */
class NotFoundError extends ApiError {
  constructor(resource = 'Recurso', id = null) {
    const message = id
      ? `${resource} com ID ${id} não encontrado`
      : `${resource} não encontrado`;
    super(message, 404);
  }
}

/**
 * Erro para validação de dados inválidos.
 * Convenção REST: usar 400 Bad Request para dados malformados.
 */
class ValidationError extends ApiError {
  constructor(message = 'Dados de entrada inválidos', errors = null) {
    super(message, 400, errors);
  }
}

/**
 * Middleware que captura erros não tratados e os converte em respostas HTTP adequadas.
 *
 * @param {Error} err - O erro capturado.
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
function errorHandler(err, req, res, next) {
  // Se o erro for nossa classe ApiError, usamos seu statusCode
  const statusCode = err instanceof ApiError ? err.statusCode : 500;

  // Em produção, não expomos stack traces para o cliente (segurança)
  const response = {
    success: false,
    error: {
      message: err.message || 'Erro interno do servidor',
      statusCode,
    },
  };

  // Inclui detalhes de validação quando disponíveis
  if (err.errors && err.errors.length > 0) {
    response.error.details = err.errors;
  }

  // Em desenvolvimento, incluímos o stack trace para facilitar debugging
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.error.stack = err.stack;
  }

  res.status(statusCode).json(response);
}

/**
 * Middleware que captura erros de async handlers.
 *
 * PROBLEMA RESOLVIDO:
 * Express não captura automaticamente rejeições de Promises em handlers assíncronos.
 * Se um handler async lança um erro, o Express não o encaminha para o middleware
 * de erro a menos que explicitamente passemos o erro para next().
 * Esta função wrapper resolve esse problema.
 *
 * @param {Function} fn - Função assíncrona do handler de rota.
 * @returns {Function} Handler Express que captura erros async.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next); // Encaminha qualquer erro para o errorHandler
  };
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler,
  asyncHandler,
};
```

