## Arquivo 4: `src/middleware/validation.js`

```javascript
/**
 * @fileoverview validation.js
 *
 * Middleware de validação de entrada para os endpoints de livros.
 *
 * PADRÃO ESCOLHIDO:
 *
 * Validamos os dados ANTES de processá-los, seguindo o princípio
 * "fail fast" (falhar rapidamente). Isso evita que dados inválidos
 * cheguem ao modelo e garante respostas consistentes para o cliente.
 */

const { ValidationError } = require('./errorHandler');

/**
 * Valida os dados de criação de um livro.
 *
 * Regras de validação:
 *   - title: obrigatório, string, 1-200 caracteres
 *   - author: obrigatório, string, 1-150 caracteres
 *   - year: opcional, número entre 1000 e 2099
 *   - genre: opcional, string, 1-50 caracteres
 *
 * @param {Object} body - Corpo da requisição.
 * @returns {void} Lança ValidationError se a validação falhar.
 */
function validateCreateBook(body) {
  const errors = [];

  // Validação do título
  if (!body.title || typeof body.title !== 'string' || body.title.trim().length === 0) {
    errors.push({ field: 'title', message: 'Título é obrigatório e deve ser uma string não vazia' });
  } else if (body.title.length > 200) {
    errors.push({ field: 'title', message: 'Título deve ter no máximo 200 caracteres' });
  }

  // Validação do autor
  if (!body.author || typeof body.author !== 'string' || body.author.trim().length === 0) {
    errors.push({ field: 'author', message: 'Autor é obrigatório e deve ser uma string não vazia' });
  } else if (body.author.length > 150) {
    errors.push({ field: 'author', message: 'Autor deve ter no máximo 150 caracteres' });
  }

  // Validação opcional do ano
  if (body.year !== undefined && body.year !== null) {
    const year = Number(body.year);
    if (!Number.isInteger(year)) {
      errors.push({ field: 'year', message: 'Ano deve ser um número inteiro' });
    } else if (year < 1000 || year > 2099) {
      errors.push({ field: 'year', message: 'Ano deve estar entre 1000 e 2099' });
    }
  }

  // Validação opcional do gênero
  if (body.genre !== undefined && body.genre !== null) {
    if (typeof body.genre !== 'string' || body.genre.trim().length === 0) {
      errors.push({ field: 'genre', message: 'Gênero deve ser uma string não vazia' });
    } else if (body.genre.length > 50) {
      errors.push({ field: 'genre', message: 'Gênero deve ter no máximo 50 caracteres' });
    }
  }

  if (errors.length > 0) {
    throw new ValidationError('Validação falhou', errors);
  }
}

/**
 * Valida os dados de atualização parcial de um livro.
 *
 * Diferente da criação, todos os campos são opcionais na atualização
 * (PATCH semantics), mas se fornecidos, devem passar pelas mesmas regras.
 *
 * @param {Object} body - Corpo da requisição com campos parciais.
 * @returns {void} Lança ValidationError se a validação falhar.
 */
function validateUpdateBook(body) {
  const errors = [];

  // Só validamos campos que foram fornecidos (partial update)
  if (body.title !== undefined) {
    if (typeof body.title !== 'string' || body.title.trim().length === 0) {
      errors.push({ field: 'title', message: 'Título deve ser uma string não vazia' });
    } else if (body.title.length > 200) {
      errors.push({ field: 'title', message: 'Título deve ter no máximo 200 caracteres' });
    }
  }

  if (body.author !== undefined) {
    if (typeof body.author !== 'string' || body.author.trim().length === 0) {
      errors.push({ field: 'author', message: 'Autor deve ser uma string não vazia' });
    } else if (body.author.length > 150) {
      errors.push({ field: 'author', message: 'Autor deve ter no máximo 150 caracteres' });
    }
  }

  if (body.year !== undefined && body.year !== null) {
    const year = Number(body.year);
    if (!Number.isInteger(year)) {
      errors.push({ field: 'year', message: 'Ano deve ser um número inteiro' });
    } else if (year < 1000 || year > 2099) {
      errors.push({ field: 'year', message: 'Ano deve estar entre 1000 e 2099' });
    }
  }

  if (body.genre !== undefined && body.genre !== null) {
    if (typeof body.genre !== 'string' || body.genre.trim().length === 0) {
      errors.push({ field: 'genre', message: 'Gênero deve ser uma string não vazia' });
    } else if (body.genre.length > 50) {
      errors.push({ field: 'genre', message: 'Gênero deve ter no máximo 50 caracteres' });
    }
  }

  if (body.available !== undefined) {
    if (typeof body.available !== 'boolean') {
      errors.push({ field: 'available', message: 'Disponibilidade deve ser um valor booleano (true/false)' });
    }
  }

  if (errors.length > 0) {
    throw new ValidationError('Validação falhou', errors);
  }
}

module.exports = {
  validateCreateBook,
  validateUpdateBook,
};
