/**
 * @fileoverview books.js
 *
 * Rotas REST para o recurso /books.
 *
 * CONVENÇÕES REST ESCOLHIDAS:
 *
 * | Método HTTP | Endpoint      | Significado              | Código de sucesso |
 * |-------------|---------------|--------------------------|-------------------|
 * | GET         | /books        | Listar todos os livros   | 200 OK            |
 * | GET         | /books/:id    | Obter um livro específico| 200 OK            |
 * | POST        | /books        | Criar novo livro         | 201 Created       |
 * | PUT         | /books/:id    | Atualizar livro completo | 200 OK            |
 * | DELETE      | /books/:id    | Excluir livro            | 204 No Content    |
 *
 * EXEMPLOS DE COMANDO CURL:
 *
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Listar com filtragem por gênero
 *   curl "http://localhost:3000/books?genre=Ficção"
 *
 *   # Filtrar por disponibilidade
 *   curl "http://localhost:3000/books?available=true"
 *
 *   # Obter livro por ID
 *   curl http://localhost:3000/books/1
 *
 *   # Criar novo livro
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Ficção"}'
 *
 *   # Atualizar livro (PUT = atualização completa)
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Ficção","available":false}'
 *
 *   # Excluir livro
 *   curl -X DELETE http://localhost:3000/books/1
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente para reuso

const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../models/bookStore');
const { NotFoundError, asyncHandler } = require('../middleware/errorHandler');
const { validateCreateBook, validateUpdateBook } = require('../middleware/validation');

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem
 * @access  Public
 *
 * Query parameters opcionais:
 *   - genre: filtra por gênero (ex: ?genre=Ficção)
 *   - available: filtra por disponibilidade (true/false)
 *   - search: busca por título ou autor (ex: ?search=tolkien)
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": [ ...livros... ],
 *   "total": 3
 * }
 */
router.get(
  '/',
  asyncHandler((req, res) => {
    let result = getAllBooks();

    // Filtragem por gênero (case-insensitive para melhor UX)
    if (req.query.genre) {
      const genreLower = req.query.genre.toLowerCase();
      result = result.filter((book) => book.genre?.toLowerCase() === genreLower);
    }

    // Filtragem por disponibilidade
    if (req.query.available !== undefined) {
      const available = req.query.available === 'true';
      result = result.filter((book) => book.available === available);
    }

    // Busca textual por título ou autor
    if (req.query.search) {
      const searchLower = req.query.search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // Resposta padronizada com metadados de paginação
    res.json({
      success: true,
      data: result,
      total: result.length,
    });
  })
);

/**
 * @route   GET /books/:id
 * @desc    Obtém um livro específico pelo ID
 * @access  Public
 *
 * Parâmetros de rota:
 *   - id: número inteiro (ex: /books/1)
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": { ...livro... }
 * }
 *
 * Resposta de erro (404):
 * {
 *   "success": false,
 *   "error": { "message": "Livro com ID 999 não encontrado", "statusCode": 404 }
 * }
 */
router.get(
  '/:id',
  asyncHandler((req, res) => {
    // Converte o ID de string (requisição HTTP) para número
    const id = parseInt(req.params.id, 10);

    // Validação básica do parâmetro
    if (isNaN(id)) {
      throw new NotFoundError('Livro', req.params.id);
    }

    const book = getBookById(id);

    if (!book) {
      throw new NotFoundError('Livro', id);
    }

    res.json({
      success: true,
      data: book,
    });
  })
);

/**
 * @route   POST /books
 * @desc    Cria um novo livro
 * @access  Public
 *
 * Corpo da requisição (JSON):
 * {
 *   "title": "Dom Casmurro",
 *   "author": "Machado de Assis",
 *   "year": 1899,
 *   "genre": "Romance"
 * }
 *
 * Resposta de sucesso (201):
 * {
 *   "success": true,
 *   "data": { ...livro criado com ID e timestamps... },
 *   "message": "Livro criado com sucesso"
 * }
 *
 * EXEMPLO POSTMAN:
 *   Method: POST
 *   URL: http://localhost:3000/books
 *   Headers: Content-Type: application/json
 *   Body (raw JSON): {"title":"1984","author":"George Orwell","year":1949,"genre":"Distopia"}
 */
router.post(
  '/',
  asyncHandler((req, res) => {
    // Valida os dados de entrada ANTES de processar
    validateCreateBook(req.body);

    const newBook = createBook({
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      year: req.body.year ? Number(req.body.year) : undefined,
      genre: req.body.genre ? req.body.genre.trim() : undefined,
      available: req.body.available !== undefined ? Boolean(req.body.available) : true,
    });

    // 201 Created é o código HTTP padrão para recursos criados com sucesso
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso',
    });
  })
);

/**
 * @route   PUT /books/:id
 * @desc    Atualiza um livro existente (atualização completa)
 * @access  Public
 *
 * Nota sobre PUT vs PATCH:
 *   - PUT substitui o recurso inteiro (todos os campos obrigatórios).
 *   - PATCH atualizaria apenas campos específicos.
 *   Para este exemplo educacional, usamos PUT com campos parciais,
 *   mas mantemos a semântica de que title e author são obrigatórios
 *   se fornecidos.
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": { ...livro atualizado... },
 *   "message": "Livro atualizado com sucesso"
 * }
 */
router.put(
  '/:id',
  asyncHandler((req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new NotFoundError('Livro', req.params.id);
    }

    // Valida os dados de atualização
    validateUpdateBook(req.body);

    const updatedBook = updateBook(id, {
      title: req.body.title !== undefined ? req.body.title.trim() : undefined,
      author: req.body.author !== undefined ? req.body.author.trim() : undefined,
      year: req.body.year !== undefined ? Number(req.body.year) : undefined,
      genre: req.body.genre !== undefined ? req.body.genre.trim() : undefined,
      available: req.body.available !== undefined ? Boolean(req.body.available) : undefined,
    });

    if (!updatedBook) {
      throw new NotFoundError('Livro', id);
    }

    res.json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso',
    });
  })
);

/**
 * @route   DELETE /books/:id
 * @desc    Exclui um livro pelo ID
 * @access  Public
 *
 * Resposta de sucesso (204):
 *   Sem corpo — apenas cabeçalhos HTTP.
 *   Código 204 No Content é o padrão REST para exclusões bem-sucedidas.
 *
 * Resposta de erro (404):
 * {
 *   "success": false,
 *   "error": { "message": "Livro com ID 999 não encontrado", "statusCode": 404 }
 * }
 */
router.delete(
  '/:id',
  asyncHandler((req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new NotFoundError('Livro', req.params.id);
    }

    const deleted = deleteBook(id);

    if (!deleted) {
      throw new NotFoundError('Livro', id);
    }

    // 204 No Content: sucesso sem corpo de resposta (padrão REST para DELETE)
    res.status(204).send();
  })
);

module.exports = router;
