## Arquivo 7: `src/server.js`

```javascript
/**
 * @fileoverview server.js
 *
 * Ponto de entrada da aplicação Express.js.
 *
 * PADRÕES ESCOLHIDOS:
 *
 * 1. async/await sobre callbacks:
 *    Async/await torna o código assíncrono mais legível, equivalente a
 *    Promises encadeadas mas com sintaxe síncrona. Isso reduz o "callback hell"
 *    e facilita o tratamento de erros com try/catch (embora aqui usemos
 *    asyncHandler para capturar erros de forma centralizada).
 *
 * 2. Separação de rotas em módulos:
 *    Cada recurso da API tem seu próprio arquivo de rotas. Isso permite:
 *      - Manutenção isolada (cada rota é autônoma).
 *      - Reuso (roteadores podem ser montados em diferentes prefixes).
 *      - Testabilidade (cada módulo pode ser testado separadamente).
 *
 * 3. Middlewares na ordem correta:
 *    express.json() deve vir ANTES das rotas para que req.body seja populado.
 *    O middleware de erro DEVE ser o ÚLTIMO para capturar erros de todas as rotas.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Inicializa a aplicação Express
const app = express();

// Configura a porta — usa variável de ambiente ou padrão 3000
const PORT = process.env.PORT || 3000;

/**
 * Middleware: parse de JSON no corpo das requisições.
 * Sem este middleware, req.body seria undefined em POST/PUT.
 */
app.use(express.json());

/**
 * Middleware: logging básico de requisições (desenvolvimento).
 * Mostra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

/**
 * Middleware: CORS básico.
 * Permite que frontends de diferentes origens acessem a API.
 * Em produção, restrinja origin a domínios específicos.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Rota raiz — health check da API.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando com sucesso!',
    endpoints: {
      books: '/books',
      stats: '/stats',
    },
  });
});

/**
 * Montagem dos roteadores.
 * Todos os endpoints de livros ficam sob /books.
 * Endpoints de estatísticas ficam sob /stats.
 */
app.use('/books', booksRouter);
app.use('/stats', statsRouter);

/**
 * Rota 404 para URLs não encontrados.
 * Deve vir DEPOIS de todas as rotas definidas.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Rota ${req.method} ${req.url} não encontrada`,
      statusCode: 404,
    },
  });
});

/**
 * Middleware de tratamento de erros — SEMPRE o último middleware.
 * Captura erros lançados por rotas e os converte em respostas padronizadas.
 */
app.use(errorHandler);

// Inicia o servidor
app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando na porta ${PORT}`);
  console.log(`   Health check: http://localhost:${PORT}/`);
  console.log(`   Livros:       http://localhost:${PORT}/books`);
  console.log(`   Stats:        http://localhost:${PORT}/stats`);
});

module.exports = app; // Exporta para testes unitários
```

