## File 2: `data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For an educational example, an in-memory array avoids the
 * complexity of setting up a database while still demonstrating all REST
 * principles. In production, you would replace this with a MongoDB/PostgreSQL
 * service. The interface (getById, getAll, etc.) can stay the same — only the
 * implementation changes.
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and are simple to filter,
 * map, and reduce. For small datasets (< 10k records), this is perfectly fine.
 * For larger datasets, a database with indexes would be necessary.
 */

// ---------------------------------------------------------------------------
// Data Structure: Each book has the following shape:
// {
//   id: number          — Unique identifier (auto-incremented)
//   title: string       — Book title
//   author: string      — Author name
//   genre: string       — Genre/category (e.g., "Fiction", "Science")
//   publishedYear: number — Year of publication
//   rating: number      — Average rating from 1.0 to 5.0
// }
// ---------------------------------------------------------------------------

/** @type {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}>} */
const books = [
  {
    id: 1,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Fiction",
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 2,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    genre: "Science",
    publishedYear: 1988,
    rating: 4.6
  },
  {
    id: 3,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Fiction",
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 4,
    title: "Clean Code",
    author: "Robert C. Martin",
    genre: "Technology",
    publishedYear: 2008,
    rating: 4.7
  },
  {
    id: 5,
    title: "Dune",
    author: "Frank Herbert",
    genre: "Science Fiction",
    publishedYear: 1965,
    rating: 4.9
  }
];

/** @type {number} Tracks the next available ID to ensure uniqueness */
let nextId = 6;

// ---------------------------------------------------------------------------
// Helper: Validate that a value is a positive integer
// Used by CRUD operations to guard against invalid IDs or years.
// ---------------------------------------------------------------------------

/**
 * Checks whether a value is a valid positive integer.
 * @param {*} value — The value to test.
 * @returns {boolean} True if the value is a positive integer, false otherwise.
 */
function isValidPositiveInteger(value) {
  return Number.isInteger(value) && value > 0;
}

// ---------------------------------------------------------------------------
// CRUD Operations on the in-memory store
// Each function is pure (no side effects beyond mutating the `books` array)
// and returns the resulting book(s) so routes can respond immediately.
// ---------------------------------------------------------------------------

/**
 * Retrieves a single book by its numeric ID.
 * @param {number} id — The unique identifier of the book.
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}|null}
 *   The book object if found, or null if no match exists.
 */
function getById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * FILTERING LOGIC:
 * - genre: exact match (case-insensitive)
 * - minRating: books with rating >= this value
 * - author: substring match (case-insensitive)
 * - publishedYear: exact year match
 *
 * These filters are combined with AND logic — all provided filters must match.
 * @param {Object} [filters] — Optional query parameters for filtering.
 * @param {string} [filters.genre] — Filter by genre.
 * @param {number} [filters.minRating] — Minimum rating threshold.
 * @param {string} [filters.author] — Search author name (substring).
 * @param {number} [filters.publishedYear] — Filter by publication year.
 * @returns {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}>}
 *   The filtered list of books.
 */
function getAll(filters = {}) {
  let result = [...books]; // Clone to avoid mutating the original array

  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter(book => book.genre.toLowerCase() === genreLower);
  }

  if (filters.minRating !== undefined && filters.minRating !== null) {
    const minRating = parseFloat(filters.minRating);
    if (!isNaN(minRating)) {
      result = result.filter(book => book.rating >= minRating);
    }
  }

  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  if (filters.publishedYear) {
    const year = parseInt(filters.publishedYear, 10);
    if (!isNaN(year)) {
      result = result.filter(book => book.publishedYear === year);
    }
  }

  return result;
}

/**
 * Creates a new book and adds it to the store.
 * Assigns an auto-incremented ID to ensure uniqueness.
 * @param {{title: string, author: string, genre: string, publishedYear: number, rating: number}} bookData
 *   The book data to insert (without id).
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}}
 *   The newly created book with its assigned ID.
 */
function create(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID. Replaces the entire book object with the
 * provided data (partial updates are not supported in this simple example).
 * @param {number} id — The ID of the book to update.
 * @param {{title?: string, author?: string, genre?: string, publishedYear?: number, rating?: number}} updateData
 *   Fields to update (all fields are optional for partial updates).
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}|null}
 *   The updated book if found, or null if the ID does not exist.
 */
function update(id, updateData) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return null;

  // Merge existing data with updates (partial update support)
  books[index] = { ...books[index], ...updateData };
  return books[index];
}

/**
 * Deletes a book by ID.
 * @param {number} id — The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function remove(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

// ---------------------------------------------------------------------------
// Statistics: Aggregate data about the collection
// These are computed on every request — acceptable for small in-memory datasets.
// For production, you might cache these or maintain them incrementally.
// ---------------------------------------------------------------------------

/**
 * Computes statistics about the book collection.
 * @returns {{
 *   totalBooks: number,
 *   averageRating: number,
 *   genres: Array<{genre: string, count: number}>,
 *   oldestBook: {title: string, publishedYear: number}|null,
 *   newestBook: {title: string, publishedYear: number}|null
 * }}
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      genres: [],
      oldestBook: null,
      newestBook: null
    };
  }

  // Compute average rating using reduce for accumulation
  const averageRating = parseFloat(
    (books.reduce((sum, book) => sum + book.rating, 0) / totalBooks).toFixed(2)
  );

  // Count books per genre using a frequency map
  const genreCounts = {};
  books.forEach(book => {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  });

  const genres = Object.entries(genreCounts).map(([genre, count]) => ({
    genre,
    count
  }));

  // Find oldest and newest books by publishedYear
  const oldestBook = books.reduce(
    (min, book) => (book.publishedYear < min.publishedYear ? book : min),
    books[0]
  );
  const newestBook = books.reduce(
    (max, book) => (book.publishedYear > max.publishedYear ? book : max),
    books[0]
  );

  return {
    totalBooks,
    averageRating,
    genres,
    oldestBook: { title: oldestBook.title, publishedYear: oldestBook.publishedYear },
    newestBook: { title: newestBook.title, publishedYear: newestBook.publishedYear }
  };
}

// ---------------------------------------------------------------------------
// Export all functions via module.exports for use in route handlers.
// We use named exports so consumers can pick exactly what they need.
// ---------------------------------------------------------------------------

module.exports = {
  getById,
  getAll,
  create,
  update,
  remove,
  getStats,
  isValidPositiveInteger
};
```

**Key design decisions explained:**

1. **In-memory array**: Chosen for simplicity and zero setup. Production systems would use a database, but the route handlers remain identical — only this file changes.
2. **Auto-incrementing `nextId`**: Guarantees unique IDs without requiring UUID libraries or database sequences.
3. **Filtering with AND logic**: All provided query parameters must match. This is intuitive and matches common API patterns (e.g., GitHub, Stripe).
4. **Pure functions**: Each operation takes inputs and returns outputs without hidden side effects, making the code testable and predictable.
5. **Statistics computed on demand**: For small datasets this is fine. In production, you'd cache results or use database aggregations.

