## File 3: `middleware/errors.js` — Custom Error Classes & Middleware

```javascript
/**
 * @fileoverview Custom error handling middleware and error classes.
 *
 * WHY CUSTOM ERROR CLASSES? They allow us to distinguish between different
 * failure modes (not found, validation error, internal server error) so that
 * the error handler can return appropriate HTTP status codes and messages.
 *
 * WHY MIDDLEWARE? Express supports a special 4-argument middleware function
 * (err, req, res, next) that catches errors from anywhere in the request chain.
 * This centralizes error formatting and prevents duplicate error-handling code.
 */

// ---------------------------------------------------------------------------
// Custom Error Classes
// Each extends Error and sets a statusCode so the handler knows which HTTP
// status to return (404, 400, 500, etc.).
// ---------------------------------------------------------------------------

/**
 * Base custom error class that includes an HTTP status code.
 * All other error classes extend this for consistency.
 */
class ApiError extends Error {
  /**
   * @param {string} message — Human-readable error description.
   * @param {number} statusCode — HTTP status code (default: 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;

    // Capture the stack trace for debugging (useful in development)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Raised when a requested resource does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends ApiError {
  /**
   * @param {string} [message] — Custom message (default: "Resource not found").
   */
  constructor(message = "Resource not found") {
    super(message, 404);
  }
}

/**
 * Raised when client input fails validation.
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message — Description of the validation failure.
   * @param {Array<{field: string, message: string}>} [details] — Specific field-level errors.
   */
  constructor(message, details = []) {
    super(message, 400);
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// Validation Helper
// Validates required fields and value constraints for book creation/update.
// Returns an array of detail objects if validation fails, empty array if valid.
// ---------------------------------------------------------------------------

/**
 * Validates book data for POST /books and PUT /books/:id.
 * @param {Object} data — The request body to validate.
 * @returns {Array<{field: string, message: string}>} List of validation errors (empty if valid).
 */
function validateBookData(data) {
  const details = [];

  // Title is required and must be a non-empty string
  if (!data.title || typeof data.title !== "string" || data.title.trim() === "") {
    details.push({ field: "title", message: "Title is required and must be a non-empty string." });
  }

  // Author is required and must be a non-empty string
  if (!data.author || typeof data.author !== "string" || data.author.trim() === "") {
    details.push({ field: "author", message: "Author is required and must be a non-empty string." });
  }

  // Genre is required and must be a non-empty string
  if (!data.genre || typeof data.genre !== "string" || data.genre.trim() === "") {
    details.push({ field: "genre", message: "Genre is required and must be a non-empty string." });
  }

  // Published year must be a valid integer between 1000 and current year + 1
  const currentYear = new Date().getFullYear();
  if (data.publishedYear === undefined || data.publishedYear === null) {
    details.push({ field: "publishedYear", message: "Published year is required." });
  } else if (!Number.isInteger(data.publishedYear) || data.publishedYear < 1000 || data.publishedYear > currentYear + 1) {
    details.push({ field: "publishedYear", message: `Published year must be an integer between 1000 and ${currentYear + 1}.` });
  }

  // Rating must be a number between 1.0 and 5.0
  if (data.rating === undefined || data.rating === null) {
    details.push({ field: "rating", message: "Rating is required." });
  } else if (typeof data.rating !== "number" || data.rating < 1.0 || data.rating > 5.0) {
    details.push({ field: "rating", message: "Rating must be a number between 1.0 and 5.0." });
  }

  return details;
}

// ---------------------------------------------------------------------------
// Error Handling Middleware
 * This 4-argument middleware catches all errors thrown in route handlers
 * and formats them into consistent JSON responses.
 *
 * ORDER MATTERS: Place this AFTER all route definitions so it runs last
 * in the middleware chain. Express executes middleware in registration order.
// ---------------------------------------------------------------------------

/**
 * Global error-handling middleware for Express.
 * Catches errors from any route and returns a structured JSON response.
 * @param {Error} err — The error object (custom or native).
 * @param {import("express").Request} req — The Express request object.
 * @param {import("express").Response} res — The Express response object.
 * @param {import("express").NextFunction} next — The next middleware function.
 */
function errorHandler(err, req, res, next) {
  // Log the full error for server-side debugging (never expose stack traces to clients)
  console.error(`[ERROR] ${err.statusCode || err.code || "500"} — ${err.message}`);
  if (process.env.NODE_ENV === "development" && err.stack) {
    console.error(err.stack);
  }

  // Determine the response structure based on error type
  const statusCode = err.statusCode || 500;
  const responseBody = {
    success: false,
    error: {
      message: err.message,
      statusCode
    }
  };

  // Include validation details if available (only for ValidationError)
  if (err.details && Array.isArray(err.details)) {
    responseBody.error.details = err.details;
  }

  // Send the JSON response with the appropriate status code
  res.status(statusCode).json(responseBody);
}

// ---------------------------------------------------------------------------
// Async Wrapper Helper
 * Express route handlers that use async/await can throw unhandled promise
 * rejections if an error occurs inside the handler. This wrapper catches
 * those and passes them to the error-handling middleware via next(err).
 *
 * WHY? Without this, async errors would crash the server or return 500 with
 * no useful message. The wrapper ensures every async route is safe.
// ---------------------------------------------------------------------------

/**
 * Wraps an async Express route handler to catch promise rejections.
 * @param {Function} fn — The async route handler function.
 * @returns {import("express").RequestHandler} Wrapped handler compatible with Express.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ---------------------------------------------------------------------------
// Export everything for use in routes and server.js
// ---------------------------------------------------------------------------

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  validateBookData,
  errorHandler,
  asyncHandler
};
```

**Key design decisions explained:**

1. **Custom error classes**: Each carries a `statusCode` so the handler can return the correct HTTP code without conditional logic.
2. **`errorHandler` middleware**: The 4-argument signature `(err, req, res, next)` is Express's convention for error-handling middleware. It must be registered after all routes.
3. **`asyncHandler` wrapper**: Prevents unhandled promise rejections in async route handlers — a common source of bugs in Express apps.
4. **Validation returns details array**: Allows clients to see exactly which fields failed and why, improving developer experience.

