## File 4: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * @fileoverview REST routes for book management (CRUD operations).
 *
 * ROUTE STRUCTURE:
 *   GET    /books          — List all books (with optional filtering)
 *   GET    /books/:id      — Get a single book by ID
 *   POST   /books          — Create a new book
 *   PUT    /books/:id      — Update an existing book
 *   DELETE /books/:id      — Delete a book
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module makes the
 * codebase modular and testable. The server.js file stays clean by only
 * importing and mounting these routes.
 *
 * REST CONVENTIONS FOLLOWED:
 *   - GET requests are idempotent and safe (no state changes)
 *   - POST creates a new resource; returns 201 with the created object
 *   - PUT replaces the entire resource; returns 200 with the updated object
 *   - DELETE removes the resource; returns 204 No Content on success
 *   - All responses use consistent JSON structure: { success, data/error }
 */

const express = require("express");
const router = express.Router();

// Import our in-memory data store and error-handling utilities
const { getById, getAll, create, update, remove } = require("../data/books");
const {
  NotFoundError,
  ValidationError,
  validateBookData,
  asyncHandler
} = require("../middleware/errors");

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
//
 * Query parameters (all optional):
 *   ?genre=fiction        — Filter by exact genre match (case-insensitive)
 *   ?minRating=4.0        — Only books with rating >= this value
 *   ?author=hawking       — Search author name (substring, case-insensitive)
 *   ?publishedYear=1988   — Filter by exact publication year
 *
 * Example: GET /books?genre=Fiction&minRating=4.5
// ---------------------------------------------------------------------------

/**
 * Handler for GET /books.
 * Returns a list of all books, optionally filtered by query parameters.
 */
router.get(
  "/books",
  asyncHandler(async (req, res) => {
    // Extract filter parameters from the query string
    const filters = {
      genre: req.query.genre,
      minRating: req.query.minRating,
      author: req.query.author,
      publishedYear: req.query.publishedYear
    };

    // Call the data layer to get filtered results
    const books = getAll(filters);

    // Return 200 OK with the book list
    res.status(200).json({
      success: true,
      count: books.length,
      data: books
    });
  })
);

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
//
 * The :id parameter is captured by Express and available as req.params.id.
 * We must validate that it's a valid positive integer before querying.
// ---------------------------------------------------------------------------

/**
 * Handler for GET /books/:id.
 * Returns a single book if found, or 404 if not.
 */
router.get(
  "/books/:id",
  asyncHandler(async (req, res) => {
    // Parse the ID from the URL parameter and validate it's a positive integer
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", [
        { field: "id", message: "ID must be a positive integer." }
      ]);
    }

    // Look up the book in our data store
    const book = getById(id);

    // If not found, throw a NotFoundError (caught by error middleware)
    if (!book) {
      throw new NotFoundError(`Book with ID ${id} not found.`);
    }

    // Return 200 OK with the book object
    res.status(200).json({
      success: true,
      data: book
    });
  })
);

// ---------------------------------------------------------------------------
// POST /books — Create a new book
//
 * The request body should contain: title, author, genre, publishedYear, rating.
 * We validate the input before creating the book to fail fast with clear errors.
 * On success, we return 201 Created (the REST convention for resource creation).
// ---------------------------------------------------------------------------

/**
 * Handler for POST /books.
 * Creates a new book and returns it with status 201.
 */
router.post(
  "/books",
  asyncHandler(async (req, res) => {
    // Extract the body from the request (Express parses JSON automatically
    // when using express.json() middleware in server.js)
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate all required fields and their constraints
    const validationErrors = validateBookData(req.body);
    if (validationErrors.length > 0) {
      throw new ValidationError("Validation failed.", validationErrors);
    }

    // Create the book in our data store
    const newBook = create({
      title: title.trim(),
      author: author.trim(),
      genre: genre.trim(),
      publishedYear,
      rating
    });

    // Return 201 Created with the newly created book
    res.status(201).json({
      success: true,
      message: "Book created successfully.",
      data: newBook
    });
  })
);

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
//
 * PUT replaces the entire resource. We accept partial updates (only provided
 * fields are changed) for convenience, but in strict REST you might require
 * all fields. This implementation uses a merge strategy.
// ---------------------------------------------------------------------------

/**
 * Handler for PUT /books/:id.
 * Updates an existing book and returns it with status 200.
 */
router.put(
  "/books/:id",
  asyncHandler(async (req, res) => {
    // Parse and validate the ID
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", [
        { field: "id", message: "ID must be a positive integer." }
      ]);
    }

    // Check if the book exists before attempting update
    const existingBook = getById(id);
    if (!existingBook) {
      throw new NotFoundError(`Book with ID ${id} not found.`);
    }

    // Validate the incoming data (only required fields for partial updates)
    const validationErrors = validateBookData(req.body);
    if (validationErrors.length > 0) {
      throw new ValidationError("Validation failed.", validationErrors);
    }

    // Perform the update (merge with existing data)
    const updatedBook = update(id, req.body);

    // Return 200 OK with the updated book
    res.status(200).json({
      success: true,
      message: "Book updated successfully.",
      data: updatedBook
    });
  })
);

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
//
 * On successful deletion, REST convention is to return 204 No Content
 * (no response body). This signals that the resource has been removed.
// ---------------------------------------------------------------------------

/**
 * Handler for DELETE /books/:id.
 * Deletes a book and returns 204 No Content on success.
 */
router.delete(
  "/books/:id",
  asyncHandler(async (req, res) => {
    // Parse and validate the ID
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      throw new ValidationError("Invalid book ID. Must be a positive integer.", [
        { field: "id", message: "ID must be a positive integer." }
      ]);
    }

    // Check if the book exists before attempting deletion
    const existingBook = getById(id);
    if (!existingBook) {
      throw new NotFoundError(`Book with ID ${id} not found.`);
    }

    // Perform the deletion
    remove(id);

    // Return 204 No Content (standard for successful DELETE operations)
    res.status(204).send();
  })
);

// ---------------------------------------------------------------------------
// Export the router so server.js can mount it at /books
// ---------------------------------------------------------------------------

module.exports = router;
```

**Key design decisions explained:**

1. **`asyncHandler` wrapper**: Every route is wrapped to catch async errors and pass them to the global error handler. This prevents unhandled promise rejections.
2. **Consistent response format**: All successful responses use `{ success: true, data: ... }` or `{ success: true, message: ..., data: ... }`. Errors use `{ success: false, error: { message, statusCode } }`.
3. **HTTP status codes**: 200 for GET/PUT, 201 for POST (created), 204 for DELETE (no content), 400 for validation errors, 404 for not found. These follow REST conventions.
4. **Input validation before processing**: We validate IDs and request bodies early, throwing descriptive errors that the middleware formats into JSON responses.

