```javascript
/**
 * @fileoverview Main application entry point.
 *
 * This file sets up the Express server, configures middleware, mounts routes,
 * and starts listening on a port. It is intentionally minimal — all business
 * logic lives in data/, routes/, and middleware/ directories.
 *
 * MIDDLEWARE ORDER MATTERS:
 *   1. express.json() — Parse JSON request bodies
 *   2. Route handlers — Process requests
 *   3. errorHandler — Catch and format errors (must be last)
 *
 * WHY THIS ORDER? Express executes middleware in registration order. If the
 * error handler were registered before routes, it would never see route errors.
 */

const express = require("express");

// Import our route modules
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");

// Import the global error-handling middleware
const { errorHandler } = require("./middleware/errors");

// ---------------------------------------------------------------------------
// Application Setup
// ---------------------------------------------------------------------------

/** @type {import("express").Express} The Express application instance */
const app = express();

/** @type {number} Port number for the server (default: 3000) */
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Middleware Configuration
// ---------------------------------------------------------------------------

/**
 * Parse JSON request bodies.
 * Enables req.body to contain parsed JSON from POST/PUT requests.
 * Without this, req.body would be undefined.
 */
app.use(express.json());

/**
 * Log every request for debugging (development only).
 * In production, you might use a proper logging library like winston.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ---------------------------------------------------------------------------
// Route Mounting
// ---------------------------------------------------------------------------

/**
 * Mount book routes at /books.
 * All routes defined in routes/books.js will be prefixed with /books.
 * Example: GET /books, POST /books, GET /books/:id, etc.
 */
app.use("/books", bookRoutes);

/**
 * Mount stats routes at /stats.
 * All routes defined in routes/stats.js will be prefixed with /stats.
 * Example: GET /stats
 */
app.use("/stats", statsRoutes);

// ---------------------------------------------------------------------------
// Root Endpoint (for health checks and API discovery)
// ---------------------------------------------------------------------------

/**
 * GET / — Return API information and available endpoints.
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "Book REST API is running.",
    endpoints: {
      books: {
        get: "/books",
        getById: "/books/:id",
        post: "/books",
        put: "/books/:id",
        delete: "/books/:id"
      },
      stats: {
        get: "/stats"
      }
    }
  });
});

// ---------------------------------------------------------------------------
// Global Error Handling Middleware
 * MUST be registered AFTER all routes so it can catch errors from them.
 * Express identifies this middleware by its 4-argument signature.
// ---------------------------------------------------------------------------

app.use(errorHandler);

// ---------------------------------------------------------------------------
// Start the Server
// ---------------------------------------------------------------------------

/**
 * Start the HTTP server and log startup information.
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || "development"}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    http://localhost:${PORT}/`);
  console.log(`  GET    http://localhost:${PORT}/books`);
  console.log(`  GET    http://localhost:${PORT}/books/:id`);
  console.log(`  POST   http://localhost:${PORT}/books`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id`);
  console.log(`  GET    http://localhost:${PORT}/stats`);
  console.log(`\nTry: curl http://localhost:${PORT}/books\n`);
});

// ---------------------------------------------------------------------------
// Export the app for testing (optional, useful for unit tests)
// ---------------------------------------------------------------------------

module.exports = app;
```

**Key design decisions explained:**

1. **Middleware order**: `express.json()` must come before route handlers so request bodies are parsed. The error handler must come after all routes so it can catch their errors.
2. **Environment-based port**: Uses `process.env.PORT` with a fallback to 3000, following the Twelve-Factor App methodology.
3. **Request logging**: Simple console logging for development. Production apps should use structured logging.
4. **Root endpoint**: Provides API discovery and health-check capability — useful for monitoring and documentation.

