## Arquivo 2: `src/errors/ErrorHandler.js`

```javascript
/**
 * ============================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================
 *
 * POR QUE CRIAR CLASSES DE ERRO PRÓPRIAS?
 * ----------------------------------------
 * Em vez de lançar erros genéricos (new Error("algo deu errado")),
 * criamos subclasses que carregam informações estruturadas:
 *   - statusCode: código HTTP apropriado (400, 404, 500, etc.)
 *   - isOperational: indica se o erro é esperado do negócio
 *     (true) ou um bug inesperado (false)
 *
 * Isso permite que o middleware de tratamento de erros decida
 * como responder ao cliente sem expor detalhes internos do sistema.
 *
 * PADRÃO ADOTADO: "Operational Errors" vs "Programming Errors"
 * -----------------------------------------------------------
 * Erros operacionais são previsíveis (recurso não encontrado,
 * validação falha) e devem ser retornados ao cliente com mensagem
 * clara. Erros de programação são bugs reais e não devem vazar
 * detalhes para o usuário final.
 */

/**
 * Classe base para todos os erros da API.
 * Extende Error nativo do JavaScript, adicionando statusCode.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP correspondente (ex: 404)
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error pai

    this.statusCode = statusCode;
    this.isOperational = true; // Erro esperado, não um bug

    // Mantém a stack trace correta mesmo com classes customizadas.
    // Sem isso, error.stack perderia a posição do construtor.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para requisições malformadas ou com dados inválidos.
 * HTTP 400 Bad Request.
 *
 * Exemplo de uso:
 *   throw new BadRequestError("O campo 'titulo' é obrigatório.");
 */
class BadRequestError extends AppError {
  constructor(message = "Requisição malformada.") {
    super(message, 400);
  }
}

/**
 * Erro quando um recurso solicitado não existe.
 * HTTP 404 Not Found.
 *
 * Exemplo de uso:
 *   throw new NotFoundError("Livro com ID 99 não encontrado.");
 */
class NotFoundError extends AppError {
  constructor(message = "Recurso não encontrado.") {
    super(message, 404);
  }
}

/**
 * Erro para recursos já existentes (violação de unicidade).
 * HTTP 409 Conflict.
 *
 * Exemplo de uso:
 *   throw new ConflictError("Já existe um livro com este ISBN.");
 */
class ConflictError extends AppError {
  constructor(message = "Conflito com recurso existente.") {
    super(message, 409);
  }
}

/**
 * Erro para operações não autorizadas.
 * HTTP 401 Unauthorized.
 *
 * Este exemplo é educacional e não implementa autenticação real,
 * mas a classe está disponível para expansão futura.
 */
class UnauthorizedError extends AppError {
  constructor(message = "Não autorizado.") {
    super(message, 401);
  }
}

/**
 * Erro para operações proibidas (ex: método não permitido).
 * HTTP 405 Method Not Allowed.
 */
class MethodNotAllowedError extends AppError {
  constructor(message = "Método não permitido.") {
    super(message, 405);
  }
}

/**
 * Erro interno do servidor (algo inesperado aconteceu).
 * HTTP 500 Internal Server Error.
 *
 * IMPORTANTE: Em produção, NUNCA exponha a mensagem original
 * deste erro ao cliente. Ela pode conter caminhos de arquivo,
 * queries SQL ou outros detalhes sensíveis.
 */
class InternalServerError extends AppError {
  constructor(message = "Erro interno do servidor.") {
    super(message, 500);
  }
}

/**
 * Exporta todas as classes de erro como um único objeto.
 * Isso facilita a importação em outros módulos:
 *   const { NotFoundError, BadRequestError } = require('./errors/ErrorHandler');
 */
module.exports = {
  AppError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  UnauthorizedError,
  MethodNotAllowedError,
  InternalServerError,
};
```

