## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE ESPECIAL PARA ERROS?
 * -------------------------------------------
 * Express permite definir middlewares com 4 parâmetros:
 *   (err, req, res, next)
 *
 * Quando um middleware ou rota chama next(err), o Express
 * pula todos os middlewares normais e vai direto para este.
 * Isso centraliza o tratamento de erros em UM único lugar,
 * evitando repetição de lógica em cada rota.
 *
 * PADRÃO async/await + catch:
 * ---------------------------
 * Em rotas assíncronas, erros lançados dentro do handler
 * NÃO são capturados automaticamente pelo Express. Por isso,
 * usamos a função wrapper 'asyncHandler' (exportada separadamente)
 * ou try/catch em cada rota. Este middleware lida com o que
 * escapar desses mecanismos.
 *
 * SEGURANÇA:
 * ----------
 * Erros operacionais (isOperational === true) recebem mensagem
 * ao cliente. Erros de programação (bugs) recebem mensagem
 * genérica, enquanto os detalhes são logados no servidor.
 */

const { InternalServerError } = require('../errors/ErrorHandler');

/**
 * Middleware principal de tratamento de erros.
 * Deve ser o ÚLTIMO middleware registrado no app Express.
 *
 * @param {Error} err - O erro capturado
 * @param {import('express').Request} req - Objeto request do Express
 * @param {import('express').Response} res - Objeto response do Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Define o statusCode: usa o do erro customizado ou 500 como fallback
  const statusCode = err.statusCode || 500;

  // Decide se expõe a mensagem ao cliente
  // Erros operacionais são seguros para exposição (são esperados)
  // Erros não-operacionais (bugs) recebem mensagem genérica
  const isOperational = err.isOperational !== false; // undefined também conta como true
  const message = isOperational ? err.message : "Erro interno do servidor.";

  // Log completo no servidor para debugging
  // Em produção, use um logger adequado (Winston, Pino, etc.)
  if (!isOperational) {
    console.error(`[ERRO DO SERVIDOR] ${err.message}`);
    console.error(err.stack); // Stack trace completo para desenvolvimento
  }

  // Monta a resposta padronizada em JSON
  // Formato: { success: false, error: { message, statusCode } }
  const response = {
    success: false,
    error: {
      message,
      statusCode,
    },
  };

  // Em desenvolvimento, inclua o stack trace para facilitar debugging
  if (process.env.NODE_ENV !== 'production' && !isOperational) {
    response.error.stack = err.stack;
  }

  // Envia a resposta com o código HTTP apropriado
  res.status(statusCode).json(response);
}

/**
 * Wrapper para handlers assíncronos de rota.
 *
 * POR QUE ESTE WRAPPER?
 * ---------------------
 * Express não captura automaticamente rejeições de Promises
 * em rotas async. Sem este wrapper, um erro non-catched
 * causaria um crash no servidor (unhandled rejection).
 *
 * O wrapper captura o erro e o passa para next(err), que
 * será tratado pelo middleware errorHandler acima.
 *
 * @param {Function} fn - Handler assíncrono da rota
 * @returns {Function} Função handler compatível com Express
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    fn(req, res, next).catch(next); // Encaminha qualquer erro para o errorHandler
  };
}

module.exports = { errorHandler, asyncHandler };
```

