## Arquivo 4: `src/middleware/validation.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE VALIDAÇÃO
 * ============================================================
 *
 * POR QUE VALIDAR ENTRADAS DO USUÁRIO?
 * -------------------------------------
 * Dados enviados pelo cliente NUNCA devem ser confiáveis.
 * Validação antecipada evita:
 *   1. Dados inconsistentes no armazenamento
 *   2. Erros de validação espalhados por várias rotas
 *   3. Injeção de dados malformados (segurança)
 *
 * PADRÃO ADOTADO: Middleware dedicado vs validação inline
 * -------------------------------------------------------
 * Criamos middlewares de validação reutilizáveis que podem ser
 * aplicados em múltiplas rotas. Isso segue o princípio DRY
 * (Don't Repeat Yourself) e centraliza regras de negócio.
 *
 * Em projetos reais, bibliotecas como Joi, Zod ou Yup são
 * preferidas para esquemas complexos. Aqui usamos validação
 * manual para fins educacionais, tornando cada regra visível.
 */

const { BadRequestError } = require('../errors/ErrorHandler');

/**
 * Valida os campos obrigatórios e tipos de um livro na requisição.
 *
 * CAMPOS VALIDADOS:
 * -----------------
 * - titulo: string não vazia (obrigatório)
 * - autor: string não vazia (obrigatório)
 * - ano: número inteiro positivo (opcional, mas se fornecido deve ser válido)
 * - isbn: string não vazia (opcional, mas se fornecido deve ter formato básico)
 * - genero: string (opcional)
 *
 * @param {import('express').Request} req - Objeto request do Express
 * @param {import('express').Response} res - Objeto response do Express
 * @param {Function} next - Função next do Express
 * @returns {void} Chama next() se válido, ou lança BadRequestError
 */
function validateBook(req, res, next) {
  const { titulo, autor, ano, isbn, genero } = req.body;

  // Verifica campos obrigatórios
  if (!titulo || typeof titulo !== 'string' || titulo.trim() === '') {
    return next(new BadRequestError("O campo 'titulo' é obrigatório e deve ser uma string."));
  }

  if (!autor || typeof autor !== 'string' || autor.trim() === '') {
    return next(new BadRequestError("O campo 'autor' é obrigatório e deve ser uma string."));
  }

  // Valida ano se fornecido: deve ser um número inteiro positivo
  if (ano !== undefined && ano !== null) {
    const anoNum = Number(ano);
    if (!Number.isInteger(anoNum) || anoNum < 0 || anoNum > new Date().getFullYear() + 1) {
      return next(new BadRequestError(
        `O campo 'ano' deve ser um número inteiro entre 0 e ${new Date().getFullYear() + 1}.`
      ));
    }
  }

  // Valida ISBN se fornecido: formato básico (10 ou 13 caracteres, pode conter '-' e 'X')
  if (isbn !== undefined && isbn !== null) {
    const isbnStr = String(isbn).trim();
    const isbnRegex = /^(\d{9}[\dX]|(\d{3}-)?\d{10}[\dX])$/;
    if (!isbnRegex.test(isbnStr)) {
      return next(new BadRequestError(
        "O campo 'isbn' deve ter 10 ou 13 dígitos (pode conter '-' e terminar com 'X')."
      ));
    }
  }

  // Valida gênero se fornecido
  if (genero !== undefined && genero !== null) {
    if (typeof genero !== 'string' || genero.trim() === '') {
      return next(new BadRequestError("O campo 'genero' deve ser uma string não vazia."));
    }
  }

  // Se tudo passou, continua para a próxima etapa
  next();
}

/**
 * Valida o ID da rota (parâmetro :id).
 *
 * Em um sistema real com banco de dados, o ID seria um UUID ou
 * número do banco. Aqui usamos números inteiros positivos.
 *
 * @param {import('express').Request} req - Objeto request do Express
 * @param {import('express').Response} res - Objeto response do Express
 * @param {Function} next - Função next do Express
 * @param {Error} err - Erro de conversão (passado pelo Express se parseInt falhar)
 */
function validateId(req, res, next, err) {
  // Se o Express já capturou um erro de parâmetro não-numérico
  if (err) {
    return next(new BadRequestError("O parâmetro 'id' deve ser um número inteiro válido."));
  }

  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id < 1) {
    return next(new BadRequestError("O parâmetro 'id' deve ser um número inteiro positivo."));
  }

  // Atualiza req.params.id para o valor numérico (seguro para uso posterior)
  req.params.id = id;
  next();
}

/**
 * Valida os parâmetros de filtragem na query string.
 *
 * PARÂMETROS ACEITOS:
 * -------------------
 * - titulo: filtra por título (case-insensitive, parcial)
 * - autor: filtra por autor (case-insensitive, parcial)
 * - genero: filtro exato por gênero
 * - ano: filtro exato por ano de publicação
 * - isbn: filtro exato por ISBN
 * - ordenar: campo para ordenação ('titulo', 'autor', 'ano')
 * - direcao: 'asc' (padrão) ou 'desc'
 * - pagina: número da página (padrão: 1)
 * - limite: itens por página (padrão: 10, máximo: 100)
 *
 * @param {import('express').Request} req - Objeto request do Express
 * @param {import('express').Response} res - Objeto response do Express
 * @param {Function} next - Função next do Express
 */
function validateFilters(req, res, next) {
  const { ordenar, direcao, pagina, limite } = req.query;

  // Valida campo de ordenação
  const camposOrdenacaoPermitidos = ['titulo', 'autor', 'ano'];
  if (ordenar && !camposOrdenacaoPermitidos.includes(ordenar)) {
    return next(new BadRequestError(
      `Campo de ordenação inválido. Permitidos: ${camposOrdenacaoPermitidos.join(', ')}.`
    ));
  }

  // Valida direção da ordenação
  if (direcao && direcao !== 'asc' && direcao !== 'desc') {
    return next(new BadRequestError("O campo 'direcao' deve ser 'asc' ou 'desc'."));
  }

  // Valida paginação
  const paginaNum = Number(pagina);
  const limiteNum = Number(limite);

  if (pagina !== undefined && (!Number.isInteger(paginaNum) || paginaNum < 1)) {
    return next(new BadRequestError("O campo 'pagina' deve ser um número inteiro positivo."));
  }

  if (limite !== undefined) {
    if (!Number.isInteger(limiteNum) || limiteNum < 1 || limiteNum > 100) {
      return next(new BadRequestError("O campo 'limite' deve ser um número entre 1 e 100."));
    }
  }

  // Normaliza valores para tipos corretos
  if (pagina !== undefined) req.query.pagina = paginaNum;
  if (limite !== undefined) req.query.limite = limiteNum;

  next();
}

module.exports = { validateBook, validateId, validateFilters };
