/**
 * ============================================================
 * CAMADA DE DADOS — ARMAZENAMENTO EM MEMÓRIA
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ----------------------------------
 * Para este exemplo educacional, um array em memória é a escolha
 * ideal porque:
 *   1. Não requer instalação de banco de dados
 *   2. Permite focar nos conceitos de API REST
 *   3. Operações são O(1) para push/pop e O(n) para busca —
 *      suficiente para demonstração
 *
 * ESTRUTURA DE DADOS ESCOLHIDA: Array de Objetos
 * -----------------------------------------------
 * Cada livro é um objeto com propriedades bem definidas.
 * Usamos array porque:
 *   - INSERT (POST): O(1) — push no final do array
 *   - READ (GET all): O(n) — percorre o array
 *   - UPDATE/DELETE: O(n) — findIndex + splice
 *
 * Em produção, um banco relacional (PostgreSQL) ou NoSQL (MongoDB)
 * seria mais adequado para escalabilidade e persistência.
 *
 * IDENTIFICADORES:
 * -----------------
 * Usamos números inteiros sequenciais (1, 2, 3...) como ID.
 * Em sistemas reais, UUIDs são preferidos porque:
 *   - São imprevisíveis (segurança por obscuridade)
 *   - Podem ser gerados sem consulta ao banco
 *   - Evitam problemas de escalabilidade distribuída
 *
 * DADOS INICIAIS (SEED):
 * -----------------------
 * Populamos o array com dados de exemplo para que a API já
 * responda meaningfulmente ao primeiro teste.
 */

/**
 * Array principal que armazena todos os livros.
 * @type {Array<{id: number, titulo: string, autor: string, ano: number|null, isbn: string|null, genero: string|null}>}
 */
let books = [
  {
    id: 1,
    titulo: "Dom Casmurro",
    autor: "Machado de Assis",
    ano: 1899,
    isbn: "978-85-359-0277-5",
    genero: "Romance",
  },
  {
    id: 2,
    titulo: "Memórias Póstumas de Brás Cubas",
    autor: "Machado de Assis",
    ano: 1881,
    isbn: "978-85-359-0276-8",
    genero: "Romance",
  },
  {
    id: 3,
    titulo: "O Senhor dos Anéis",
    autor: "J.R.R. Tolkien",
    ano: 1954,
    isbn: "978-0-618-12911-5",
    genero: "Fantasia",
  },
  {
    id: 4,
    titulo: "1984",
    autor: "George Orwell",
    ano: 1949,
    isbn: "978-0-451-52493-5",
    genero: "Distopia",
  },
  {
    id: 5,
    titulo: "Cem Anos de Solidão",
    autor: "Gabriel García Márquez",
    ano: 1967,
    isbn: "978-958-42-1023-3",
    genero: "Realismo Mágico",
  },
];

/**
 * Próximo ID a ser atribuído a um novo livro.
 * Incrementado a cada POST para garantir unicidade.
 * @type {number}
 */
let nextId = 6; // Começa após o último ID dos dados iniciais

/**
 * Retorna uma cópia profunda do array de livros.
 *
 * POR QUE COPIAR?
 * ----------------
 * Retornar o array original permitiria que o chamador modificasse
 * os dados internos diretamente (mutação acidental). Criamos uma
 * cópia com spread operator (...) para garantir imutabilidade
 * dos dados a partir da perspectiva do chamador.
 *
 * @returns {Array} Cópia superficial do array de livros
 */
function getAllBooks() {
  return [...books];
}

/**
 * Busca um livro pelo ID.
 *
 * @param {number} id - ID numérico do livro
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function getBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Adiciona um novo livro ao array.
 *
 * @param {Object} bookData - Dados do novo livro (sem id)
 * @returns {Object} Livro criado com ID atribuído
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Atribui ID sequencial e incrementa o contador
    ...bookData,  // Espalha os dados fornecidos (titulo, autor, etc.)
  };
  books.push(newBook); // O(1) — adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update)
  // Isso permite PUT parcial: o usuário envia só o que quer mudar
  books[index] = {
    ...books[index],       // Mantém todos os campos existentes
    ...updates,            // Sobrescreve com os novos valores
    id: books[index].id,   // Garante que o ID não seja sobrescrito acidentalmente
  };

  return books[index];
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} true se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false;
  }

  // splice remove o elemento e retorna um array com ele
  // O( n ) no pior caso porque pode precisar deslocar elementos
  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas calculadas
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      totalLivros: 0,
      totalAutores: 0,
      generos: {},
      anoMedio: null,
    };
  }

  // Set para contar autores únicos (elimina duplicatas automaticamente)
  const autoresUnicos = new Set(books.map((book) => book.autor.toLowerCase()));

  // Contagem por gênero
  const generos = {};
  books.forEach((book) => {
    if (book.genero) {
      generos[book.genero] = (generos[book.genero] || 0) + 1;
    }
  });

  // Ano médio dos livros (exclui nulls)
  const anosComValor = books.filter((book) => book.ano !== null && book.ano !== undefined);
  const anoMedio =
    anosComValor.length > 0
      ? anosComValor.reduce((sum, book) => sum + book.ano, 0) / anosComValor.length
      : null;

  return {
    totalLivros: total,
    totalAutores: autoresUnicos.size,
    generos,
    anoMedio: anoMedio ? Math.round(anoMedio * 100) / 100 : null, // 2 casas decimais
  };
}

/**
 * Exporta todas as funções da camada de dados.
 *
 * Usamos exports.módulo em vez de module.exports = {...} porque
 * facilita a adição futura de novas funções sem quebrar imports.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
