/**
 * ============================================================
 * ROTAS DA API — GERENCIAMENTO DE LIVROS
 * ============================================================
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar rotas em arquivos distintos segue o princípio de
 * responsabilidade única. O arquivo app.js se preocupa com a
 * configuração do servidor, enquanto routes/books.js cuida
 * exclusivamente das regras de negócio relacionadas a livros.
 *
 * Em projetos maiores, poderíamos ter:
 *   - routes/auth.js (autenticação)
 *   - routes/users.js (usuários)
 *   - routes/stats.js (estatísticas)
 *
 * CONVENÇÕES REST ADOTADAS:
 * --------------------------
 * | Método  | Caminho        | Ação                    | Status Code Sucesso |
 * |---------|----------------|-------------------------|---------------------|
 * | GET     | /books         | Listar todos            | 200 OK              |
 * | GET     | /books/:id     | Buscar um               | 200 OK              |
 * | POST    | /books         | Criar novo              | 201 Created           |
 * | PUT     | /books/:id     | Atualizar completo      | 200 OK              |
 * | DELETE  | /books/:id     | Excluir                 | 204 No Content        |
 *
 * PADRÃO DE RESPOSTA JSON:
 * -------------------------
 * Todas as respostas de sucesso seguem o formato:
 *   { success: true, data: <dados> }
 *
 * Isso permite expansão futura para incluir metadados como:
 *   { success: true, data: [...], meta: { pagina, total } }
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente

// Importações da camada de dados e middleware
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('../data/books');
const { asyncHandler } = require('../middleware/errorHandler');
const { validateBook, validateId, validateFilters } = require('../middleware/validation');
const { NotFoundError } = require('../errors/ErrorHandler');

/**
 * GET /books
 * Lista todos os livros com suporte a filtragem e paginação.
 *
 * PARÂMETROS DE QUERY (opcionais):
 * ---------------------------------
 * - titulo: string — filtra por título (parcial, case-insensitive)
 * - autor: string — filtra por autor (parcial, case-insensitive)
 * - genero: string — filtra por gênero (exato)
 * - ano: number — filtra por ano de publicação (exato)
 * - isbn: string — filtra por ISBN (exato)
 * - ordenar: string — campo para ordenação ('titulo', 'autor', 'ano')
 * - direcao: 'asc' | 'desc' — direção da ordenação (padrão: 'asc')
 * - pagina: number — número da página (padrão: 1)
 * - limite: number — itens por página (padrão: 10, máximo: 100)
 *
 * RESPOSTA:
 * ----------
 * { success: true, data: [...], meta: { pagina, limite, total } }
 *
 * EXEMPLO DE CURL:
 * -----------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por autor
 * curl "http://localhost:3000/books?autor=machado"
 *
 * # Ordenar por ano (decrescente) com paginação
 * curl "http://localhost:3000/books?ordenar=ano&direcao=desc&pagina=1&limite=2"
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Aplica filtros se parâmetros de query forem fornecidos
    let result = getAllBooks();

    const { titulo, autor, genero, ano, isbn } = req.query;

    if (titulo) {
      // toLowerCase() para comparação case-insensitive
      // includes() para busca parcial (substrings)
      result = result.filter((book) =>
        book.titulo.toLowerCase().includes(titulo.toLowerCase())
      );
    }

    if (autor) {
      result = result.filter((book) =>
        book.autor.toLowerCase().includes(autor.toLowerCase())
      );
    }

    if (genero) {
      result = result.filter((book) => book.genero === genero);
    }

    if (ano) {
      result = result.filter((book) => book.ano === Number(ano));
    }

    if (isbn) {
      result = result.filter((book) => book.isbn === isbn);
    }

    // Ordenação
    const { ordenar, direcao } = req.query;
    if (ordenar && ['titulo', 'autor', 'ano'].includes(ordenar)) {
      result.sort((a, b) => {
        let valA = a[ordenar] || '';
        let valB = b[ordenar] || '';

        // Normaliza para comparação
        if (typeof valA === 'string') valA = valA.toLowerCase();
        if (typeof valB === 'string') valB = valB.toLowerCase();

        if (valA < valB) return direcao === 'desc' ? 1 : -1;
        if (valA > valB) return direcao === 'desc' ? -1 : 1;
        return 0;
      });
    } else if (direcao) {
      // Se só direcao foi fornecida sem ordenar, ordena por ID padrão
      result.sort((a, b) => direcao === 'desc' ? b.id - a.id : a.id - b.id);
    }

    // Paginação
    const pagina = req.query.pagina || 1;
    const limite = req.query.limite || 10;

    // Math.max para garantir que pagina não seja menor que 1
    const inicio = (pagina - 1) * limite;
    const livrosPaginados = result.slice(inicio, inicio + limite);

    // Resposta com metadados de paginação
    res.json({
      success: true,
      data: livrosPaginados,
      meta: {
        pagina: Number(pagina),
        limite: Number(limite),
        total: result.length,
        totalPages: Math.ceil(result.length / limite),
      },
    });
  })
);

/**
 * GET /books/:id
 * Busca um livro específico pelo ID.
 *
 * PARÂMETROS DE ROTA:
 * --------------------
 * - id: number — ID numérico do livro
 *
 * RESPOSTA:
 * ----------
 * { success: true, data: { id, titulo, autor, ... } }
 *
 * EXEMPLO DE CURL:
 * -----------------
 * curl http://localhost:3000/books/1
 * curl http://localhost:3000/books/999  // Retorna 404
 */
router.get(
  '/books/:id',
  asyncHandler(async (req, res, next) => {
    // Valida se o ID é um número válido
    validateId(req, res, next);

    const book = getBookById(req.params.id);

    if (!book) {
      // Lança NotFoundError em vez de retornar manualmente 404
      // Isso permite que o errorHandler trate de forma consistente
      return next(new NotFoundError(`Livro com ID ${req.params.id} não encontrado.`));
    }

    res.json({
      success: true,
      data: book,
    });
  })
);

/**
 * POST /books
 * Cria um novo livro.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * ----------------------------
 * {
 *   "titulo": "O Nome do Vento",
 *   "autor": "Patrick Rothfuss",
 *   "ano": 2007,
 *   "isbn": "978-85-638-0610-4",
 *   "genero": "Fantasia"
 * }
 *
 * CAMPOS OBRIGATÓRIOS: titulo, autor
 * CAMPOS OPCIONAIS: ano, isbn, genero
 *
 * RESPOSTA:
 * ----------
 * { success: true, data: <livro criado com ID> }
 * Status: 201 Created
 *
 * EXEMPLO DE CURL:
 * -----------------
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"titulo":"O Nome do Vento","autor":"Patrick Rothfuss","ano":2007,"genero":"Fantasia"}'
 */
router.post(
  '/books',
  asyncHandler(async (req, res, next) => {
    // Aplica validação dos dados de entrada
    validateBook(req, res, next);

    const book = createBook({
      titulo: req.body.titulo.trim(),
      autor: req.body.autor.trim(),
      ano: req.body.ano ? Number(req.body.ano) : null,
      isbn: req.body.isbn ? String(req.body.isbn).trim() : null,
      genero: req.body.genero ? req.body.genero.trim() : null,
    });

    // 201 Created indica que um novo recurso foi criado com sucesso
    res.status(201).json({
      success: true,
      data: book,
    });
  })
);

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente.
 *
 * NOTA SOBRE PUT vs PATCH:
 * -------------------------
 * PUT é definido pela especificação HTTP como uma operação de
 * SUBSTITUIÇÃO COMPLETA. Isso significa que todos os campos
 * devem ser fornecidos. No entanto, para melhor experiência
 * do desenvolvedor, implementamos um partial update (atualização
 * parcial) — campos não fornecidos mantêm seus valores anteriores.
 *
 * Se quiser comportamento PUT estrito (todos os campos obrigatórios),
 * basta remover a lógica de merge e exigir todos os campos.
 *
 * CORPO DA REQUISIÇÃO:
 * ---------------------
 * {
 *   "titulo": "Dom Casmurro (Edição Comentada)",
 *   "autor": "Machado de Assis",
 *   "ano": 1899,
 *   "isbn": "978-85-359-0277-5",
 *   "genero": "Romance Realista"
 * }
 *
 * RESPOSTA:
 * ----------
 * { success: true, data: <livro atualizado> }
 *
 * EXEMPLO DE CURL:
 * -----------------
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"titulo":"Dom Casmurro","autor":"Machado de Assis","ano":1899,"genero":"Romance"}'
 */
router.put(
  '/books/:id',
  asyncHandler(async (req, res, next) => {
    validateId(req, res, next);
    validateBook(req, res, next);

    const bookExists = getBookById(req.params.id);

    if (!bookExists) {
      return next(new NotFoundError(`Livro com ID ${req.params.id} não encontrado.`));
    }

    // Monta os dados de atualização (apenas campos fornecidos)
    const updates = {};

    if (req.body.titulo !== undefined) {
      updates.titulo = req.body.titulo.trim();
    }
    if (req.body.autor !== undefined) {
      updates.autor = req.body.autor.trim();
    }
    if (req.body.ano !== undefined) {
      updates.ano = req.body.ano ? Number(req.body.ano) : null;
    }
    if (req.body.isbn !== undefined) {
      updates.isbn = req.body.isbn ? String(req.body.isbn).trim() : null;
    }
    if (req.body.genero !== undefined) {
      updates.genero = req.body.genero ? req.body.genero.trim() : null;
    }

    const updatedBook = updateBook(req.params.id, updates);

    res.json({
      success: true,
      data: updatedBook,
    });
  })
);

/**
 * DELETE /books/:id
 * Exclui um livro pelo ID.
 *
 * RESPOSTA:
 * ----------
 * Sem corpo (204 No Content) — padrão REST para exclusão bem-sucedida.
 * Se o livro não existir, retorna 404 com mensagem de erro.
 *
 * EXEMPLO DE CURL:
 * -----------------
 * curl -X DELETE http://localhost:3000/books/1
 * curl -X DELETE http://localhost:3000/books/999  // Retorna 404
 */
router.delete(
  '/books/:id',
  asyncHandler(async (req, res, next) => {
    validateId(req, res, next);

    const deleted = deleteBook(req.params.id);

    if (!deleted) {
      return next(new NotFoundError(`Livro com ID ${req.params.id} não encontrado.`));
    }

    // 204 No Content — padrão REST para operações de exclusão
    // Não enviamos corpo porque não há recurso para retornar
    res.status(204).send();
  })
);

module.exports = router;
