## Arquivo 8: `src/app.js`

```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO PRINCIPAL DO SERVIDOR EXPRESS
 * ============================================================
 *
 * POR QUE ESTRUTURA ASSIM?
 * -------------------------
 * O arquivo app.js é o ponto de entrada que orquestra todos
 * os módulos. Ele segue a ordem lógica:
 *   1. Configurações globais (CORS, JSON parsing)
 *   2. Rotas da API
 *   3. Middleware de tratamento de erros (SEMPRE por último)
 *   4. Roteador para rotas não encontradas (404)
 *   5. Inicialização do servidor
 *
 * ORDEM DOS MIDDLEWARES É CRÍTICA:
 * ----------------------------------
 * No Express, middlewares são executados na ordem em que são
 * registrados. Por isso:
 *   - Middleware de parsing (body-parser) vem PRIMEIRO
 *   - Rotas vêm DEPOIS do parsing
 *   - ErrorHandler vem POR ÚLTIMO (captura erros de tudo acima)
 */

const express = require('express');
const booksRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a aplicação Express
const app = express();

/**
 * CONFIGURAÇÕES GLOBAIS
 * ----------------------
 */

// body-parser embutido no Express 4.16+
// Parseia o corpo de requisições com Content-Type: application/json
// Isso torna req.body disponível em todas as rotas
app.use(express.json());

// CORS (Cross-Origin Resource Sharing)
// Permite que frontends de diferentes origens acessem a API.
// Em produção, substitua '*' pelo domínio do frontend.
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * ROTAS DA API
 * -------------
 * As rotas são registradas antes do middleware de erro.
 * Cada router é mountado em um prefixo de caminho.
 */
app.use('/books', booksRoutes);
app.use('/', statsRoutes); // Stats usa raiz porque já tem /stats na rota

/**
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ----------------------------------
 * Registrado POR ÚLTIMO para capturar erros de todas as rotas.
 * Deve ter EXATAMENTE 4 parâmetros (err, req, res, next).
 */
app.use(errorHandler);

/**
 * ROTA PARA RECURSOS NÃO ENCONTRADOS (404)
 * ------------------------------------------
 * Se nenhuma rota corresponder, o Express continua até o
 * errorHandler. Mas como não houve erro lançado, precisamos
 * lançar um NotFoundError manualmente para que o errorHandler
 * responda com 404 em vez de 500.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./errors/ErrorHandler');
  next(new NotFoundError(`Rota ${req.method} ${req.originalUrl} não encontrada.`));
});

/**
 * INICIALIZAÇÃO DO SERVIDOR
 * --------------------------
 */
const PORT = process.env.PORT || 3000; // Porta configurável via variável de ambiente

app.listen(PORT, () => {
  console.log(`✅ Servidor rodando na porta ${PORT}`);
  console.log(`📚 API de Livros disponível em http://localhost:${PORT}`);
  console.log(`\nEndpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/books          — Listar livros`);
  console.log(`  GET    http://localhost:${PORT}/books/:id      — Buscar livro`);
  console.log(`  POST   http://localhost:${PORT}/books          — Criar livro`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id      — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id      — Excluir livro`);
  console.log(`  GET    http://localhost:${PORT}/stats          — Estatísticas`);
});

module.exports = app;
```

