## File 2: `data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For an educational example, an in-memory array avoids the
 * complexity of setting up a database while still demonstrating all CRUD
 * operations. In production, you would replace this module with a database
 * adapter (e.g., MongoDB, PostgreSQL) — the route handlers remain unchanged.
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and are simple to iterate
 * for filtering/sorting. For larger datasets, a Map or object keyed by ID would
 * give O(1) lookups by ID instead of O(n).
 */

// ---------------------------------------------------------------------------
// Seed data — so the API isn't empty when first started
// ---------------------------------------------------------------------------
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8,
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7,
  },
  {
    id: 4,
    title: 'The Art of War',
    author: 'Sun Tzu',
    genre: 'Philosophy',
    publishedYear: -500, // BCE year represented as negative
    rating: 4.3,
  },
  {
    id: 5,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    rating: 4.6,
  },
];

// ---------------------------------------------------------------------------
// Helper: generate a unique numeric ID
// In production you'd use a UUID library or let the database handle it.
// ---------------------------------------------------------------------------
let nextId = books.length > 0 ? Math.max(...books.map((b) => b.id)) + 1 : 1;

/**
 * Returns all books (used by GET /books and GET /stats).
 * @returns {Array<Object>} Array of book objects.
 */
function getAllBooks() {
  return [...books]; // Return a copy to prevent external mutation
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The book's unique identifier.
 * @returns {Object|undefined} The book object, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adds a new book to the store and assigns it the next available ID.
 * @param {Object} bookData - The book data (without an id field).
 * @returns {Object} The newly created book with its assigned ID.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData,
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID. Mutates the store in place.
 * @param {number} id - The book's unique identifier.
 * @param {Object} updates - Fields to update (partial update supported).
 * @returns {Object|undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Merge only the provided fields (partial update pattern)
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by ID.
 * @param {number} id - The book's unique identifier.
 * @returns {boolean} True if deleted, false if not found.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

// ---------------------------------------------------------------------------
// Export all store operations as a single module
// This makes it easy to swap the implementation later (e.g., for a DB).
// ---------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
```

