## File 3: `middleware/errors.js` — Custom Error Classes & Middleware

```javascript
/**
 * @fileoverview Custom error hierarchy and Express error-handling middleware.
 *
 * WHY CUSTOM ERROR CLASSES? Built-in JavaScript errors (Error, TypeError) don't
 * carry HTTP semantics. By creating subclasses with an `statusCode` property,
 * route handlers can throw domain-specific errors and the central error
 * middleware can translate them into proper HTTP responses automatically.
 *
 * WHY 4-PARAMETER MIDDLEWARE? Express identifies error-handling middleware by
 * its signature: (err, req, res, next). Any middleware with fewer parameters is
 * treated as regular middleware. This convention lets us place the error handler
 * at the end of the middleware chain.
 */

// ---------------------------------------------------------------------------
// Base error class — all custom errors inherit from this
// ---------------------------------------------------------------------------
class BaseError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    // Preserve the correct stack trace in ES6 classes
    Object.setPrototypeOf(this, BaseError.prototype);
  }
}

/**
 * Thrown when a requested resource does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends BaseError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

/**
 * Thrown when client-supplied data fails validation.
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends BaseError {
  constructor(message = 'Validation failed', details = null) {
    super(message, 400);
    this.details = details; // Optional: array of specific field errors
  }
}

/**
 * Thrown for unexpected server-side failures.
 * Maps to HTTP 500 Internal Server Error.
 */
class InternalServerError extends BaseError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500);
  }
}

// ---------------------------------------------------------------------------
// Centralized error-handling middleware
// Placed AFTER all routes so it catches errors from anywhere in the chain.
// ---------------------------------------------------------------------------
const errorHandler = (err, req, res, next) => {
  // Log the full error for server-side debugging
  console.error(`[ERROR] ${err.statusCode || err.code || 500} — ${err.message}`);
  if (process.env.DEBUG === 'true') {
    console.error(err.stack);
  }

  // Build a consistent JSON error response
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode,
    },
  };

  // Include validation details when available (helps the client fix input)
  if (err.details) {
    response.error.details = err.details;
  }

  res.status(err.statusCode || 500).json(response);
};

// ---------------------------------------------------------------------------
// Request logger middleware — useful for debugging and monitoring
// ---------------------------------------------------------------------------
const requestLogger = (req, res, next) => {
  const start = Date.now();
  // Log after the response is sent so we can include the status code
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.originalUrl} ` +
        `${res.statusCode} — ${duration}ms`
    );
  });
  next();
};

// ---------------------------------------------------------------------------
// Export everything so server.js can wire them up
// ---------------------------------------------------------------------------
module.exports = {
  BaseError,
  NotFoundError,
  ValidationError,
  InternalServerError,
  errorHandler,
  requestLogger,
};
```

