## File 4: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * @fileoverview RESTful route handlers for the /books resource.
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module makes the main
 * server.js file lean and allows each route file to be tested independently.
 * Express's `Router()` creates a mini-app that can be mounted at any path.
 *
 * WHY ASYNC/AWAIT? Even though our store is synchronous, using async/await
 * prepares the code for when we swap in an asynchronous database. It also
 * lets us use try/catch blocks cleanly instead of .catch() chains.
 */

const express = require('express');
const router = express.Router();
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('../data/books');
const { NotFoundError, ValidationError } = require('../middleware/errors');

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
//
// Query parameters (all optional):
//   genre        — exact match on genre (case-insensitive)
//   author       — substring match on author name
//   minRating    — minimum rating (0–5)
//   publishedYearAfter — only books published after this year
//
// Example: GET /books?genre=Fiction&minRating=4.5
// ---------------------------------------------------------------------------
router.get('/', (req, res) => {
  let results = getAllBooks();

  // --- Filter by genre (case-insensitive exact match) -------------------
  if (req.query.genre) {
    const genreLower = req.query.genre.toLowerCase();
    results = results.filter((book) => book.genre.toLowerCase() === genreLower);
  }

  // --- Filter by author (substring, case-insensitive) ------------------
  if (req.query.author) {
    const authorLower = req.query.author.toLowerCase();
    results = results.filter((book) =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // --- Filter by minimum rating ----------------------------------------
  if (req.query.minRating !== undefined) {
    const minRating = parseFloat(req.query.minRating);
    if (isNaN(minRating)) {
      throw new ValidationError('minRating must be a number');
    }
    results = results.filter((book) => book.rating >= minRating);
  }

  // --- Filter by published year (strictly after the given year) --------
  if (req.query.publishedYearAfter !== undefined) {
    const year = parseInt(req.query.publishedYearAfter, 10);
    if (isNaN(year)) {
      throw new ValidationError('publishedYearAfter must be an integer');
    }
    results = results.filter((book) => book.publishedYear > year);
  }

  // Return the (possibly filtered) list with a 200 status
  res.json({ success: true, count: results.length, data: results });
});

// ---------------------------------------------------------------------------
// GET /books/:id — Retrieve a single book by its numeric ID
// ---------------------------------------------------------------------------
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validate that the ID parameter is actually a number
  if (isNaN(id)) {
    throw new ValidationError('ID must be a numeric value');
  }

  const book = getBookById(id);
  if (!book) {
    // NotFoundError is caught by the central error handler and turned into
    // a 404 JSON response automatically.
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  res.json({ success: true, data: book });
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
//
// Request body (JSON):
//   {
//     "title": "...",          // required, string
//     "author": "...",         // required, string
//     "genre": "...",          // required, string
//     "publishedYear": 1925,   // optional, integer
//     "rating": 4.5            // optional, number 0–5
//   }
// ---------------------------------------------------------------------------
router.post('/', (req, res) => {
  const { title, author, genre, publishedYear, rating } = req.body;

  // --- Validate required fields ----------------------------------------
  const errors = [];
  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push({ field: 'genre', message: 'Genre is required and must be a non-empty string' });
  }
  if (publishedYear !== undefined && !Number.isInteger(publishedYear)) {
    errors.push({ field: 'publishedYear', message: 'Published year must be an integer' });
  }
  if (rating !== undefined && (typeof rating !== 'number' || rating < 0 || rating > 5)) {
    errors.push({ field: 'rating', message: 'Rating must be a number between 0 and 5' });
  }

  if (errors.length > 0) {
    throw new ValidationError('Invalid input data', errors);
  }

  const newBook = createBook({
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  });

  // 201 Created is the semantically correct status for resource creation.
  // We include the Location header so clients know where to find the new resource.
  res.status(201).header('Location', `/books/${newBook.id}`).json({
    success: true,
    data: newBook,
  });
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Fully replace an existing book
// (Use PATCH in a real app for partial updates; PUT implies full replacement.)
// ---------------------------------------------------------------------------
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('ID must be a numeric value');
  }

  const existing = getBookById(id);
  if (!existing) {
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  const { title, author, genre, publishedYear, rating } = req.body;

  // Reuse the same validation logic as POST
  const errors = [];
  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push({ field: 'genre', message: 'Genre is required and must be a non-empty string' });
  }
  if (publishedYear !== undefined && !Number.isInteger(publishedYear)) {
    errors.push({ field: 'publishedYear', message: 'Published year must be an integer' });
  }
  if (rating !== undefined && (typeof rating !== 'number' || rating < 0 || rating > 5)) {
    errors.push({ field: 'rating', message: 'Rating must be a number between 0 and 5' });
  }

  if (errors.length > 0) {
    throw new ValidationError('Invalid input data', errors);
  }

  const updated = updateBook(id, {
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  });

  res.json({ success: true, data: updated });
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Remove a book by ID
// Returns 204 No Content on successful deletion (no response body).
// ---------------------------------------------------------------------------
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('ID must be a numeric value');
  }

  const deleted = deleteBook(id);
  if (!deleted) {
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  // 204 tells the client the resource was removed and there's nothing to return.
  res.status(204).end();
});

module.exports = router;
```

