## File 5: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * @fileoverview GET /stats — Aggregate statistics about the book collection.
 *
 * WHY A SEPARATE ENDPOINT? Statistics are a derived view, not a resource.
 * Placing them under /stats (not /books/stats) keeps the API RESTful and
 * makes it clear this is an aggregate operation, not a sub-resource.
 */

const express = require('express');
const router = express.Router();
const { getAllBooks } = require('../data/books');

/**
 * GET /stats
 *
 * Returns:
 *   totalBooks       — total number of books in the store
 *   averageRating    — mean rating across all books (null if empty)
 *   genreBreakdown   — count of books per genre
 *   yearRange        — { min, max } published years
 *   topRatedBooks    — up to 3 highest-rated books
 */
router.get('/', (req, res) => {
  const books = getAllBooks();

  // Guard against empty store
  if (books.length === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        averageRating: null,
        genreBreakdown: {},
        yearRange: null,
        topRatedBooks: [],
      },
    });
  }

  // --- Total count -----------------------------------------------------
  const totalBooks = books.length;

  // --- Average rating --------------------------------------------------
  const sumRatings = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = parseFloat((sumRatings / totalBooks).toFixed(2));

  // --- Genre breakdown -------------------------------------------------
  // Reduce the array into an object mapping genre → count.
  const genreBreakdown = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // --- Year range ------------------------------------------------------
  const years = books.map((b) => b.publishedYear);
  const yearRange = { min: Math.min(...years), max: Math.max(...years) };

  // --- Top rated (up to 3) ---------------------------------------------
  const topRatedBooks = [...books]
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 3);

  res.json({
    success: true,
    data: {
      totalBooks,
      averageRating,
      genreBreakdown,
      yearRange,
      topRatedBooks,
    },
  });
});

module.exports = router;
```

