## File 6: `server.js` — Application Entry Point

```javascript
/**
 * @fileoverview Express application bootstrap.
 *
 * WHY THIS ORDER OF MIDDLEWARE?
 *   1. JSON parser — must come before route handlers so req.body is populated.
 *   2. Request logger — logs every incoming request.
 *   3. Route mounts  — actual API routes.
 *   4. Error handler — MUST be last; Express only calls it when an error is
 *      thrown or next(err) is invoked somewhere up the chain.
 *
 * WHY CORS HEADERS? Adding Access-Control-Allow-Origin lets browsers make
 * cross-origin requests (e.g., from a frontend app running on a different port).
 * In production you'd restrict this to specific origins for security.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler, requestLogger } = require('./middleware/errors');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Middleware stack (order matters!)
// ---------------------------------------------------------------------------

// Parse JSON request bodies up to 10kb (default Express limit)
app.use(express.json({ limit: '10kb' }));

// Log every request for debugging / monitoring
app.use(requestLogger);

// Allow cross-origin requests from any origin (educational — restrict in prod)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  // Handle preflight requests immediately
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

// ---------------------------------------------------------------------------
// Mount route modules at their respective paths
// ---------------------------------------------------------------------------
app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

// ---------------------------------------------------------------------------
// Root endpoint — simple health check / API info
// ---------------------------------------------------------------------------
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book Management API',
    endpoints: {
      books: 'GET /books, GET /books/:id, POST /books, PUT /books/:id, DELETE /books/:id',
      stats: 'GET /stats',
    },
  });
});

// ---------------------------------------------------------------------------
// Catch-all for undefined routes — returns 404 instead of Express's default HTML
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: { message: `Route ${req.method} ${req.originalUrl} not found` },
  });
});

// ---------------------------------------------------------------------------
// Centralized error handler — MUST be the last middleware
// ---------------------------------------------------------------------------
app.use(errorHandler);

// ---------------------------------------------------------------------------
// Start the server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`📚 Book Management API running on http://localhost:${PORT}`);
  console.log(`   Try: curl http://localhost:${PORT}/books`);
});

module.exports = app;
```

