## 2. `src/errors.js` — Classes de Erro Personalizadas

```javascript
/**
 * ============================================================
 * src/errors.js
 * ============================================================
 *
 * CLASSES DE ERRO PERSONALIZADAS
 *
 * Por que criar classes de erro customizadas em vez de usar
 * apenas Error nativo?
 *
 * 1. PERMITE DISTINGUIR TIPOS DE ERRO no middleware de tratamento:
 *    - NotFoundError → resposta 404
 *    - ValidationError → resposta 400
 *    - InternalError → resposta 500
 *
 * 2. CADA CLASSE CARREGA SEU PRÓPRIO STATUS HTTP, tornando o
 *    middleware de erro mais declarativo e menos propenso a erros.
 *
 * 3. MELHORA A LEGIBILIDADE: ao ver "throw new NotFoundError()",
 *    fica claro imediatamente qual foi a intenção do desenvolvedor.
 * ============================================================
 */

/**
 * Classe base para todos os erros da API.
 * Estende Error nativo e adiciona um código de status HTTP.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor da classe Error nativa

    // Mantém a stack trace correta mesmo após herdar de Error
    this.name = 'ApiError';
    this.statusCode = statusCode;

    // Captura o nome da classe para uso em logs e tratamento específico
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/**
 * Erro disparado quando um recurso solicitado não é encontrado.
 * Mapeia para HTTP 404 Not Found — padrão REST.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404); // Status 404 herdado do REST
    this.name = 'NotFoundError';
  }
}

/**
 * Erro disparado quando os dados enviados pelo cliente são inválidos.
 * Mapeia para HTTP 400 Bad Request — padrão REST.
 */
class ValidationError extends ApiError {
  constructor(message = 'Dados de entrada inválidos') {
    super(message, 400); // Status 400 herdado do REST
    this.name = 'ValidationError';
  }
}

/**
 * Erro disparado quando o cliente tenta uma operação não permitida.
 * Mapeia para HTTP 405 Method Not Allowed — padrão REST.
 */
class MethodNotAllowedError extends ApiError {
  constructor(message = 'Método não permitido') {
    super(message, 405);
    this.name = 'MethodNotAllowedError';
  }
}

/**
 * Erro disparado quando ocorre um problema interno no servidor.
 * Mapeia para HTTP 500 Internal Server Error — padrão REST.
 */
class InternalError extends ApiError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500);
    this.name = 'InternalError';
  }
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  MethodNotAllowedError,
  InternalError,
};
```

