## 3. `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * ============================================================
 * src/middleware/errorHandler.js
 * ============================================================
 *
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 *
 * Por que usar um middleware centralizado para erros?
 *
 * 1. O Express permite definir um middleware com 4 parâmetros
 *    (err, req, res, next) que captura TODOS os erros lançados
 *    em qualquer rota ou middleware anterior. Isso evita a
 *    necessidade de try/catch em cada handler individualmente.
 *
 * 2. Centraliza a formatação da resposta de erro, garantindo
 *    consistência: { error: 'mensagem', statusCode: NNN }.
 *
 * 3. Em produção, NÃO expomos stack traces ao cliente por
 *    segurança (vazamento de informações internas).
 * ============================================================
 */

const { ApiError } = require('../errors');

/**
 * Middleware que captura e trata todos os erros da aplicação.
 * Deve ser o ÚLTIMO middleware registrado no app Express.
 *
 * @param {Error} err - A exceção lançada em qualquer ponto da pipeline
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
function errorHandler(err, req, res, next) {
  // Determina o status HTTP baseado no tipo do erro
  const statusCode = err instanceof ApiError ? err.statusCode : 500;

  // Em desenvolvimento, incluímos a stack trace para facilitar debugging.
  // Em produção, isso seria omitido por segurança (não expor detalhes internos).
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Monta o corpo da resposta de erro com formato consistente
  const errorResponse = {
    error: err.message,          // Mensagem legível para o cliente
    statusCode,                  // Código HTTP correspondente
  };

  // Adiciona stack trace apenas em ambiente de desenvolvimento
  if (isDevelopment && err.stack) {
    errorResponse.stack = err.stack;
  }

  // Envia a resposta com o status apropriado e corpo JSON
  res.status(statusCode).json(errorResponse);
}

module.exports = errorHandler;
```

