## 5. `src/routes/books.js` — Rotas de Livros

```javascript
/**
 * ============================================================
 * src/routes/books.js
 * ============================================================
 *
 * ROTAS DE LIVROS (CRUD COMPLETO)
 *
 * POR QUE SEPARAR AS ROTAS EM ARQUIVOS DIFERENTES?
 *
 * 1. ORGANIZAÇÃO: conforme a API cresce, ter todas as rotas em
 *    um único arquivo se torna ilegível. Arquivos separados por
 *    domínio (livros, stats, usuários) mantêm o código modular.
 *
 * 2. EXPRESS ROUTER: o Express fornece `express.Router()` que
 *    cria um mini-app de roteamento. Isso permite agrupar rotas,
 *    aplicar middlewares específicos e até montar sub-rotas.
 *
 * 3. CONVENÇÕES REST: cada verbo HTTP mapeia para uma operação:
 *    - GET    → leitura (listagem ou busca)
 *    - POST   → criação
 *    - PUT    → atualização completa
 *    - DELETE → remoção
 *    Isso segue a semântica padrão da web e facilita o consumo
 *    por qualquer cliente HTTP.
 * ============================================================
 */

const express = require('express');
const { NotFoundError, ValidationError } = require('../errors');

// Instancia um roteador separado para as rotas de livros.
// Isso isola o escopo das rotas e permite reutilização.
const router = express.Router();

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA
// ============================================================
//
// Por que usar um array em memória?
//
// 1. PARA FINS EDUCACIONAIS: elimina a complexidade de configurar
//    um banco de dados, permitindo focar nos conceitos de REST,
//    middleware e tratamento de erros.
//
// 2. ESTRUTURA DE DADOS — Array de objetos:
//    - Array: permite operações nativas como .find(), .filter(),
//      .push(), .splice() que são intuitivas para CRUD.
//    - Objetos: cada livro tem propriedades nomeadas (title, author),
//      o que é mais legível que arrays aninhados ou mapas.
//
// 3. POR QUE NÃO USAR MAP? Um Map seria eficiente para buscas por ID,
//    mas perderíamos a capacidade de iterar facilmente para listagem
//    e filtragem múltipla. O array é o compromisso ideal aqui.
// ============================================================

/** Array que armazena todos os livros em memória. */
let books = require('../data/books.json');

/** Contador para gerar IDs únicos automaticamente. */
let nextId = books.length > 0 ? Math.max(...books.map((b) => b.id)) + 1 : 1;

// ============================================================
// VALIDAÇÃO DE ENTRADA
// ============================================================
//
// Por que validar dados de entrada?
//
// 1. SEGURANÇA: previne injeção de dados maliciosos ou corrompidos.
//
// 2. CONSISTÊNCIA: garante que todos os livros tenham o formato
//    esperado, evitando erros em operações posteriores.
//
// 3. FEEDBACK AO CLIENTE: erros de validação claros (400) ajudam
//    os desenvolvedores a corrigirem rapidamente suas requisições.
// ============================================================

/**
 * Valida os campos obrigatórios e tipos de um livro.
 * Lança ValidationError se alguma validação falhar.
 *
 * @param {Object} bookData - Dados do livro a serem validados
 * @returns {void}
 */
function validateBook(bookData) {
  const errors = [];

  // Verifica se o título foi fornecido e é uma string não vazia
  if (!bookData.title || typeof bookData.title !== 'string' || bookData.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string.');
  }

  // Verifica se o autor foi fornecido e é uma string não vazia
  if (!bookData.author || typeof bookData.author !== 'string' || bookData.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string.');
  }

  // Verifica se o ano é um número válido (inteiro entre 0 e o ano atual + 1)
  const currentYear = new Date().getFullYear();
  if (bookData.year === undefined || bookData.year === null) {
    errors.push('O campo "year" é obrigatório.');
  } else if (!Number.isInteger(bookData.year)) {
    errors.push('O campo "year" deve ser um número inteiro.');
  } else if (bookData.year < 0 || bookData.year > currentYear + 1) {
    errors.push(`O campo "year" deve estar entre 0 e ${currentYear + 1}.`);
  }

  // Verifica se o gênero foi fornecido (opcional, mas recomendado)
  if (bookData.genre && typeof bookData.genre !== 'string') {
    errors.push('O campo "genre" deve ser uma string.');
  }

  // Verifica ISBN: formato opcional, mas se fornecido, deve ter 13 dígitos
  if (bookData.isbn !== undefined && bookData.isbn !== null) {
    const isbnStr = String(bookData.isbn);
    if (!/^\d{10}(\d{3})?$/.test(isbnStr)) {
      errors.push('O campo "isbn" deve ter 10 ou 13 dígitos numéricos.');
    }
  }

  // Se houver erros, lança um ValidationError com todas as mensagens
  if (errors.length > 0) {
    throw new ValidationError(errors.join(' '));
  }
}

// ============================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?author=Tolkien"
//   curl "http://localhost:3000/books?genre=Fantasia&year=1954"
//   curl "http://localhost:3000/books?search=senhor"  (busca por título/autor)
// ============================================================

/**
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * Filtros disponíveis via query parameters:
 *   - author    : filtra por autor (case-insensitive, substring match)
 *   - genre     : filtra por gênero (case-insensitive, substring match)
 *   - year      : filtra por ano exato
 *   - search    : busca por título ou autor (substring, case-insensitive)
 *
 * @param {import('express').Request} req - Requisição com query params
 * @param {import('express').Response} res - Resposta com lista de livros
 */
router.get('/', (req, res) => {
  // Começa com todos os livros e aplica filtros sequencialmente.
  // Isso permite combinar múltiplos filtros na mesma requisição.
  let result = [...books];

  const { author, genre, year, search } = req.query;

  // Filtro por autor: comparação case-insensitive com substring match
  if (author) {
    result = result.filter((book) =>
      book.author.toLowerCase().includes(author.toLowerCase())
    );
  }

  // Filtro por gênero:同上
  if (genre) {
    result = result.filter((book) =>
      book.genre.toLowerCase().includes(genre.toLowerCase())
    );
  }

  // Filtro por ano: conversão para número para comparação numérica correta
  if (year) {
    const yearNum = parseInt(year, 10);
    if (!isNaN(yearNum)) {
      result = result.filter((book) => book.year === yearNum);
    }
  }

  // Busca por título ou autor: substring match em ambos os campos
  if (search) {
    const searchLower = search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
    );
  }

  // Retorna a lista filtrada com status 200 OK
  res.json({
    count: result.length,
    data: result,
  });
});

// ============================================================
// GET /books/:id — Obter um livro específico por ID
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  → 404
// ============================================================

/**
 * Retorna um livro específico pelo seu ID.
 * Lança NotFoundError se o ID não existir.
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta com o livro
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
router.get('/:id', (req, res, next) => {
  // Converte ID de string (vem do Express como string) para número
  const id = parseInt(req.params.id, 10);

  // Busca o livro pelo ID usando Array.find() — O(n), suficiente para dados pequenos
  const book = books.find((b) => b.id === id);

  // Se não encontrado, lança NotFoundError que será capturado pelo middleware de erro
  if (!book) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado.`));
  }

  res.json(book);
});

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl -X POST http://localhost:3000/books \
//     -H "Content-Type: application/json" \
//     -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Ficção Científica"}'
// ============================================================

/**
 * Cria um novo livro e o adiciona ao array.
 * Gera automaticamente um ID único baseado no contador nextId.
 *
 * @param {import('express').Request} req - Requisição com body do livro
 * @param {import('express').Response} res - Resposta com o livro criado
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
router.post('/', (req, res, next) => {
  try {
    // Valida os dados de entrada antes de processar
    validateBook(req.body);

    // Cria o novo livro com ID auto-incrementado
    const newBook = {
      id: nextId++,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      year: req.body.year,
      genre: req.body.genre ? req.body.genre.trim() : null,
      isbn: req.body.isbn || null,
    };

    // Adiciona ao array — O(1) para push
    books.push(newBook);

    // Retorna 201 Created (padrão REST para criação de recursos)
    // O corpo contém o recurso criado para que o cliente não precise fazer outra requisição
    res.status(201).json(newBook);
  } catch (error) {
    // Re-lança o erro para o middleware de tratamento
    next(error);
  }
});

// ============================================================
// PUT /books/:id — Atualizar completamente um livro existente
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl -X PUT http://localhost:3000/books/1 \
//     -H "Content-Type: application/json" \
//     -d '{"title":"O Senhor dos Anéis (Ed. Definitiva)","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
//
// NOTA: PUT substitui o recurso INTEIRO. Para atualização parcial,
//       usaríamos PATCH em vez de PUT (não implementado aqui).
// ============================================================

/**
 * Atualiza completamente um livro existente pelo seu ID.
 * Substitui todos os campos pelo que foi enviado no body.
 *
 * @param {import('express').Request} req - Requisição com params.id e body atualizado
 * @param {import('express').Response} res - Resposta com o livro atualizado
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
router.put('/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Encontra o índice do livro no array (mais eficiente que find() + splice())
    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      return next(new NotFoundError(`Livro com ID ${id} não encontrado.`));
    }

    // Valida os dados de entrada antes de atualizar
    validateBook(req.body);

    // Cria o objeto atualizado — mantemos o id original
    const updatedBook = {
      id,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      year: req.body.year,
      genre: req.body.genre ? req.body.genre.trim() : null,
      isbn: req.body.isbn || null,
    };

    // Substitui o livro no array pelo índice encontrado — O(1)
    books[index] = updatedBook;

    // Retorna 200 OK com o recurso atualizado
    res.json(updatedBook);
  } catch (error) {
    next(error);
  }
});

// ============================================================
// DELETE /books/:id — Excluir um livro pelo ID
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl -X DELETE http://localhost:3000/books/1
//   curl -X DELETE http://localhost:3000/books/999  → 404
// ============================================================

/**
 * Exclui um livro do array pelo seu ID.
 * Retorna o livro excluído como confirmação (padrão REST).
 *
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta com o livro excluído
 * @param {import('express').NextFunction} next - Função para encadear middlewares
 */
router.delete('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  // Encontra o índice do livro a ser excluído
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado.`));
  }

  // splice retorna um array com o elemento removido — pegamos o primeiro item
  const [deletedBook] = books.splice(index, 1);

  // Retorna 200 OK com o recurso excluído (padrão REST para DELETE)
  res.json({
    message: 'Livro excluído com sucesso.',
    data: deletedBook,
  });
});

module.exports = router;
```

