## 6. `src/routes/stats.js` — Rotas de Estatísticas

```javascript
/**
 * ============================================================
 * src/routes/stats.js
 * ============================================================
 *
 * ROTAS DE ESTATÍSTICAS
 *
 * Por que estatísticas são um endpoint separado?
 *
 * 1. SEPARAÇÃO DE DOMÍNIOS: estatísticas não são recursos CRUD,
 *    mas sim dados agregados derivados dos livros. Ter um endpoint
 *    próprio (/stats) deixa claro que se trata de uma operação de
 *    leitura analítica, não de manipulação de entidades.
 *
 * 2. PERFORMANCE: cálculos de agregação podem ser custosos.
 *    Isolar essas rotas permite otimizações futuras (cache, etc.)
 *    sem afetar as rotas CRUD principais.
 * ============================================================
 */

const express = require('express');
const router = express.Router();

// Reutilizamos o mesmo array de livros para cálculos
let books = require('../data/books.json');

// ============================================================
// GET /stats — Retornar estatísticas agregadas dos livros
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl http://localhost:3000/stats
//
// RESPOSTA ESPERADA:
//   {
//     "total": 5,
//     "avgYear": 1924.4,
//     "genres": { "Fantasia": 1, "Ficção Científica": 2, ... },
//     "authors": ["J.R.R. Tolkien", "George Orwell", ...],
//     "oldestBook": { "title": "...", "year": 1899 },
//     "newestBook": { "title": "...", "year": 1967 }
//   }
// ============================================================

/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Estatísticas calculadas:
 *   - total: quantidade total de livros
 *   - avgYear: ano médio de publicação (arredondado para 1 casa decimal)
 *   - genres: contagem de livros por gênero
 *   - authors: lista de autores únicos ordenados alfabeticamente
 *   - oldestBook: livro mais antigo
 *   - newestBook: livro mais recente
 *
 * @param {import('express').Request} req - Requisição
 * @param {import('express').Response} res - Resposta com estatísticas
 */
router.get('/', (req, res) => {
  // Se não houver livros, retorna estatísticas zeradas
  if (books.length === 0) {
    return res.json({
      total: 0,
      avgYear: 0,
      genres: {},
      authors: [],
      oldestBook: null,
      newestBook: null,
    });
  }

  // CÁLCULO DO TOTAL — O(1) pois length é uma propriedade nativa do array
  const total = books.length;

  // CÁLCULO DA MÉDIA DOS ANOS — usa reduce para somar todos os anos
  // e divide pelo total. Reduzir um array a um único valor é o padrão
  // funcional para operações de agregação.
  const sumYears = books.reduce((sum, book) => sum + book.year, 0);
  const avgYear = Math.round((sumYears / total) * 10) / 10;

  // CONTAGEM POR GÊNERO — usa reduce para construir um mapa de contagem
  // Cada gênero é uma chave e o valor é a quantidade de livros daquele gênero.
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // LISTA DE AUTORES ÚNICOS — usa Set para remover duplicatas, depois converte para array
  // e ordena alfabeticamente para consistência na resposta.
  const authors = [...new Set(books.map((book) => book.author))].sort();

  // LIVRO MAIS ANTIGO E MAIS RECENTE — usa reduce para encontrar os extremos
  // em uma única passagem (O(n)), mais eficiente que ordenar o array inteiro.
  const oldestBook = books.reduce(
    (min, book) => (book.year < min.year ? book : min),
    books[0]
  );

  const newestBook = books.reduce(
    (max, book) => (book.year > max.year ? book : max),
    books[0]
  );

  // Retorna todas as estatísticas em uma única resposta JSON
  res.json({
    total,
    avgYear,
    genres,
    authors,
    oldestBook,
    newestBook,
  });
});

module.exports = router;
```

