## 7. `src/app.js` — Aplicação Principal

```javascript
/**
 * ============================================================
 * src/app.js
 * ============================================================
 *
 * APLICAÇÃO PRINCIPAL DO EXPRESS
 *
 * POR QUE ESTRUTURA EM CAMADAS?
 *
 * 1. O app.js é o "orquestrador" que conecta middlewares, rotas
 *    e tratamento de erros. Ele não contém lógica de negócio —
 *    isso está nas rotas e no middleware.
 *
 * 2. ORDEM DOS MIDDLEWARES importa no Express:
 *    - Middlewares globais (body-parser, CORS) vêm primeiro
 *    - Rotas vêm em seguida
 *    - Middleware de erro vem POR ÚLTIMO (sempre!)
 *
 * 3. O Express processa middlewares na ordem em que são registrados.
 *    Um middleware de erro mal posicionado pode não capturar erros
 *    de rotas registradas após ele.
 * ============================================================
 */

const express = require('express');
const errorHandler = require('./middleware/errorHandler');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');

// Cria a aplicação Express — instância única que orquestra toda a API
const app = express();

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * body-parser: parseia o corpo das requisições HTTP como JSON.
 * Sem isso, req.body seria undefined e não poderíamos ler dados
 * enviados por POST/PUT.
 */
app.use(express.json());

/**
 * Logger simples de requisições — útil para debugging.
 * Imprime método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

// ============================================================
// REGISTRO DE ROTAS
// ============================================================
//
// Por que usar app.use('/books', booksRouter)?
//
// 1. PREFIXO DE ROTA: todo o conteúdo do router é prefixado com /books,
//    então as rotas internas (/, :id) se tornam /books e /books/:id.
//
// 2. MODULARIDADE: se quisermos mover as rotas de livros para outro
//    serviço no futuro, basta alterar uma linha aqui.
// ============================================================

/** Rotas de gerenciamento de livros (CRUD completo). */
app.use('/books', booksRouter);

/** Rotas de estatísticas. */
app.use('/stats', statsRouter);

// ============================================================
// ROTA PADRÃO (RAIZ)
// ============================================================
//
// EXEMPLO DE REQUISIÇÃO:
//   curl http://localhost:3000/
// ============================================================

/**
 * Rota raiz que fornece informações básicas sobre a API.
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Book API',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      books: {
        methods: ['GET', 'POST'],
        paths: ['/books', '/books/:id'],
        description: 'Gerenciamento completo de livros (CRUD)',
      },
      stats: {
        methods: ['GET'],
        paths: ['/stats'],
        description: 'Estatísticas agregadas do acervo',
      },
    },
  });
});

// ============================================================
// TRATAMENTO DE ERROS 404 (Rota não encontrada)
// ============================================================
//
// Se nenhuma rota corresponder, o Express não lança erro automaticamente.
// Precisamos tratar isso manualmente para retornar um 404 JSON adequado.
// ============================================================

app.use((req, res, next) => {
  const { NotFoundError } = require('./errors');
  next(new NotFoundError(`Rota ${req.method} ${req.url} não encontrada.`));
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS — SEMPRE POR ÚLTIMO!
// ============================================================
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

/** Porta padrão para o servidor. Pode ser sobrescrita por variável de ambiente. */
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor e faz log de confirmação.
 * O callback é executado apenas quando o servidor começa a ouvir.
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book API rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nEndpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/              — Info da API`);
  console.log(`  GET    http://localhost:${PORT}/books         — Listar livros`);
  console.log(`  GET    http://localhost:${PORT}/books/:id     — Buscar livro por ID`);
  console.log(`  POST   http://localhost:${PORT}/books         — Criar livro`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id     — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id     — Excluir livro`);
  console.log(`  GET    http://localhost:${PORT}/stats         — Estatísticas`);
  console.log(`\nTeste com: curl http://localhost:${PORT}/books\n`);
});

module.exports = app;
```

