## File 2: `data/books.js`

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For an educational example, an in-memory array avoids the
 * complexity of setting up a database while still demonstrating all CRUD
 * operations. In production you would replace this module with a database
 * adapter (e.g., MongoDB, PostgreSQL) — the route handlers would remain
 * largely unchanged because we abstract the storage layer here.
 *
 * WHY AN ARRAY OF OBJECTS? Arrays provide O(1) access by index and are
 * trivial to iterate over for filtering and statistics. Each book object
 * contains: id (unique identifier), title, author, year (publication year),
 * and genre. We use a simple counter (`nextId`) to generate unique IDs
 * rather than relying on external libraries like UUID, keeping dependencies minimal.
 */

// ---------------------------------------------------------------------------
// Data structure
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} Book
 * @property {number} id - Unique numeric identifier for the book.
 * @property {string} title - The title of the book.
 * @property {string} author - The author's full name.
 * @property {number} year - Year the book was published.
 * @property {string} genre - Primary genre (e.g., "Fiction", "Science").
 */

/**
 * @type {Book[]}
 *
 * Initial seed data so the API is not empty on startup.
 * Having sample data makes testing immediately satisfying.
 */
const books = [
  { id: 1, title: 'To Kill a Mockingbird', author: 'Harper Lee', year: 1960, genre: 'Fiction' },
  { id: 2, title: 'A Brief History of Time', author: 'Stephen Hawking', year: 1988, genre: 'Science' },
  { id: 3, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', year: 1925, genre: 'Fiction' },
  { id: 4, title: 'Sapiens', author: 'Yuval Noah Harari', year: 2011, genre: 'History' },
  { id: 5, title: 'Dune', author: 'Frank Herbert', year: 1965, genre: 'Science Fiction' },
];

/**
 * @type {number}
 * Counter for generating unique IDs. Starts at the max existing ID + 1
 * so that even if we delete books, IDs never collide.
 */
let nextId = Math.max(...books.map((b) => b.id)) + 1;

// ---------------------------------------------------------------------------
// Public API (functions that routes will call)
// ---------------------------------------------------------------------------

/**
 * Returns a shallow copy of the entire books array.
 * Returning a copy prevents external code from mutating the internal state
 * directly, which is a good encapsulation practice.
 * @returns {Book[]} All books in the store.
 */
function getAllBooks() {
  return [...books];
}

/**
 * Finds a book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Book | undefined} The matching book, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adds a new book to the store and assigns it a unique ID.
 * @param {Omit<Book, 'id'>} bookData - Book data without the id field.
 * @returns {Book} The newly created book including its generated id.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData,
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID. Returns undefined if the book doesn't exist.
 * Uses object spread to create a new object rather than mutating in place,
 * which is safer and makes debugging easier.
 * @param {number} id - The ID of the book to update.
 * @param {Partial<Book>} updates - Fields to overwrite (title, author, year, genre).
 * @returns {Book | undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Create a new object with merged fields so the original reference isn't mutated unexpectedly.
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by ID. Returns true if deleted, false if not found.
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and removed.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Computes aggregate statistics from the current book collection.
 * This demonstrates data processing on top of CRUD operations.
 * @returns {Object} Statistics object containing total count, average year,
 *                   most common genre, and a breakdown by author.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return { total: 0, averageYear: null, mostCommonGenre: null, booksByAuthor: {} };
  }

  // Calculate average publication year.
  const sumOfYears = books.reduce((sum, book) => sum + book.year, 0);
  const averageYear = Math.round(sumOfYears / total);

  // Determine the most common genre using a frequency map.
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }
  const mostCommonGenre = Object.entries(genreCounts).sort((a, b) => b[1] - a[1])[0][0];

  // Group book counts by author.
  const booksByAuthor = {};
  for (const book of books) {
    booksByAuthor[book.author] = (booksByAuthor[book.author] || 0) + 1;
  }

  return { total, averageYear, mostCommonGenre, booksByAuthor };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Key design decisions explained:**

1. **In-memory array**: Chosen for simplicity in an educational context. No database setup required. The trade-off is that data is lost on server restart — acceptable for a demo.
2. **Shallow copy on read (`[...books]`)**: Prevents callers from accidentally mutating the internal array. This is a form of encapsulation.
3. **`nextId` counter**: Simple, collision-free ID generation. In production you'd use UUIDs or let the database handle it.
4. **`Partial<Book>` for updates**: TypeScript-style thinking — we only require the fields that are being changed, not the entire object. This makes PUT requests more flexible.

