## File 3: `middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Custom error classes and centralized error-handling middleware.
 *
 * WHY CUSTOM ERROR CLASSES? Built-in Error objects don't carry HTTP status
 * codes or structured messages. By creating subclasses (AppError, NotFoundError,
 * ValidationError) we can distinguish between different failure modes and
 * respond with appropriate HTTP status codes consistently.
 *
 * WHY CENTRALIZED MIDDLEWARE? Express allows us to register a special
 * 4-argument middleware function that catches all errors thrown in route
 * handlers (including async errors when using the express-async-errors pattern,
 * or manual next(err) calls). This avoids repeating try/catch blocks in every
 * route and ensures every error returns a consistent JSON shape.
 */

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

/**
 * Base application error class. All custom errors inherit from this.
 * @extends {Error}
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    // Ensure proper prototype chain for instanceof checks.
    Object.setPrototypeOf(this, AppError.prototype);
  }
}

/**
 * Error thrown when a requested resource is not found (404).
 */
class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

/**
 * Error thrown when client input fails validation (400).
 */
class ValidationError extends AppError {
  constructor(message = 'Validation failed', details = null) {
    super(message, 400);
    this.details = details; // Optional: array of specific field errors.
  }
}

// ---------------------------------------------------------------------------
// Error-Handling Middleware
// ---------------------------------------------------------------------------

/**
 * Centralized error-handling middleware.
 *
 * Express identifies middleware with exactly 4 parameters ((err, req, res, next))
 * as an error handler. This function is called whenever `next(err)` is invoked
 * or when an async route throws an unhandled exception.
 *
 * @param {Error} err - The error object (our custom AppError or subclass).
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 */
function errorHandler(err, req, res, next) {
  // Log the error for server-side debugging (in production, use a logging library).
  console.error(`[ERROR] ${err.statusCode || 500} — ${err.message}`);
  if (err.stack) {
    console.error(err.stack);
  }

  // Build a consistent JSON response shape for all errors.
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode,
    },
  };

  // Include validation details if present (helps clients fix their input).
  if (err.details) {
    response.error.details = err.details;
  }

  // Send the JSON response with the appropriate status code.
  res.status(err.statusCode || 500).json(response);
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  errorHandler,
};
```

**Why this pattern?** Custom error classes let us carry extra metadata (status code, validation details) alongside the error message. The centralized middleware ensures that *every* error in the application returns the same JSON structure (`{ success: false, error: { ... } }`), which makes client-side error handling predictable.

