## File 4: `routes/books.js`

```javascript
/**
 * @fileoverview Book CRUD routes.
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module promotes
 * separation of concerns. The server.js file stays clean, and we can test
 * routes independently. This also mirrors how larger Express applications
 * are structured in production.
 *
 * WHY ASYNC/AWAIT? Modern JavaScript supports async/await natively. It makes
 * asynchronous code read synchronously, which is far easier to reason about
 * than callback chains or .then() promises. Express 4+ handles async route
 * handlers gracefully when errors are caught and passed to `next(err)`.
 */

const express = require('express');
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('../data/books');
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// Create an Express Router instance. Routers are mini-applications that can
// be mounted at a path. This keeps route definitions organized and reusable.
const router = express.Router();

// ---------------------------------------------------------------------------
// Validation Helpers
// ---------------------------------------------------------------------------

/**
 * Validates the fields required for creating or updating a book.
 *
 * @param {Object} body - The request body to validate.
 * @param {string[]} requiredFields - Array of field names that must be present.
 * @returns {null|ValidationError} Returns null if valid, or a ValidationError with details.
 */
function validateBookBody(body, requiredFields = ['title', 'author', 'year', 'genre']) {
  const missing = requiredFields.filter((field) => !body[field]);
  if (missing.length > 0) {
    return new ValidationError(
      `Missing required fields: ${missing.join(', ')}`,
      missing.map((field) => ({ field, message: `${field} is required` }))
    );
  }

  // Year must be a positive integer.
  if (!Number.isInteger(body.year) || body.year < 0) {
    return new ValidationError('Year must be a non-negative integer', [
      { field: 'year', message: 'Year must be a valid integer' },
    ]);
  }

  return null; // Validation passed.
}

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// ---------------------------------------------------------------------------

/**
 * @route GET /books
 * @description Retrieves all books, optionally filtered by query parameters.
 *
 * Query Parameters (all optional):
 *   - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author: Filter by author name substring (case-insensitive)
 *   - minYear: Minimum publication year (inclusive)
 *   - maxYear: Maximum publication year (inclusive)
 *
 * @access Public
 *
 * @example curl http://localhost:3000/books?genre=Fiction
 * @example curl "http://localhost:3000/books?author=hawking&minYear=1980"
 */
router.get('/', (req, res) => {
  // Start with the full collection.
  let result = getAllBooks();

  // Apply genre filter if provided.
  if (req.query.genre) {
    result = result.filter((book) => book.genre.toLowerCase() === req.query.genre.toLowerCase());
  }

  // Apply author substring filter (case-insensitive).
  if (req.query.author) {
    const authorQuery = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorQuery));
  }

  // Apply year range filters.
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    result = result.filter((book) => book.year >= minYear);
  }
  if (req.query.maxYear) {
    const maxYear = parseInt(req.query.maxYear, 10);
    result = result.filter((book) => book.year <= maxYear);
  }

  // Return the (possibly filtered) collection.
  res.json({ success: true, data: result });
});

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------

/**
 * @route GET /books/:id
 * @description Retrieves a single book by its numeric ID.
 *
 * @param {number} id - The book's unique identifier (URL parameter).
 *
 * @access Public
 *
 * @example curl http://localhost:3000/books/1
 */
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validate that the ID is a valid integer.
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  const book = getBookById(id);
  if (!book) {
    // Throw NotFoundError so the centralized error handler catches it.
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  res.json({ success: true, data: book });
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------

/**
 * @route POST /books
 * @description Creates a new book and returns it with its generated ID.
 *
 * Request Body (JSON):
 *   - title (string, required): The book's title.
 *   - author (string, required): The author's name.
 *   - year (number, required): Publication year as a non-negative integer.
 *   - genre (string, required): Primary genre of the book.
 *
 * @access Public
 *
 * @example curl -X POST http://localhost:3000/books \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Dystopian"}'
 */
router.post('/', (req, res) => {
  // Validate the incoming request body.
  const validationError = validateBookBody(req.body);
  if (validationError) {
    throw validationError;
  }

  const newBook = createBook({
    title: req.body.title,
    author: req.body.author,
    year: req.body.year,
    genre: req.body.genre,
  });

  // 201 Created is the semantically correct status for resource creation.
  res.status(201).json({ success: true, data: newBook });
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
// ---------------------------------------------------------------------------

/**
 * @route PUT /books/:id
 * @description Fully replaces an existing book's data. All fields must be provided.
 *
 * Note: We use PUT (not PATCH) to demonstrate full replacement semantics.
 * For partial updates, you would use PATCH and make all fields optional.
 *
 * @param {number} id - The book's unique identifier (URL parameter).
 * @body title (string, required), author (string, required), year (number, required), genre (string, required)
 *
 * @access Public
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"To Kill a Mockingbird","author":"Harper Lee","year":1960,"genre":"Fiction"}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  // Check that the book exists before attempting update.
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  const validationError = validateBookBody(req.body);
  if (validationError) {
    throw validationError;
  }

  const updatedBook = updateBook(id, {
    title: req.body.title,
    author: req.body.author,
    year: req.body.year,
    genre: req.body.genre,
  });

  // Return the updated resource with 200 OK.
  res.json({ success: true, data: updatedBook });
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// ---------------------------------------------------------------------------

/**
 * @route DELETE /books/:id
 * @description Permanently deletes a book by its ID.
 *
 * @param {number} id - The book's unique identifier (URL parameter).
 *
 * @access Public
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  const deleted = deleteBook(id);
  if (!deleted) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  // 204 No Content is appropriate when deleting — no body to return.
  res.status(204).end();
});

// ---------------------------------------------------------------------------
// Module Export
// ---------------------------------------------------------------------------

module.exports = router;
```

**Key patterns explained:**

1. **`express.Router()`**: Creates a modular route handler that can be mounted anywhere. This is how production Express apps organize routes.
2. **Validation helper (`validateBookBody`)**: Extracted to avoid duplicating validation logic between POST and PUT handlers. It returns `null` on success or a `ValidationError` on failure — this lets us `throw` it directly in the route handler.
3. **`throw` instead of manual `next(err)`**: In Express, throwing inside a route handler (or calling `next(err)`) both trigger the error-handling middleware. Using `throw` is cleaner for synchronous code.
4. **HTTP status codes**: We use semantically correct codes — `201 Created` for POST, `204 No Content` for successful DELETE, `404 Not Found` when resources don't exist. This follows REST conventions and helps clients understand the outcome.

