## File 6: `server.js`

```javascript
/**
 * @fileoverview Main application entry point.
 *
 * This file wires together Express, middleware, routes, and the error handler.
 * It is intentionally kept minimal — all business logic lives in the data/
 * and routes/ directories.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Create the Express application instance.
const app = express();

// ---------------------------------------------------------------------------
// Middleware Configuration
// ---------------------------------------------------------------------------

/**
 * Built-in middleware to parse JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests.
 * limit: '10kb' prevents abnormally large payloads (DoS protection).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Built-in middleware to parse URL-encoded bodies (for form submissions).
 * extended: false uses the Node.js querystring parser (simpler, faster).
 */
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// Route Mounting
// ---------------------------------------------------------------------------

/**
 * Mount the books router at /books.
 * All routes defined in routes/books.js will be prefixed with /books.
 * For example, GET /books/:id in the router becomes GET /books/:id on the app.
 */
app.use('/books', booksRouter);

/**
 * Mount the stats router at /stats.
 */
app.use('/stats', statsRouter);

// ---------------------------------------------------------------------------
// Root Endpoint (for health checks and documentation)
// ---------------------------------------------------------------------------

/**
 * @route GET /
 * @description Returns API information and available endpoints.
 * Useful for clients discovering what the API offers.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API — Educational Example',
    endpoints: {
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

// ---------------------------------------------------------------------------
// Catch-All for Undefined Routes (404)
// ---------------------------------------------------------------------------

/**
 * If a request hits an endpoint that doesn't match any route,
 * throw a NotFoundError so the centralized error handler returns a proper JSON response.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./middleware/errorHandler');
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ---------------------------------------------------------------------------
// Centralized Error Handler (MUST be last middleware)
// ---------------------------------------------------------------------------

/**
 * Express error-handling middleware. Must be registered after all routes
 * so it can catch errors from any route handler.
 */
app.use(errorHandler);

// ---------------------------------------------------------------------------
// Server Startup
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: curl http://localhost:${PORT}/`);
});
```

**Why this structure?** The server file is the "glue" that connects everything. It stays thin by delegating to route modules and middleware. The catch-all 404 handler ensures that *every* undefined route returns a proper JSON error rather than Express's default HTML page — this keeps the API consistent for all clients.

