## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @file errorHandler.js
 * @description Middleware centralizado de tratamento de erros para a API.
 *
 * POR QUE UM MIDDLEWARE DE ERROS CENTRALIZADO?
 * ---------------------------------------------
 * Em vez de repetir lógica de resposta de erro em cada rota, centralizamos
 * tudo em um único middleware. O Express identifica middlewares de erro pela
 * assinatura: (err, req, res, next) => ... — quatro parâmetros são a convenção.
 *
 * PADRÃO ESCOLHIDO: Middleware de 4 parâmetros + tratamento async/await
 * - Middlewares normais têm 3 parâmetros; erros têm 4
 * - Async errors são capturados por wrapper (ver app.js)
 * - Respostas consistentes em JSON para todos os tipos de erro
 */

const { AppError, NotFoundError } = require('../classes/AppError');

/**
 * Middleware principal de tratamento de erros.
 * Intercepta erros lançados em rotas e responde com formato padronizado.
 *
 * @param {AppError} err - Instância de erro (AppError ou nativo).
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função para encadear middlewares.
 */
function errorHandler(err, req, res, next) {
  // Configurações padrão de segurança: nunca expor stack trace em produção
  const isProduction = process.env.NODE_ENV === 'production';

  /**
   * Se o erro já é uma instância de AppError, usamos suas propriedades.
   * Caso contrário, tratamos como erro não operacional (bug do sistema).
   */
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Erro interno do servidor';
  let details = err.details || {};

  // Erros operacionais conhecidos recebem mensagem amigável
  if (!err.isOperational && !isProduction) {
    // Em desenvolvimento, incluímos stack trace para debugging
    details.stack = err.stack;
  }

  /**
   * Resposta padronizada em JSON.
   * Formato: { success: false, error: { message, statusCode, details? } }
   * O campo "success" permite que clientes verifiquem rapidamente o status.
   */
  res.status(statusCode).json({
    success: false,
    error: {
      message,
      statusCode,
      ...(Object.keys(details).length > 0 && { details }),
    },
    ...(process.env.NODE_ENV !== 'production' && { timestamp: new Date().toISOString() }),
  });
}

/**
 * Middleware para capturar erros em handlers assíncronos.
 * Express não captura automaticamente rejeições de Promises em rotas.
 * Este wrapper envolve cada handler async e encaminha erros ao middleware.
 *
 * @param {Function} fn - Handler assíncrono Express.
 * @returns {Function} Middleware Express com tratamento de erro embutido.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    /**
     * Promise.then/reject captura tanto erros síncronos quanto rejeições assíncronas.
     * Se fn() rejeitar, o erro é passado para next(err), que aciona errorHandler.
     */
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, asyncHandler };
```

> **Explicação:** O `errorHandler` é um middleware de 4 parâmetros (convenção Express). Ele padroniza todas as respostas de erro no formato JSON esperado. O `asyncHandler` é crucial — sem ele, erros em rotas `async` seriam silenciosamente ignorados pelo Express. A separação entre erros operacionais (`isOperational = true`) e bugs permite respostas diferentes em produção vs. desenvolvimento.

