## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * @file books.js
 * @description Rotas REST para gerenciamento de livros.
 *
 * ESTRUTURA DE DADOS ESCOLHIDA: Array de objetos em memória
 * ----------------------------------------------------------
 * POR QUE ARRAY?
 * - Simplicidade: acesso por índice, iteração com forEach/map/filter
 * - Ordenação natural pela ordem de inserção (útil para listagem)
 * - Sem dependência de banco de dados para exemplo educacional
 * - Operações O(n) são aceitáveis para datasets pequenos (< 1000 itens)
 *
 * POR QUE NÃO USAR MAP/SET?
 * - Map: perde ordenação por inserção em iterações (depende do engine)
 * - Set: não permite busca por campo específico sem iterar
 * - Array + filter(): mais legível para buscas por propriedade
 *
 * CONVENÇÕES REST ESCOLHIDAS:
 * - GET /books?author=...&minYear=... — query params para filtragem
 * - PUT /books/:id — atualização completa (substituição total)
 * - PATCH não implementado intencionalmente — foco em CRUD básico
 * - DELETE retorna 204 No Content sem body (convenção REST estrita)
 */

const { AppError, NotFoundError, ValidationError } = require('../classes/AppError');
const { asyncHandler } = require('../middleware/errorHandler');

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA
// ============================================================

/**
 * Array principal de livros. Cada elemento é um objeto com:
 * - id: número único (timestamp para simplicidade)
 * - title: string do título
 * - author: string do autor
 * - year: number do ano de publicação
 * - genre: string do gênero literário
 * - createdAt: ISO string da data de criação
 *
 * ESCOLHA DE TIPO: Array vs. Object (mapa por ID)
 * - Array permite ordenação temporal e iteração eficiente para listagem
 * - Busca por ID usa find() — aceitável para datasets pequenos
 * - Para escala maior, um Map<id, livro> seria mais performático (O(1))
 */
const books = [];

/**
 * Contador para gerar IDs únicos sequenciais.
 * Usa timestamp como fallback para evitar colisão em criação rápida.
 */
let idCounter = 1;

// ============================================================
// FUNÇÕES AUXILIARES DE VALIDAÇÃO
// ============================================================

/**
 * Valida campos obrigatórios de um livro.
 *
 * @param {Object} data - Dados do livro a validar.
 * @returns {void} Lança ValidationError se inválido.
 */
function validateBookData(data) {
  const errors = {};

  if (!data.title || typeof data.title !== 'string' || data.title.trim().length === 0) {
    errors.title = 'Título é obrigatório e deve ser uma string não vazia';
  }

  if (!data.author || typeof data.author !== 'string' || data.author.trim().length === 0) {
    errors.author = 'Autor é obrigatório e deve ser uma string não vazia';
  }

  if (data.year === undefined || data.year === null) {
    // Ano é opcional — permite livros sem ano registrado
  } else if (!Number.isInteger(data.year) || data.year < 0 || data.year > new Date().getFullYear() + 1) {
    errors.year = `Ano deve ser um inteiro entre 0 e ${new Date().getFullYear() + 1}`;
  }

  if (data.genre && typeof data.genre !== 'string') {
    errors.genre = 'Gênero deve ser uma string';
  }

  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Validação falhou', errors);
  }
}

/**
 * Converte um livro para formato de resposta (remove campos internos).
 *
 * @param {Object} book - Livro completo.
 * @returns {Object} Livro sanitizado para API.
 */
function serializeBook(book) {
  return {
    id: book.id,
    title: book.title,
    author: book.author,
    year: book.year || null,
    genre: book.genre || null,
    createdAt: book.createdAt,
  };
}

// ============================================================
// ROTAS GET — LISTAGEM E BUSCA
// ============================================================

/**
 * @route GET /books
 * @description Lista todos os livros com filtragem opcional por query params.
 *
 * QUERY PARAMS DISPONÍVEIS:
 * - author: filtra por autor (case-insensitive, partial match)
 * - genre: filtra por gênero (partial match)
 * - minYear: filtra livros publicados a partir deste ano
 * - search: busca por título ou autor (ambos)
 * - sort: ordenação por campo (title, author, year, createdAt)
 * - order: direção da ordenação (asc, desc) — padrão: asc
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books?author=jk&minYear=2000
 *   curl "http://localhost:3000/books?search=harry&sort=year&order=desc"
 *
 * @param {import('express').Request} req - Requisição com query params.
 * @param {import('express').Response} res - Resposta com lista de livros.
 */
const getBooks = asyncHandler(async (req, res) => {
  let result = [...books]; // Cópia para não mutar o array original

  // Filtragem por autor (parcial, case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorFilter));
  }

  // Filtragem por gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => book.genre && book.genre.toLowerCase().includes(genreFilter));
  }

  // Filtragem por ano mínimo
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    if (!isNaN(minYear)) {
      result = result.filter((book) => book.year && book.year >= minYear);
    }
  }

  // Busca textual por título ou autor
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchFilter) ||
        book.author.toLowerCase().includes(searchFilter)
    );
  }

  // Ordenação
  if (req.query.sort) {
    const field = req.query.sort;
    const order = req.query.order === 'desc' ? -1 : 1;
    result.sort((a, b) => {
      const valA = a[field] ?? '';
      const valB = b[field] ?? '';
      if (typeof valA === 'string') return valA.localeCompare(valB) * order;
      return (valA || 0) - (valB || 0) * order;
    });
  }

  // Paginação simples (offset + limit)
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || result.length;
  const startIndex = (page - 1) * limit;
  const paginatedResult = result.slice(startIndex, startIndex + limit);

  res.json({
    success: true,
    count: paginatedResult.length,
    total: result.length,
    page,
    totalPages: Math.ceil(result.length / limit),
    data: paginatedResult.map(serializeBook),
  });
});

/**
 * @route GET /books/stats
 * @description Retorna estatísticas agregadas da coleção de livros.
 *
 * ESTATÍSTICAS RETORNADAS:
 * - totalBooks: quantidade total de livros
 * - totalAuthors: quantidade de autores únicos
 * - avgYear: ano médio de publicação (arredondado)
 * - booksByGenre: contagem por gênero
 * - oldestBook: livro mais antigo com ano registrado
 * - newestBook: livro mais recente com ano registrado
 *
 * EXEMPLO DE RESPOSTA:
 *   { "totalBooks": 5, "totalAuthors": 4, ... }
 *
 * @param {import('express').Request} req - Requisição.
 * @param {import('express').Response} res - Resposta com estatísticas.
 */
const getStats = asyncHandler(async (req, res) => {
  if (books.length === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        totalAuthors: 0,
        avgYear: null,
        booksByGenre: {},
        oldestBook: null,
        newestBook: null,
      },
    });
  }

  // Agrupamento por gênero usando reduce (padrão funcional)
  const booksByGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Cálculo do ano médio (ignorando livros sem ano)
  const booksWithYear = books.filter((b) => b.year);
  const avgYear =
    booksWithYear.length > 0
      ? Math.round(booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length)
      : null;

  // Livros mais antigo e mais recente por ano
  const sortedByYear = [...books].sort((a, b) => (a.year || 0) - (b.year || 0));
  const oldestBook = sortedByYear[0] ? serializeBook(sortedByYear[0]) : null;
  const newestBook = sortedByYear[sortedByYear.length - 1] ? serializeBook(sortedByYear[sortedByYear.length - 1]) : null;

  // Autores únicos usando Set (estrutura para deduplicação)
  const uniqueAuthors = new Set(books.map((b) => b.author));

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      totalAuthors: uniqueAuthors.size,
      avgYear,
      booksByGenre,
      oldestBook,
      newestBook,
    },
  });
});

// ============================================================
// ROTAS GET — BUSCA POR ID
// ============================================================

/**
 * @route GET /books/:id
 * @description Retorna um livro específico pelo seu identificador numérico.
 *
 * COMPORTAMENTO:
 * - Busca por find() no array (O(n))
 * - Retorna 404 se ID não existir
 * - Retorna 400 se ID for inválido (não numérico)
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404
 *
 * @param {import('express').Request} req - Requisição com params.id.
 * @param {import('express').Response} res - Resposta com livro encontrado.
 * @param {import('express').NextFunction} next - Encadeamento de middlewares.
 */
const getBookById = asyncHandler(async (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  // Validação do parâmetro de rota
  if (isNaN(id) || id < 1) {
    return next(new ValidationError('ID deve ser um número inteiro positivo', { id: req.params.id }));
  }

  const book = books.find((b) => b.id === id);

  if (!book) {
    // NotFoundError herda de AppError com statusCode 404
    return next(new NotFoundError('Livro'));
  }

  res.json({ success: true, data: serializeBook(book) });
});

// ============================================================
// ROTAS POST — CRIAÇÃO
// ============================================================

/**
 * @route POST /books
 * @description Cria um novo livro na coleção.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1954,
 *     "genre": "Fantasia"
 *   }
 *
 * CAMPOS OPCIONAIS: year, genre (padrão: null)
 * ID é gerado automaticamente pelo servidor.
 *
 * EXEMPLOS DE USO:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","year":1949}'
 *
 * @param {import('express').Request} req - Requisição com body do livro.
 * @param {import('express').Response} res - Resposta com livro criado.
 * @param {import('express').NextFunction} next - Encadeamento de middlewares.
 */
const createBook = asyncHandler(async (req, res, next) => {
  // Validação dos dados de entrada
  validateBookData(req.body);

  const newBook = {
    id: idCounter++,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: req.body.year ? parseInt(req.body.year, 10) : null,
    genre: req.body.genre ? req.body.genre.trim() : null,
    createdAt: new Date().toISOString(),
  };

  // push() adiciona ao final do array — ordenação temporal preservada
  books.push(newBook);

  /**
   * 201 Created é o código HTTP padrão para recursos criados com sucesso.
   * Inclui Location header apontando para o recurso criado (convenção REST).
   */
  res.status(201).header('Location', `/books/${newBook.id}`).json({
    success: true,
    message: 'Livro criado com sucesso',
    data: serializeBook(newBook),
  });
});

// ============================================================
// ROTAS PUT — ATUALIZAÇÃO COMPLETA
// ============================================================

/**
 * @route PUT /books/:id
 * @description Atualiza completamente um livro existente.
 *
 * DIFERENÇA ENTRE PUT E PATCH:
 * - PUT: substituição total — campos não enviados são removidos (null)
 * - PATCH: atualização parcial — apenas campos enviados são modificados
 * Escolhemos PUT para este exemplo por ser mais simples de implementar e entender.
 *
 * EXEMPLOS DE USO:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Novo Título","author":"Novo Autor"}'
 *
 * @param {import('express').Request} req - Requisição com params e body.
 * @param {import('express').Response} res - Resposta com livro atualizado.
 * @param {import('express').NextFunction} next - Encadeamento de middlewares.
 */
const updateBook = asyncHandler(async (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new ValidationError('ID deve ser um número inteiro positivo', { id: req.params.id }));
  }

  // splice() retorna array com elemento removido; [0] é o livro encontrado
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Livro'));
  }

  // Validação antes de atualizar
  validateBookData(req.body);

  // Atualização completa do objeto (substituição)
  books[bookIndex] = {
    ...books[bookIndex], // Preserva id e createdAt
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: req.body.year ? parseInt(req.body.year, 10) : null,
    genre: req.body.genre ? req.body.genre.trim() : null,
  };

  /**
   * 200 OK para atualização bem-sucedida.
   * Retorna o recurso atualizado no body (boa prática para PUT).
   */
  res.json({ success: true, message: 'Livro atualizado com sucesso', data: serializeBook(books[bookIndex]) });
});

// ============================================================
// ROTAS DELETE — EXCLUSÃO
// ============================================================

/**
 * @route DELETE /books/:id
 * @description Remove um livro da coleção permanentemente.
 *
 * COMPORTAMENTO:
 * - splice() remove o elemento do array (O(n) para busca + O(1) para remoção)
 * - 204 No Content: padrão REST para operações de deleção sem body
 * - Não retorna dados do livro deletado (convenção REST estrita)
 *
 * EXEMPLOS DE USO:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404
 *
 * @param {import('express').Request} req - Requisição com params.id.
 * @param {import('express').Response} res - Resposta vazia (204).
 * @param {import('express').NextFunction} next - Encadeamento de middlewares.
 */
const deleteBook = asyncHandler(async (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new ValidationError('ID deve ser um número inteiro positivo', { id: req.params.id }));
  }

  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Livro'));
  }

  // splice(index, 1) remove exatamente 1 elemento na posição index
  books.splice(bookIndex, 1);

  /**
   * 204 No Content é o código HTTP correto para deleção.
   * Significa: "a operação foi bem-sucedida, mas não há conteúdo para retornar".
   * Não enviamos body nesta resposta (convenção REST).
   */
  res.status(204).send();
});

// ============================================================
// EXPORTAÇÃO DAS ROTAS
// ============================================================

module.exports = {
  getBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Explicação:** Este arquivo contém todas as rotas REST organizadas por verbo HTTP. Cada função é envolta em `asyncHandler` para capturar erros assíncronos. A validação é feita antes de qualquer operação de escrita. O array `books` é o único estado da aplicação — operações usam métodos nativos (`push`, `find`, `splice`, `filter`) com complexidade aceitável para datasets pequenos.

