## Arquivo 5: `src/app.js`

```javascript
/**
 * @file app.js
 * @description Ponto de entrada da API REST de livros.
 *
 * ARQUITETURA ESCOLHIDA: Camadas separadas
 * -----------------------------------------
 * - routes/: lógica de negócio por recurso (livros)
 * - middleware/: tratamento transversal (erros, logging)
 * - classes/: tipos de domínio (erros personalizados)
 *
 * POR QUE EXPRESS?
 * - Middleware chain: req → middleware1 → middleware2 → route → res
 * - Roteamento flexível com parâmetros de URL (:id) e query params (?author=)
 * - Body-parser nativo via express.json() para parsing de JSON
 * - Ecossistema vasto com milhares de middlewares disponíveis
 *
 * PADRÃO ASYNC/AWAIT ESCOLHIDO:
 * - Mais legível que .then().catch() encadeados
 * - Compatível com try/catch tradicional (padrão da maioria dos devs)
 * - Express 4+ suporta handlers async nativamente
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorHandler');
const { getBooks, getBookById, createBook, updateBook, deleteBook, getStats } = require('./routes/books');

/**
 * Instância principal do aplicativo Express.
 * app é o objeto central que configura middlewares e rotas.
 */
const app = express();

// ============================================================
// CONFIGURAÇÃO DE MIDDLEWARES GLOBAIS
// ============================================================

/**
 * express.json() — Parser de body para requisições com Content-Type: application/json.
 * Sem este middleware, req.body seria undefined em POST/PUT/PATCH.
 * Limit de 100kb evita abuso de memória com payloads gigantes.
 */
app.use(express.json({ limit: '100kb' }));

/**
 * Middleware de logging básico para depuração.
 * Registra método, URL e timestamp de cada requisição.
 * Em produção, substituir por Winston/Morgan para logs estruturados.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

/**
 * Headers de segurança CORS (Cross-Origin Resource Sharing).
 * Permite que frontends de diferentes origens acessem esta API.
 * Em produção, restrinja origin a domínios específicos.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Preflight request para CORS (OPTIONS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// ============================================================
// CONFIGURAÇÃO DAS ROTAS REST
// ============================================================

/**
 * Rota raiz — documentação e health check.
 * GET / → informações sobre a API
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    name: 'API de Livros',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

/**
 * Rotas de livros — todas as operações CRUD.
 * Cada rota é mapeada para uma função no módulo routes/books.js.
 */
app.get('/books', getBooks);
app.get('/books/stats', getStats);
app.get('/books/:id', getBookById);
app.post('/books', createBook);
app.put('/books/:id', updateBook);
app.delete('/books/:id', deleteBook);

// ============================================================
// TRATAMENTO DE ERROS E ROTAS NÃO ENCONTRADAS
// ============================================================

/**
 * Middleware 404 — captua requisições para rotas inexistentes.
 * Deve ser definido ANTES do middleware de erro para funcionar corretamente.
 */
app.use((req, res, next) => {
  const error = new Error(`Rota não encontrada: ${req.method} ${req.url}`);
  error.statusCode = 404;
  next(error);
});

/**
 * Middleware de tratamento de erros — deve ser o ÚLTIMO middleware.
 * Express identifica este middleware pelos 4 parâmetros (err, req, res, next).
 */
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

/**
 * Porta padrão: 3000 para desenvolvimento local.
 * Em produção, usar variável de ambiente PORT ou gerenciador de processos.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`\n✅ API de Livros rodando em http://localhost:${PORT}`);
  console.log(`📚 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/`);
  console.log(`   GET    http://localhost:${PORT}/books`);
  console.log(`   GET    http://localhost:${PORT}/books/stats`);
  console.log(`   POST   http://localhost:${PORT}/books`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id\n`);
});

module.exports = app;
```

> **Explicação:** O `app.js` é o ponto de entrada que conecta tudo. Middlewares globais (JSON parser, logging, CORS) são aplicados antes das rotas. As rotas CRUD mapeiam diretamente para funções do módulo de rotas. O middleware 404 captura URLs inexistentes e o errorHandler lida com todos os erros. A porta padrão é 3000, mas pode ser sobrescrita por variável de ambiente.

