## File 2: `data/books.js`

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For educational purposes, an in-memory array is simpler than
 * setting up a database. It lets us focus on API design, routing, and error
 * handling without infrastructure complexity. In production, you would replace
 * this module with a database driver (e.g., MongoDB, PostgreSQL).
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and are intuitive for
 * demonstrating CRUD operations. For larger datasets, a Map or object hash
 * would give O(1) lookups by ID instead of O(n) linear search.
 */

// ---------------------------------------------------------------------------
// Data Structure Definition
// ---------------------------------------------------------------------------

/**
 * Each book is represented as a plain JavaScript object with the following shape:
 *
 * {
 *   id: number,          // Unique identifier (auto-incremented)
 *   title: string,       // Book title
 *   author: string,      // Author name
 *   genre: string,       // Genre/category (e.g., "Fiction", "Science")
 *   publishedYear: number, // Year of publication
 *   rating: number       // Average rating from 0.0 to 5.0
 * }
 *
 * We use a plain object rather than a class because:
 * 1. Simpler serialization (JSON.stringify works directly)
 * 2. No prototype chain overhead for basic data storage
 * 3. Easier to manipulate with spread operators and destructuring
 */

/** @type {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}>} */
const books = [
  {
    id: 1,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Fiction",
    publishedYear: 1960,
    rating: 4.8,
  },
  {
    id: 2,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    genre: "Science",
    publishedYear: 1988,
    rating: 4.6,
  },
  {
    id: 3,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Fiction",
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 4,
    title: "Clean Code",
    author: "Robert C. Martin",
    genre: "Technology",
    publishedYear: 2008,
    rating: 4.7,
  },
  {
    id: 5,
    title: "Dune",
    author: "Frank Herbert",
    genre: "Science Fiction",
    publishedYear: 1965,
    rating: 4.9,
  },
];

// ---------------------------------------------------------------------------
// Auto-Increment ID Generator
// ---------------------------------------------------------------------------

/**
 * Tracks the highest ID assigned so far. When creating a new book, we increment
 * this counter to ensure uniqueness.
 *
 * WHY NOT use `books.length`? Because books can be deleted, so length alone
 * doesn't guarantee unique IDs. We could also use a UUID library, but a simple
 * counter is sufficient for this educational example.
 */
let nextId = 6; // Start after the last seeded ID

/**
 * Generates the next unique book ID.
 * @returns {number} The next available ID.
 */
function getNextId() {
  return nextId++;
}

// ---------------------------------------------------------------------------
// Data Access Functions
// ---------------------------------------------------------------------------

/**
 * Retrieves all books from the in-memory store.
 *
 * WHY RETURN A COPY? We spread the array (`[...books]`) to prevent callers
 * from accidentally mutating the internal state. This is a defensive coding
 * practice that becomes critical as the application grows.
 *
 * @returns {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}>}
 *   A shallow copy of all books.
 */
function getAllBooks() {
  return [...books];
}

/**
 * Finds a book by its unique ID.
 *
 * WHY USE `Array.find()`? It returns the first element that satisfies the
 * predicate, or `undefined` if none match. This is more idiomatic than a
 * manual loop with a break statement.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}|undefined}
 *   The matching book object, or `undefined` if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adds a new book to the store and returns it with an assigned ID.
 *
 * WHY ASSIGN ID HERE? The data layer owns ID generation to keep IDs consistent
 * across all operations. The route handler simply passes through the created
 * object.
 *
 * @param {{title: string, author: string, genre: string, publishedYear: number, rating: number}} newBookData
 *   The book data provided by the client (without an `id` field).
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}}
 *   The newly created book with its assigned ID.
 */
function createBook(newBookData) {
  const newBook = {
    id: getNextId(),
    ...newBookData, // Spread operator merges the provided fields into the new object
  };
  books.push(newBook); // O(1) amortized append to array
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 *
 * WHY USE SPREAD FOR PARTIAL UPDATES? `PUT` is supposed to be a full replace,
 * but in practice many APIs support partial updates. We merge the existing
 * book with the new data so that omitted fields retain their original values.
 * For strict PUT semantics, you would require all fields and reject partials.
 *
 * @param {number} id - The ID of the book to update.
 * @param {{title?: string, author?: string, genre?: string, publishedYear?: number, rating?: number}} updates
 *   Partial or full book data to merge with the existing record.
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, rating: number}|null}
 *   The updated book object, or `null` if no book with that ID exists.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) {
    return null; // Book not found — caller should handle this as a 404
  }
  // Merge existing data with updates; undefined values are ignored by spread
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by its ID.
 *
 * WHY USE `Array.splice()`? It removes elements in-place and returns the
 * removed items. We only care about whether the removal succeeded (index !== -1).
 * For large datasets, filtering to create a new array (`books.filter(...)`)
 * would be more functional but less efficient due to copying.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} `true` if the book was found and deleted; `false` otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) {
    return false;
  }
  books.splice(index, 1); // Remove 1 element at the found index
  return true;
}

// ---------------------------------------------------------------------------
// Statistics Functions
// ---------------------------------------------------------------------------

/**
 * Computes aggregate statistics about the book collection.
 *
 * WHY COMPUTE ON THE FLY? For a small in-memory dataset, real-time computation
 * is fast and keeps the data layer simple. In production with millions of
 * records, you would maintain cached aggregates or use database-level queries.
 *
 * @returns {{
 *   totalBooks: number,
 *   averageRating: number,
 *   booksByGenre: Record<string, number>,
 *   oldestBook: {title: string, publishedYear: number}|null,
 *   newestBook: {title: string, publishedYear: number}|null
 * }}
 *   Aggregate statistics about the collection.
 */
function getStats() {
  const totalBooks = books.length;

  // Compute average rating — return 0 if no books exist to avoid division by zero
  const averageRating =
    totalBooks > 0
      ? parseFloat((books.reduce((sum, b) => sum + b.rating, 0) / totalBooks).toFixed(2))
      : 0;

  // Count books per genre using a reduce accumulator
  /** @type {Record<string, number>} */
  const booksByGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Find oldest and newest books by published year
  /** @type {{title: string, publishedYear: number}|null} */
  let oldestBook = null;
  /** @type {{title: string, publishedYear: number}|null} */
  let newestBook = null;

  if (totalBooks > 0) {
    const sortedByYear = [...books].sort((a, b) => a.publishedYear - b.publishedYear);
    oldestBook = { title: sortedByYear[0].title, publishedYear: sortedByYear[0].publishedYear };
    newestBook = { title: sortedByYear[sortedByYear.length - 1].title, publishedYear: sortedByYear[sortedByYear.length - 1].publishedYear };
  }

  return {
    totalBooks,
    averageRating,
    booksByGenre,
    oldestBook,
    newestBook,
  };
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------

/**
 * Export all data access functions as a named object.
 *
 * WHY NAMED EXPORTS? They make it clear which functions are being used in each
 * route file and enable tree-shaking in bundlers. Default exports are less
 * explicit and can lead to naming confusion.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Key design decisions explained:**

1. **In-memory array**: Chosen for simplicity — no database setup required. The `books` array is seeded with sample data so the API works immediately on startup.
2. **Auto-increment IDs**: A module-level counter (`nextId`) ensures uniqueness even after deletions. In production, you'd use UUIDs or database auto-increment.
3. **Defensive copies**: `getAllBooks()` returns a spread copy (`[...books]`) to prevent external code from mutating the internal state directly.
4. **On-the-fly statistics**: Computed in real-time rather than cached. Fine for small datasets; production systems would use database queries or Redis caching.

