## File 4: `routes/books.js`

```javascript
/**
 * @fileoverview Book CRUD routes with filtering and validation.
 *
 * WHY SEPARATE ROUTE FILE? Keeping routes in their own module promotes
 * separation of concerns. The server.js file only needs to import and use the
 * router, keeping it clean and readable. This also makes testing easier — you
 * can test route handlers in isolation from the Express app.
 *
 * WHY USE `express.Router()`? It creates a standalone mini-app that can be
 * mounted at a path prefix (`/books`). This avoids repeating `/books` in every
 * route definition and allows middleware to be scoped to specific routes.
 */

const express = require("express");
const router = express.Router(); // Create a new router instance

// Import data access functions from our in-memory store
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require("../data/books");

// Import custom error classes for throwing typed errors
const { NotFoundError, ValidationError } = require("../middleware/errors");

// ---------------------------------------------------------------------------
// Validation Helpers
// ---------------------------------------------------------------------------

/**
 * Validates the required fields for creating or updating a book.
 *
 * WHY VALIDATE IN THE ROUTE LAYER? Validation belongs in routes (or a dedicated
 * middleware) rather than in the data layer because:
 * 1. The data layer should be agnostic about HTTP concerns
 * 2. Different clients may have different validation rules
 * 3. It keeps the data layer reusable (e.g., for CLI tools or background jobs)
 *
 * @param {{title?: string, author?: string, genre?: string, publishedYear?: number, rating?: number}} body
 *   The request body to validate.
 * @param {boolean} isUpdate - Whether this is an update (partial fields allowed).
 * @throws {ValidationError} If validation fails.
 */
function validateBookBody(body, isUpdate = false) {
  // For updates, we allow partial data — at least one field must be provided
  if (isUpdate) {
    const requiredFields = ["title", "author", "genre", "publishedYear", "rating"];
    const hasAnyField = requiredFields.some((field) => body[field] !== undefined);
    if (!hasAnyField) {
      throw new ValidationError("At least one field must be provided for update");
    }
    // Validate types for fields that ARE present
    if (body.title !== undefined && typeof body.title !== "string") {
      throw new ValidationError("title must be a string");
    }
    if (body.author !== undefined && typeof body.author !== "string") {
      throw new ValidationError("author must be a string");
    }
    if (body.genre !== undefined && typeof body.genre !== "string") {
      throw new ValidationError("genre must be a string");
    }
    if (body.publishedYear !== undefined && (!Number.isInteger(body.publishedYear) || body.publishedYear < 0)) {
      throw new ValidationError("publishedYear must be a positive integer");
    }
    if (body.rating !== undefined && (typeof body.rating !== "number" || body.rating < 0 || body.rating > 5)) {
      throw new ValidationError("rating must be a number between 0 and 5");
    }
    return; // Validation passed for update
  }

  // For creation, ALL fields are required
  const requiredFields = ["title", "author", "genre", "publishedYear", "rating"];
  const missingFields = requiredFields.filter((field) => body[field] === undefined);
  if (missingFields.length > 0) {
    throw new ValidationError(`Missing required fields: ${missingFields.join(", ")}`);
  }

  // Type and range validation for creation
  if (typeof body.title !== "string" || body.title.trim() === "") {
    throw new ValidationError("title must be a non-empty string");
  }
  if (typeof body.author !== "string" || body.author.trim() === "") {
    throw new ValidationError("author must be a non-empty string");
  }
  if (typeof body.genre !== "string" || body.genre.trim() === "") {
    throw new ValidationError("genre must be a non-empty string");
  }
  if (!Number.isInteger(body.publishedYear) || body.publishedYear < 0) {
    throw new ValidationError("publishedYear must be a positive integer");
  }
  if (typeof body.rating !== "number" || body.rating < 0 || body.rating > 5) {
    throw new ValidationError("rating must be a number between 0 and 5");
  }
}

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// ---------------------------------------------------------------------------

/**
 * @route GET /books
 * @description Retrieve a list of all books with optional query parameter filters.
 *
 * QUERY PARAMETERS (all optional):
 * - `genre` — Filter by exact genre match (e.g., ?genre=Fiction)
 * - `author` — Filter by author name substring (case-insensitive, e.g., ?author=hawking)
 * - `minRating` — Minimum rating threshold (e.g., ?minRating=4.5)
 *
 * WHY USE QUERY PARAMETERS? Query params are the REST-conventional way to add
 * optional filters without changing the URL structure. They keep the endpoint
 * flexible and composable (you can combine multiple filters).
 *
 * @access Public
 * @example
 *   // Get all books
 *   GET /books
 *
 *   // Filter by genre
 *   GET /books?genre=Fiction
 *
 *   // Filter by author substring and minimum rating
 *   GET /books?author=hawking&minRating=4.5
 */
router.get("/", (req, res) => {
  // Destructure query parameters with defaults for missing values
  const { genre, author, minRating } = req.query;

  // Start with a full copy of all books to avoid mutating the source array
  let filteredBooks = getAllBooks();

  // Apply genre filter if provided — exact match (case-insensitive)
  if (genre) {
    filteredBooks = filteredBooks.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
  }

  // Apply author filter if provided — substring match (case-insensitive)
  if (author) {
    const authorLower = author.toLowerCase();
    filteredBooks = filteredBooks.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  // Apply minimum rating filter if provided
  if (minRating) {
    const minRatingNum = parseFloat(minRating);
    // Validate that minRating is a valid number
    if (isNaN(minRatingNum)) {
      throw new ValidationError("minRating must be a valid number");
    }
    filteredBooks = filteredBooks.filter((book) => book.rating >= minRatingNum);
  }

  // Send the filtered results as JSON with status 200 OK
  res.json(filteredBooks);
});

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------

/**
 * @route GET /books/:id
 * @description Retrieve a single book by its unique identifier.
 *
 * URL PARAMETER:
 * - `id` — The numeric ID of the book (e.g., /books/1)
 *
 * WHY USE URL PARAMETERS? IDs are part of the resource identity, so they belong
 * in the URL path rather than query parameters. This follows REST conventions
 * and makes URLs human-readable and bookmarkable.
 *
 * @access Public
 * @example
 *   // Get book with ID 1
 *   GET /books/1
 */
router.get("/:id", (req, res) => {
  // Parse the ID from the URL parameter and convert to integer
  const id = parseInt(req.params.id, 10);

  // Validate that the ID is a valid number
  if (isNaN(id)) {
    throw new ValidationError("Invalid book ID: must be a number");
  }

  // Look up the book in our data store
  const book = getBookById(id);

  // If not found, throw a NotFoundError (caught by global error handler)
  if (!book) {
    throw new NotFoundError("Book", id);
  }

  // Send the book as JSON with status 200 OK
  res.json(book);
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------

/**
 * @route POST /books
 * @description Create a new book and return it with its assigned ID.
 *
 * REQUEST BODY (JSON):
 * ```json
 * {
 *   "title": "The Catcher in the Rye",
 *   "author": "J.D. Salinger",
 *   "genre": "Fiction",
 *   "publishedYear": 1951,
 *   "rating": 4.3
 * }
 * ```
 *
 * WHY RETURN 201 CREATED? Per HTTP specification, successful resource creation
 * should return 201 (not 200) to signal that a new resource was created. This
 * helps API consumers distinguish between retrieval and creation operations.
 *
 * @access Public
 * @example
 *   POST /books
 *   Content-Type: application/json
 *
 *   {
 *     "title": "1984",
 *     "author": "George Orwell",
 *     "genre": "Dystopian",
 *     "publishedYear": 1949,
 *     "rating": 4.7
 *   }
 */
router.post("/", (req, res) => {
  // Validate the request body before attempting to create the book
  validateBookBody(req.body, false);

  // Create the book in our data store
  const newBook = createBook(req.body);

  // Respond with 201 Created and the newly created book object
  res.status(201).json(newBook);
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
// ---------------------------------------------------------------------------

/**
 * @route PUT /books/:id
 * @description Fully update an existing book by ID.
 *
 * URL PARAMETER:
 * - `id` — The numeric ID of the book to update
 *
 * REQUEST BODY (JSON) — All fields required for strict PUT semantics:
 * ```json
 * {
 *   "title": "Updated Title",
 *   "author": "Updated Author",
 *   "genre": "Updated Genre",
 *   "publishedYear": 2020,
 *   "rating": 4.5
 * }
 * ```
 *
 * WHY USE PUT VS PATCH? `PUT` is defined as a full replacement — the client
 * sends the complete resource, and the server replaces it entirely. `PATCH`
 * would imply partial updates. For this educational example, we accept all
 * fields to demonstrate strict REST semantics. In practice, many APIs support
 * both endpoints.
 *
 * @access Public
 * @example
 *   PUT /books/1
 *   Content-Type: application/json
 *
 *   {
 *     "title": "To Kill a Mockingbird (Updated Edition)",
 *     "author": "Harper Lee",
 *     "genre": "Fiction",
 *     "publishedYear": 1960,
 *     "rating": 4.9
 *   }
 */
router.put("/:id", (req, res) => {
  // Parse and validate the ID
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError("Invalid book ID: must be a number");
  }

  // Validate the request body — all fields required for PUT
  validateBookBody(req.body, false);

  // Attempt to update the book
  const updatedBook = updateBook(id, req.body);

  // If no book was found, throw NotFoundError
  if (!updatedBook) {
    throw new NotFoundError("Book", id);
  }

  // Respond with 200 OK and the updated book
  res.json(updatedBook);
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// ---------------------------------------------------------------------------

/**
 * @route DELETE /books/:id
 * @description Delete a book by its unique identifier.
 *
 * URL PARAMETER:
 * - `id` — The numeric ID of the book to delete
 *
 * WHY RETURN 204 NO CONTENT? Per HTTP specification, successful deletion should
 * return 204 with no response body. This signals that the resource has been
 * removed and there's nothing to return. Some APIs return 200 with a confirmation
 * message, but 204 is the standard convention.
 *
 * @access Public
 * @example
 *   DELETE /books/1
 */
router.delete("/:id", (req, res) => {
  // Parse and validate the ID
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError("Invalid book ID: must be a number");
  }

  // Attempt to delete the book
  const deleted = deleteBook(id);

  // If no book was found, throw NotFoundError
  if (!deleted) {
    throw new NotFoundError("Book", id);
  }

  // Respond with 204 No Content — no body needed for successful deletion
  res.status(204).end();
});

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------

/**
 * Export the router so it can be mounted in server.js.
 *
 * WHY EXPORT THE ROUTER? This follows the modular pattern where each route file
 * is a self-contained module that exports its router. The server only needs to
 * import and mount these routers, keeping the architecture clean and testable.
 */
module.exports = router;
```

**REST conventions demonstrated:**

| HTTP Method | Purpose | Status Code on Success |
|-------------|---------|----------------------|
| `GET` | Retrieve resources | 200 OK |
| `POST` | Create a new resource | 201 Created |
| `PUT` | Full update of a resource | 200 OK |
| `DELETE` | Remove a resource | 204 No Content |

**Why async/await isn't used here:** The data layer uses synchronous operations (array methods). In production with a database, you'd use `async/await` for I/O-bound operations. The route handlers are structured to be easily convertible to async when needed.

