curl "http://localhost:3000/books?genre=Fiction"

# Filter by author and minimum rating
curl "http://localhost:3000/books?author=hawking&minRating=4.5"

# Get a single book
curl http://localhost:3000/books/1

# Create a new book
curl -X POST http://localhost:3000/books \
  -H "Content-Type: application/json" \
  -d '{"title":"The Catcher in the Rye","author":"J.D. Salinger","genre":"Fiction","publishedYear":1951,"rating":4.3}'

# Update a book
