## Arquivo 2: `src/errors/customErrors.js`

```javascript
/**
 * ============================================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================================
 *
 * POR QUE criar classes de erro personalizadas?
 * ----------------------------------------------
 * Em vez de simplesmente lançar objetos genéricos ({ message: '...' }),
 * criamos classes que estendem Error para:
 *   1. Manter o stack trace completo (herdado de Error)
 *   2. Incluir um código HTTP padrão (statusCode) para facilitar o middleware
 *      de tratamento de erros
 *   3. Diferenciar tipos de erro no middleware (BadRequestError vs NotFoundError)
 *      usando instanceof, permitindo respostas com status codes corretos
 *
 * PADRÃO ADOTADO: Error Subclassing (herança de Error)
 * Este é o padrão recomendado pela comunidade Node.js para erros customizados.
 */

/**
 * Classe base para todos os erros da API.
 *
 * Escolha do padrão: Usamos uma classe base que já define statusCode = 500
 * (Internal Server Error) como fallback, garantindo que qualquer erro não
 * tratado retorne um status 5xx em vez de silenciosamente falhar.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor de Error, preservando stack trace

    // Estabelece o nome da classe para depuração fácil com console.log(err.name)
    this.name = this.constructor.name;

    // Código HTTP que o middleware usará para montar a resposta
    this.statusCode = statusCode;

    // Flag para diferenciar erros da API de erros não tratados do Node.js
    // Isso evita que middlewares genéricos tratem nosso erro como um bug
    this.isOperational = true;
  }
}

/**
 * Erro 400 Bad Request — dados inválidos enviados pelo cliente.
 *
 * EXEMPLO DE USO:
 *   - Campo obrigatório ausente no body
 *   - ID com formato incorreto (não numérico)
 *   - Valor negativo em campo que não aceita negativos
 */
class BadRequestError extends ApiError {
  constructor(message) {
    super(message, 400); // Sobrescreve statusCode para 400
  }
}

/**
 * Erro 404 Not Found — recurso não encontrado.
 *
 * EXEMPLO DE USO:
 *   - Livro com ID inexistente
 *   - Rota inexistente (tratada separadamente pelo Express)
 */
class NotFoundError extends ApiError {
  constructor(message) {
    super(message, 404); // Sobrescreve statusCode para 404
  }
}

/**
 * Erro 409 Conflict — conflito com estado atual do recurso.
 *
 * EXEMPLO DE USO:
 *   - Tentativa de criar livro com ID duplicado (se permitido)
 */
class ConflictError extends ApiError {
  constructor(message) {
    super(message, 409); // Sobrescreve statusCode para 409
  }
}

/**
 * Exporta todas as classes de erro como um único objeto.
 * Isso facilita a importação em outros módulos com:
 *   const { BadRequestError, NotFoundError } = require('./errors/customErrors');
 */
module.exports = { ApiError, BadRequestError, NotFoundError, ConflictError };
