/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE um middleware de erro dedicado?
 * ----------------------------------------
 * No Express, middlewares de erro têm ASSINATURA DIFERENTE:
 *   (err, req, res, next) => { ... }
 * O Express identifica automaticamente um middleware como handler de erros
 * pelo número de parâmetros (4 em vez de 3). Isso permite centralizar todo
 * o tratamento de erros em UM único lugar, evitando repetição.
 *
 * PADRÃO ADOTADO: Error-First Callback + Express Error Middleware
 * Este é o padrão idiomático do ecossistema Node.js/Express.
 */

const { ApiError } = require('../errors/customErrors');

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err - O erro capturado (pode ser qualquer objeto Error)
 * @param {import('express').Request} req - Objeto Request do Express
 * @param {import('express').Response} res - Objeto Response do Express
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware
 *
 * FLUXO DE DECISÃO:
 * 1. Se for um erro operacional da API (ApiError), retorna status code adequado
 * 2. Se for erro não operacional (bug do servidor), retorna 500 com mensagem genérica
 * 3. Em desenvolvimento, inclui stack trace para depuração
 * 4. Em produção, oculta detalhes sensíveis do erro
 */
function errorHandler(err, req, res, next) {
  // Determina o ambiente para decidir se mostra detalhes do erro
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Caso 1: Erro operacional da API (BadRequestError, NotFoundError, etc.)
  if (err instanceof ApiError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        // name: err.name,          // Opcional: descomente para ver o tipo do erro
        message: err.message,
        // Em desenvolvimento, incluímos o stack trace para facilitar debugging
        ...(isDevelopment && { stack: err.stack }),
      },
    });
  }

  // Caso 2: Erro não operacional (bug inesperado no servidor)
  // Usamos mensagem genérica em produção para não vazar informações sensíveis
  const statusCode = err.statusCode || 500;
  const message = isDevelopment ? err.message : 'Erro interno do servidor';

  console.error('[ERROR]', err); // Log completo no servidor para depuração

  return res.status(statusCode).json({
    success: false,
    error: {
      message,
      ...(isDevelopment && { stack: err.stack }),
    },
  });
}

/**
 * Middleware para rotas não encontradas (404).
 *
 * POR QUE este middleware é necessário?
 * O Express NÃO lança erro automaticamente quando uma rota não corresponde.
 * Precisamos chamar next(err) manualmente para que o errorHandler acima
 * capture e responda com 404 em vez de deixar a requisição pendente.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function handleNotFound(req, res, next) {
  // Criamos um erro com statusCode 404 e chamamos next() para encadeá-lo
  // ao middleware de tratamento de erros
  const err = new Error(`Rota não encontrada: ${req.method} ${req.originalUrl}`);
  err.statusCode = 404;
  next(err);
}

module.exports = { errorHandler, handleNotFound };
```

