/**
 * ============================================================================
 * ROTAS DA API — Gerenciamento de Livros
 * ============================================================================
 *
 * POR QUE rotas em arquivo separado?
 * ----------------------------------
 * Separar rotas do app principal permite:
 *   1. Código mais organizado e legível
 *   2. Facilitar testes unitários por rota
 *   3. Escalonar o projeto adicionando novas rotas sem poluir app.js
 *
 * PADRÃO REST ADOTADO:
 *   - GET    /books          → Listar todos (com filtragem opcional)
 *   - GET    /books/:id      → Obter um específico
 *   - POST   /books          → Criar novo
 *   - PUT    /books/:id      → Atualizar completo (substituir)
 *   - DELETE /books/:id      → Excluir
 *
 * POR QUE PUT e não PATCH?
 *   PUT substitui o recurso inteiro; PATCH atualiza campos específicos.
 *   Para este exemplo, PUT é mais simples de implementar e documentar.
 *   Em uma API real, ofereceríamos ambos.
 *
 * PADRÃO async/await:
 *   Usamos funções assíncronas mesmo sem I/O real (memória) porque:
 *   1. Prepara o código para migração futura a banco de dados
 *   2. Permite uso de try/catch limpo com Promise rejection handling
 *   3. É o padrão moderno do ecossistema Node.js
 */

const express = require('express');
const { books, nextId } = require('../data/books');
const { BadRequestError, NotFoundError } = require('../errors/customErrors');

// Cria um roteador Express isolado. Isso permite aplicar middlewares
// específicos apenas a este conjunto de rotas (ex: validação de body).
const router = express.Router();

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================
/**
 * Lista todos os livros com suporte a filtragem por query parameters.
 *
 * QUERY PARAMETERS suportados:
 *   - author  → Filtra por autor (case-insensitive, partial match)
 *   - genre   → Filtra por gênero (case-insensitive, partial match)
 *   - year    → Filtra por ano exato de publicação
 *   - search  → Busca textual no título ou autor
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?author=machado"
 *   curl "http://localhost:3000/books?genre=Romance&year=1899"
 *   curl "http://localhost:3000/books?search=cortiço"
 *
 * POSTMAN: GET http://localhost:3000/books?author=machado
 */
router.get('/books', async (req, res, next) => {
  try {
    // Desestruturamos os query parameters para filtragem
    const { author, genre, year, search } = req.query;

    let result = books;

    // FILTRO POR AUTOR:
    // .toLowerCase() torna a busca case-insensitive
    // .includes() permite partial match (ex: "mach" encontra "Machado")
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // FILTRO POR GÊNERO: mesmo padrão de busca case-insensitive
    if (genre) {
      const genreLower = genre.toLowerCase();
      result = result.filter((book) =>
        book.genre.toLowerCase().includes(genreLower)
      );
    }

    // FILTRO POR ANO: converte string do query para número
    if (year) {
      const yearNum = parseInt(year, 10);
      if (!isNaN(yearNum)) {
        result = result.filter((book) => book.year === yearNum);
      }
    }

    // BUSCA TEXTUAL: procura no título OU autor
    if (search) {
      const searchLower = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // Resposta 200 OK com os livros filtrados
    // Usamos spread (...) para retornar uma cópia, evitando mutações externas
    res.json({
      success: true,
      count: result.length, // Número de resultados (útil para paginação futura)
      data: [...result],
    });
  } catch (error) {
    // Encadeia o erro ao middleware de tratamento
    next(error);
  }
});

// ============================================================================
// GET /books/:id — Obter livro por ID
// ============================================================================
/**
 * Retorna um único livro identificado pelo parâmetro de rota :id.
 *
 * PARÂMETRO DE ROTA:
 *   - id (string) → Convertido para número via parseInt
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → Retorna 404
 *
 * POSTMAN: GET http://localhost:3000/books/1
 */
router.get('/books/:id', async (req, res, next) => {
  try {
    // Converte ID de string (req.params são sempre strings) para número
    const id = parseInt(req.params.id, 10);

    // Validação: verifica se o ID é um número válido
    if (isNaN(id)) {
      // Lançamos BadRequestError em vez de retornar diretamente porque:
      //   1. Mantém consistência no tratamento de erros
      //   2. Permite que o middleware de erro formate a resposta uniformemente
      throw new BadRequestError('ID inválido. Deve ser um número inteiro.');
    }

    // .find() retorna o PRIMEIRO elemento que satisfaz a condição, ou undefined
    // Isso é mais eficiente que .filter().find() para busca por ID único
    const book = books.find((b) => b.id === id);

    if (!book) {
      // NotFoundError com mensagem contextualizada
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// POST /books — Criar novo livro
// ============================================================================
/**
 * Cria um novo livro a partir dos dados enviados no body da requisição.
 *
 * BODY esperado (JSON):
 *   {
 *     "title": "String obrigatória",
 *     "author": "String obrigatória",
 *     "year": 2024,        // Opcional, padrão: ano atual
 *     "genre": "Ficção"    // Opcional, padrão: "Não especificado"
 *   }
 *
 * EXEMPLOS DE USO:
 *   curl -X POST http://localhost:3000/books \\
 *        -H "Content-Type: application/json" \\
 *        -d '{"title":"Grande Sertão: Veredas","author":"Guimarães Rosa","year":1956,"genre":"Romance"}'
 *
 *   curl -X POST http://localhost:3000/books \\
 *        -H "Content-Type: application/json" \\
 *        -d '{"title":"Sem autor"}'  → Retorna 400 (author é obrigatório)
 *
 * POSTMAN: POST http://localhost:3000/books
 *          Body (raw JSON): {"title":"Teste","author":"Teste Autor","year":2024,"genre":"Ficção"}
 */
router.post('/books', async (req, res, next) => {
  try {
    // Desestruturamos o body para extrair os campos
    const { title, author, year, genre } = req.body;

    // VALIDAÇÃO: Campos obrigatórios
    if (!title || !author) {
      throw new BadRequestError(
        'Campos obrigatórios ausentes: "title" e "author" são requeridos.'
      );
    }

    // Validação adicional: título e autor devem ter pelo menos 1 caractere
    if (typeof title !== 'string' || title.trim().length === 0) {
      throw new BadRequestError('O campo "title" deve ser uma string não vazia.');
    }

    if (typeof author !== 'string' || author.trim().length === 0) {
      throw new BadRequestError('O campo "author" deve ser uma string não vazia.');
    }

    // Validação do ano: se fornecido, deve ser um número válido
    let normalizedYear = year;
    if (year !== undefined && year !== null) {
      normalizedYear = parseInt(year, 10);
      if (isNaN(normalizedYear)) {
        throw new BadRequestError('O campo "year" deve ser um número inteiro.');
      }
      if (normalizedYear < 0 || normalizedYear > new Date().getFullYear() + 1) {
        throw new BadRequestError(
          `O ano deve estar entre 0 e ${new Date().getFullYear() + 1}.`
        );
      }
    }

    // Validação do gênero: se fornecido, deve ser string
    let normalizedGenre = genre || 'Não especificado';
    if (genre !== undefined && typeof genre !== 'string') {
      throw new BadRequestError('O campo "genre" deve ser uma string.');
    }

    // Cria o novo livro com ID auto-incrementado
    const newBook = {
      id: nextId++, // Incrementa após atribuição (pré-incremento seria nextId++)
      title: title.trim(), // Normaliza removendo espaços extras
      author: author.trim(),
      year: normalizedYear || new Date().getFullYear(),
      genre: normalizedGenre.trim(),
      createdAt: new Date().toISOString(), // Timestamp ISO para ordenação futura
    };

    // .push() adiciona ao final do array e retorna o NOVO length
    // Não precisamos do retorno, apenas do efeito colateral (mutação do array)
    books.push(newBook);

    // 201 Created é o status HTTP correto para recursos criados com sucesso
    // O header Location indica onde o recurso foi criado (convenção REST)
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso.',
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id — Atualizar livro existente
// ============================================================================
/**
 * Atualiza completamente um livro existente.
 *
 * NOTA SOBRE PUT vs PATCH:
 *   PUT substitui o recurso inteiro. Todos os campos obrigatórios devem
 *   ser enviados, mesmo que não tenham mudado. Se quiser atualização
 *   parcial, use PATCH (não implementado neste exemplo).
 *
 * BODY esperado (JSON):
 *   {
 *     "title": "Novo título",
 *     "author": "Novo autor",
 *     "year": 2024,
 *     "genre": "Ficção"
 *   }
 *
 * EXEMPLOS DE USO:
 *   curl -X PUT http://localhost:3000/books/1 \\
 *        -H "Content-Type: application/json" \\
 *        -d '{"title":"Dom Casmurro (Ed. Atualizada)","author":"Machado de Assis","year":1899,"genre":"Romance Psicológico"}'
 *
 *   curl -X PUT http://localhost:3000/books/999 \\
 *        -H "Content-Type: application/json" \\
 *        -d '{"title":"X","author":"Y","year":2024,"genre":"Z"}'  → Retorna 404
 *
 * POSTMAN: PUT http://localhost:3000/books/1
 *          Body (raw JSON): {"title":"Novo Título","author":"Novo Autor","year":2024,"genre":"Ficção"}
 */
router.put('/books/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new BadRequestError('ID inválido. Deve ser um número inteiro.');
    }

    // Encontra o índice do livro (usamos indexOf em vez de findIndex para ter ambos)
    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
    }

    // Validação dos campos obrigatórios do body
    const { title, author, year, genre } = req.body;

    if (!title || !author) {
      throw new BadRequestError(
        'Campos obrigatórios ausentes: "title" e "author" são requeridos.'
      );
    }

    // Atualiza o livro no array usando splice (substituição no índice)
    // splice(index, 1, novoLivro) remove 1 elemento na posição index e insere novoLivro
    // Isso é equivalente a books[index] = novoLivro mas mais explícito
    const [updatedBook] = books.splice(index, 1, {
      id, // Mantém o ID original (IDs não são alterados em atualizações)
      title: title.trim(),
      author: author.trim(),
      year: year !== undefined ? parseInt(year, 10) : books[index].year,
      genre: genre || books[index].genre,
      createdAt: books[index].createdAt, // Preserva o timestamp de criação
    });

    // 200 OK para atualização bem-sucedida
    res.json({
      success: true,
      message: 'Livro atualizado com sucesso.',
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id — Excluir livro
// ============================================================================
/**
 * Exclui permanentemente um livro pelo ID.
 *
 * EXEMPLOS DE USO:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → Retorna 404
 *
 * POSTMAN: DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new BadRequestError('ID inválido. Deve ser um número inteiro.');
    }

    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado.`);
    }

    // .splice(index, 1) remove 1 elemento na posição index e retorna um array
    // com o elemento removido. Desestruturamos para obter o livro excluído.
    const [deletedBook] = books.splice(index, 1);

    // 200 OK com o recurso excluído retornado (útil para confirmação)
    // Alternativa: 204 No Content (sem body) — ambas são válidas conforme RFC 7231
    res.json({
      success: true,
      message: 'Livro excluído com sucesso.',
      data: deletedBook,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GET /stats — Estatísticas dos livros
// ============================================================================
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * ESTATÍSTICAS retornadas:
 *   - total: número total de livros
 *   - porGenero: contagem de livros por gênero
 *   - porAutor: contagem de livros por autor
 *   - anoMedio: média dos anos de publicação (arredondada)
 *   - maisAntigo / maisNovo: livros com ano extremos
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/stats
 *
 * POSTMAN: GET http://localhost:3000/stats
 */
router.get('/stats', async (req, res, next) => {
  try {
    const total = books.length;

    // Estatísticas por gênero usando reduce para agrupamento
    // reduce é mais eficiente que criar múltiplos arrays temporários
    const porGenero = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    // Estatísticas por autor — mesmo padrão de agrupamento
    const porAutor = books.reduce((acc, book) => {
      acc[book.author] = (acc[book.author] || 0) + 1;
      return acc;
    }, {});

    // Ano médio: soma todos os anos e divide pela quantidade
    // Math.round para arredondar para inteiro mais próximo
    const anoMedio =
      total > 0
        ? Math.round(books.reduce((sum, b) => sum + b.year, 0) / total)
        : 0;

    // Livros mais antigo e mais novo usando reduce (single pass)
    let maisAntigo = null;
    let maisNovo = null;

    if (total > 0) {
      // Inicializamos com o primeiro livro e comparamos com os demais
      [maisAntigo, maisNovo] = books.reduce(
        ([antigo, novo], book) => {
          if (book.year < antigo.year) antigo = book;
          if (book.year > novo.year) novo = book;
          return [antigo, novo];
        },
        // Valores iniciais: primeiro livro para ambos
        [books[0], books[0]]
      );
    }

    res.json({
      success: true,
      data: {
        total,
        porGenero,
        porAutor,
        anoMedio,
        maisAntigo: maisAntigo
          ? { id: maisAntigo.id, title: maisAntigo.title, year: maisAntigo.year }
          : null,
        maisNovo: maisNovo
          ? { id: maisNovo.id, title: maisNovo.title, year: maisNovo.year }
          : null,
      },
    });
  } catch (error) {
    next(error);
  }
});

// Exporta o roteador para ser usado em app.js
module.exports = router;
```

