## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================================================
 * APP PRINCIPAL — Configuração e Inicialização do Servidor Express
 * ============================================================================
 *
 * POR QUE separar configuração da lógica de rotas?
 * -------------------------------------------------
 * app.js é o ponto de entrada que:
 *   1. Configura middlewares globais (body-parser, CORS se necessário)
 *   2. Registra as rotas do roteador
 *   3. Instala o middleware de tratamento de erros
 *   4. Inicia o servidor na porta configurada
 *
 * PADRÃO ADOTADO: Middleware Pipeline
 * O Express processa middlewares em ordem sequencial. A ordem importa:
 *   1. body-parser → antes das rotas (para ler req.body)
 *   2. Rotas       → lógica de negócio
 *   3. handleNotFound → após rotas (captura requisições sem rota correspondente)
 *   4. errorHandler → por último (captura erros de tudo acima)
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler, handleNotFound } = require('./middleware/errorHandler');

// Cria a aplicação Express
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * express.json() — Parser de body JSON.
 *
 * POR QUE este middleware é necessário?
 * O Express NÃO parseia automaticamente o body das requisições.
 * Sem este middleware, req.body seria undefined em requisições POST/PUT.
 *
 * Opções configuradas:
 *   - limit: '10kb' — limita o tamanho do body para evitar abuse
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware de logging simples para depuração.
 * Registra método, URL e timestamp de cada requisição.
 * Em produção, considere usar um logger como winston ou pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware
});

// ============================================================================
// REGISTRO DE ROTAS
// ============================================================================

/**
 * Registra as rotas de livros.
 * Todas as rotas definidas em routes/books.js estarão disponíveis
 * sob o prefixo / (porque o roteador não tem mount path).
 *
 * Para organizar melhor no futuro, poderíamos usar:
 *   app.use('/api/v1', bookRoutes);
 */
app.use(bookRoutes);

// ============================================================================
// MIDDLEWARES DE ERRO (devem ser os ÚLTIMOS a serem registrados)
// ============================================================================

/**
 * Middleware para rotas não encontradas.
 * Deve vir ANTES do errorHandler para que erros 404 sejam capturados corretamente.
 */
app.use(handleNotFound);

/**
 * Middleware de tratamento de erros global.
 * Deve ser o ÚLTIMO middleware registrado.
 * Captura todos os erros lançados via next(err) nas rotas.
 */
app.use(errorHandler);

// ============================================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================================

/**
 * Porta configurada via variável de ambiente ou padrão 3000.
 * Usamos variável de ambiente para facilitar deploy em diferentes ambientes.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║     API REST de Livros — Servidor Rodando!              ║
║                                                          ║
║   Endereço: http://localhost:${PORT}                      ║
║                                                          ║
║   Endpoints disponíveis:                                 ║
║     GET    /books          → Listar livros              ║
║     GET    /books/:id      → Obter livro por ID         ║
║     POST   /books          → Criar novo livro           ║
║     PUT    /books/:id      → Atualizar livro            ║
║     DELETE /books/:id      → Excluir livro              ║
║     GET    /stats          → Estatísticas               ║
╚══════════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

