## File 2: `src/errors/customErrors.js`

```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY custom error classes?
 *   JavaScript's built-in Error class is functional but not very descriptive.
 *   By extending Error, we create typed errors that middleware can inspect and
 *   respond to appropriately (e.g., 404 for NotFoundError vs 500 for generic).
 *   This follows the principle of "fail loudly with context."
 */

/**
 * Base custom error class.
 * Extends the native Error so all instanceof checks still work.
 * Sets `isOperational` to true so we can distinguish expected errors
 * (like "book not found") from unexpected bugs (like null pointer exceptions).
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {number} statusCode - HTTP status code to return
   */
  constructor(message, statusCode) {
    super(message); // Call parent constructor with the message

    this.statusCode = statusCode;       // Store HTTP status for middleware
    this.isOperational = true;          // Mark as expected/operational error
    Error.captureStackTrace(this, this.constructor); // Clean stack trace
  }
}

/**
 * BadRequestError — Client sent invalid data (400 Bad Request).
 * Examples: missing required fields, malformed ID, invalid query params.
 */
class BadRequestError extends AppError {
  constructor(message = 'Bad request') {
    super(message, 400); // Pass message and status up to parent
  }
}

/**
 * NotFoundError — Requested resource does not exist (404 Not Found).
 * Examples: book ID doesn't exist in the array.
 */
class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

/**
 * ConflictError — Resource already exists (409 Conflict).
 * Examples: duplicate ISBN submission.
 */
class ConflictError extends AppError {
  constructor(message = 'Resource conflict') {
    super(message, 409);
  }
}

module.exports = { AppError, BadRequestError, NotFoundError, ConflictError };
```

> **Key design decisions:**
> - All custom errors extend `AppError`, which extends native `Error`. This means `err instanceof Error` still works everywhere.
> - `isOperational` flag lets our error handler skip logging expected errors (like 404s) while still logging real bugs.
> - Each subclass only needs to call `super(message, statusCode)` — no duplicated logic.

