## File 3: `src/models/book.js`

```javascript
/**
 * ============================================================================
 * BOOK MODEL — In-Memory Data Store
 * ============================================================================
 *
 * WHY an in-memory array?
 *   For this educational example, an array avoids database setup complexity
 *   while still demonstrating CRUD operations. In production, you'd replace
 *   these functions with database calls (e.g., MongoDB, PostgreSQL).
 *
 * DATA STRUCTURE CHOICES:
 *   - `books` array: Simple O(n) lookup is fine for small datasets. For large
 *     datasets, a Map or object keyed by ID would give O(1) lookups.
 *   - Auto-incrementing `id`: Simpler than UUIDs for this example. In production,
 *     use UUIDs to avoid collisions in distributed systems.
 *   - ISO date strings: Standard format that serializes cleanly to JSON.
 */

// Import custom errors so we can throw typed exceptions
const { NotFoundError } = require('../errors/customErrors');

/**
 * In-memory storage for books.
 * Each book is an object with the following shape:
 * {
 *   id: number,           // Unique identifier (auto-incremented)
 *   title: string,        // Book title
 *   author: string,       // Author name
 *   genre: string,        // Genre/category
 *   publishedYear: number,// Year of publication
 *   isbn: string,         // ISBN-13 format
 *   createdAt: string,    // ISO 8601 timestamp
 *   updatedAt: string     // ISO 8601 timestamp (updated on each modification)
 * }
 */
const books = [];

/**
 * Current auto-increment counter for book IDs.
 * Starts at 1 and increments with each new book creation.
 */
let nextId = 1;

// Seed some sample data so the API isn't empty on first launch
seedInitialData();

/**
 * Seeds the in-memory store with sample books.
 * Called once at module load time to provide demo data.
 */
function seedInitialData() {
  const sampleBooks = [
    {
      title: 'To Kill a Mockingbird',
      author: 'Harper Lee',
      genre: 'Fiction',
      publishedYear: 1960,
      isbn: '978-0-06-112008-4'
    },
    {
      title: '1984',
      author: 'George Orwell',
      genre: 'Dystopian',
      publishedYear: 1949,
      isbn: '978-0-451-52493-5'
    },
    {
      title: 'The Great Gatsby',
      author: 'F. Scott Fitzgerald',
      genre: 'Fiction',
      publishedYear: 1925,
      isbn: '978-0-7432-7356-5'
    }
  ];

  // Map each sample book to our full schema with id and timestamps
  const now = new Date().toISOString();
  for (const book of sampleBooks) {
    books.push({
      ...book,
      id: nextId++,
      createdAt: now,
      updatedAt: now
    });
  }
}

/**
 * Retrieves all books from the in-memory store.
 * @returns {Array<Object>} Array of book objects
 */
function getAllBooks() {
  return [...books]; // Return a copy to prevent external mutation
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The book's unique identifier
 * @returns {Object} The matching book object
 * @throws {NotFoundError} If no book with the given ID exists
 */
function getBookById(id) {
  const book = books.find(b => b.id === id);
  if (!book) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }
  return book;
}

/**
 * Creates a new book in the store.
 * @param {Object} bookData - Book properties (title, author, genre, publishedYear, isbn)
 * @returns {Object} The newly created book with id and timestamps
 */
function createBook(bookData) {
  const now = new Date().toISOString();
  const newBook = {
    id: nextId++,
    ...bookData,
    createdAt: now,
    updatedAt: now
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 * Only updates fields that are actually present in updateData
 * (partial update / PATCH-style behavior).
 * @param {number} id - The book's unique identifier
 * @param {Object} updateData - Fields to update
 * @returns {Object} The updated book object
 * @throws {NotFoundError} If no book with the given ID exists
 */
function updateBook(id, updateData) {
  const index = books.findIndex(b => b.id === id);
  if (index === -1) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  // Merge existing book with updated fields
  const updatedBook = {
    ...books[index],
    ...updateData,
    updatedAt: new Date().toISOString() // Always refresh the timestamp
  };

  books[index] = updatedBook;
  return updatedBook;
}

/**
 * Deletes a book by its ID.
 * @param {number} id - The book's unique identifier
 * @returns {boolean} True if deleted, false if not found
 * @throws {NotFoundError} If no book with the given ID exists
 */
function deleteBook(id) {
  const index = books.findIndex(b => b.id === id);
  if (index === -1) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  books.splice(index, 1); // Remove from array
  return true;
}

/**
 * Computes aggregate statistics about the book collection.
 * @returns {Object} Statistics including total count, genre breakdown,
 *   average published year, and author count.
 */
function getStats() {
  const totalBooks = books.length;

  // Group books by genre and count occurrences
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }

  // Calculate average published year
  const totalYear = books.reduce((sum, b) => sum + b.publishedYear, 0);
  const avgPublishedYear = totalBooks > 0
    ? Math.round(totalYear / totalBooks)
    : 0;

  // Count unique authors
  const uniqueAuthors = new Set(books.map(b => b.author)).size;

  return {
    totalBooks,
    genreCounts,
    averagePublishedYear: avgPublishedYear,
    uniqueAuthors
  };
}

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

> **Why return copies (`[...books]`)?** Returning the actual array reference would let external code mutate our internal state without going through our functions. Spreading creates a shallow copy — safe for this use case.
>
> **Why `splice` instead of filtering?** For an in-memory demo with few items, `splice` is O(n) but simple and clear. In production with thousands of records, you'd use a database DELETE.

