## File 4: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY centralized error handling?
 *   Without it, every route handler would need its own try/catch block,
 *   leading to duplicated error-response logic. Express's error-handling
 *   middleware (functions with 4 parameters: err, req, res, next) catches
 *   all errors — both thrown synchronously and passed via next(err).
 *
 * PATTERN: We check `err.isOperational` to decide whether to log it.
 *   - Operational errors (404, 400) are expected; don't spam logs.
 *   - Non-operational errors (null pointer, DB crash) are bugs; log everything.
 */

const { AppError } = require('../errors/customErrors');

/**
 * Global error-handling middleware for Express.
 * Must be registered LAST (after all routes) so it catches errors from anywhere.
 *
 * @param {Error} err - The error object (can be any Error or custom error)
 * @param {import('express').Request} req - Express request object
 * @param {import('express').Response} res - Express response object
 * @param {import('express').NextFunction} next - Express next function
 */
function errorHandler(err, req, res, next) {
  // Default to 500 Internal Server Error for unknown errors
  const statusCode = err.statusCode || 500;

  // Log non-operational errors fully for debugging
  if (!err.isOperational) {
    console.error('[ERROR]', {
      message: err.message,
      stack: err.stack,
      url: req.url,
      method: req.method,
      timestamp: new Date().toISOString()
    });
  }

  // Send a consistent JSON error response shape
  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
      // Only include stack trace in development for security
    }
  });
}

/**
 * 404 handler — catches requests to undefined routes.
 * Placed AFTER all route definitions so it only triggers for unmatched paths.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFoundHandler(req, res, next) {
  // This is called when no route matches the request URL
  next(new AppError(`Cannot ${req.method} ${req.originalUrl}`, 404));
}

module.exports = { errorHandler, notFoundHandler };
```

> **Why 4 parameters?** Express identifies error middleware by the `(err, req, res, next)` signature. Regular middleware has only 3 params. This is a convention Express uses to distinguish them.
>
> **Why `process.env.NODE_ENV` check?** Stack traces contain file paths and internal details — never expose them in production.

