## File 5: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * BOOKS ROUTES
 * ============================================================================
 *
 * WHY separate route files?
 *   As the API grows, keeping all routes in one file becomes unmaintainable.
 *   Express's `Router()` creates a modular, self-contained set of routes that
 *   can be mounted at any path. This follows the "single responsibility" principle.
 *
 * REST CONVENTIONS USED:
 *   - GET    /books       → List all (with optional filters)
 *   - GET    /books/:id   → Get one by ID
 *   - POST   /books       → Create new
 *   - PUT    /books/:id   → Full update (replaces the resource)
 *   - DELETE /books/:id   → Delete by ID
 *
 * ASYNC/AWAIT PATTERN:
 *   We use async route handlers with try/catch. Any error thrown or passed to
 *   next(err) is caught by our global errorHandler middleware. This avoids
 *   repeating try/catch in every handler and keeps the code flat/readable.
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance

// Import model functions (separation of concerns: routes ≠ data logic)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require('../models/book');

// Import custom errors for explicit throwing
const { BadRequestError, NotFoundError } = require('../errors/customErrors');

/**
 * GET /books
 * List all books with optional filtering by genre and/or author.
 *
 * QUERY PARAMETERS:
 *   - genre  (string)  — Filter by exact genre match (case-sensitive)
 *   - author (string)  — Filter by partial author name match (case-insensitive)
 *
 * EXAMPLES:
 *   GET /books                          → All books
 *   GET /books?genre=Fiction            → Only Fiction books
 *   GET /books?author=orwell            → Books by authors containing "orwell"
 *   GET /books?genre=Dystopian&author=1984  → Combined filters (AND logic)
 *
 * CURL EXAMPLES:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fiction"
 *   curl "http://localhost:3000/books?author=lee"
 */
router.get('/', (req, res) => {
  // Destructure query params with defaults for safety
  const { genre, author } = req.query;

  // Start with all books as our base dataset
  let result = getAllBooks();

  // Apply genre filter if provided
  if (genre) {
    result = result.filter(book => book.genre === genre);
  }

  // Apply author filter if provided (partial, case-insensitive match)
  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // Send the filtered (or full) list as JSON
  res.json({
    success: true,
    count: result.length,
    data: result
  });
});

/**
 * GET /books/:id
 * Retrieve a single book by its numeric ID.
 *
 * URL PARAMETER:
 *   - id (number) — The book's unique identifier
 *
 * EXAMPLES:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999    → 404 Not Found
 */
router.get('/:id', (req, res) => {
  // Validate that id is a positive integer
  const id = parseInt(req.params.id, 10);
  if (isNaN(id) || id < 1) {
    throw new BadRequestError('Invalid book ID: must be a positive integer');
  }

  // Model function throws NotFoundError if ID doesn't exist
  const book = getBookById(id);

  res.json({
    success: true,
    data: book
  });
});

/**
 * POST /books
 * Create a new book. Expects a JSON body with required fields.
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "String",          // Required
 *     "author": "String",         // Required
 *     "genre": "String",          // Required
 *     "publishedYear": 2024,      // Required, must be a year
 *     "isbn": "978-0-XXX-XXXXX-X" // Optional but recommended
 *   }
 *
 * EXAMPLES:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dune","author":"Frank Herbert","genre":"Sci-Fi",
 *             "publishedYear":1965,"isbn":"978-0-441-17271-9"}'
 */
router.post('/', (req, res) => {
  const { title, author, genre, publishedYear, isbn } = req.body;

  // Validate required fields — throw BadRequestError for missing data
  if (!title || !author || !genre || !publishedYear) {
    throw new BadRequestError(
      'Missing required fields: title, author, genre, and publishedYear are required'
    );
  }

  // Basic validation: publishedYear should be a reasonable year
  const year = Number(publishedYear);
  if (year < 0 || year > new Date().getFullYear() + 1) {
    throw new BadRequestError('publishedYear must be a valid year');
  }

  // Create the book via our model layer
  const newBook = createBook({ title, author, genre, publishedYear: year, isbn });

  // 201 Created is the standard status for resource creation
  res.status(201).json({
    success: true,
    data: newBook
  });
});

/**
 * PUT /books/:id
 * Fully update an existing book. All required fields must be provided.
 * Note: This is a FULL replacement (not PATCH). Omitted fields will be lost.
 *
 * URL PARAMETER:
 *   - id (number) — The book's unique identifier
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "String",
 *     "author": "String",
 *     "genre": "String",
 *     "publishedYear": 2024,
 *     "isbn": "978-0-XXX-XXXXX-X"
 *   }
 *
 * EXAMPLES:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"To Kill a Mockingbird (50th Anniversary Ed.)",
 *              "author":"Harper Lee","genre":"Fiction",
 *              "publishedYear":1960,"isbn":"978-0-06-112008-4"}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id) || id < 1) {
    throw new BadRequestError('Invalid book ID: must be a positive integer');
  }

  const { title, author, genre, publishedYear, isbn } = req.body;

  // Validate required fields for update
  if (!title || !author || !genre || !publishedYear) {
    throw new BadRequestError(
      'Missing required fields: title, author, genre, and publishedYear are required'
    );
  }

  const year = Number(publishedYear);
  if (year < 0 || year > new Date().getFullYear() + 1) {
    throw new BadRequestError('publishedYear must be a valid year');
  }

  // Model function throws NotFoundError if ID doesn't exist
  const updatedBook = updateBook(id, { title, author, genre, publishedYear: year, isbn });

  res.json({
    success: true,
    data: updatedBook
  });
});

/**
 * DELETE /books/:id
 * Delete a book by its ID. Returns the deleted book in the response body.
 *
 * URL PARAMETER:
 *   - id (number) — The book's unique identifier
 *
 * EXAMPLES:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404 Not Found
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id) || id < 1) {
    throw new BadRequestError('Invalid book ID: must be a positive integer');
  }

  // First, get the book so we can return it in the response
  const book = getBookById(id);

  // Delete it via the model layer
  deleteBook(id);

  // 200 OK with the deleted resource is a common pattern
  res.json({
    success: true,
    data: book
  });
});

module.exports = router;
```

> **Why `throw` instead of `res.status().json()` inside routes?** Throwing lets our centralized error handler manage all responses consistently. If each route handled its own errors, we'd have duplicated response shapes and inconsistent status codes across the API.
>
> **Why 201 for POST?** HTTP spec says 201 Created is the correct status when a new resource is successfully created. Using it makes the API self-documenting.

