## File 7: `src/app.js`

```javascript
/**
 * ============================================================================
 * MAIN APPLICATION ENTRY POINT
 * ============================================================================
 *
 * WHY this structure?
 *   app.js is the "glue" that wires everything together: it configures Express,
 *   mounts middleware in the correct order, registers routes, and starts the server.
 *   Keeping configuration separate from business logic makes testing and
 *   environment-specific overrides (like port numbers) straightforward.
 *
 * MIDDLEWARE ORDER MATTERS:
 *   1. express.json() — Parse JSON request bodies (MUST come before routes)
 *   2. Routes          — Handle incoming requests
 *   3. notFoundHandler — Catch unmatched routes
 *   4. errorHandler    — Catch all errors (MUST be last)
 */

const express = require('express');
const app = express(); // Create the Express application instance

// Import route modules
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import error-handling middleware
const { errorHandler, notFoundHandler } = require('./middleware/errorHandler');

/**
 * Parse incoming JSON request bodies.
 * Limits payload to 10kb to prevent abuse.
 * Without this, req.body would be undefined.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Simple logging middleware for development visibility.
 * Prints method, URL, and status code for every request.
 */
app.use((req, res, next) => {
  const start = Date.now();
  // Hook into the response finish event to log after the response is sent
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} → ${res.statusCode} (${duration}ms)`);
  });
  next(); // Pass control to the next middleware/route
});

/**
 * Mount book routes at /books.
 * All routes defined in src/routes/books.js are now accessible under /books.
 */
app.use('/books', bookRoutes);

/**
 * Mount stats routes at /stats.
 */
app.use('/stats', statsRoutes);

/**
 * Root endpoint for API discovery / health check.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API is running!',
    endpoints: {
      books: {
        GET: '/books',
        POST: '/books',
        GET_one: '/books/:id',
        PUT: '/books/:id',
        DELETE: '/books/:id'
      },
      stats: {
        GET: '/stats'
      }
    }
  });
});

/**
 * Register the 404 handler AFTER all routes.
 * This ensures it only catches truly unmatched requests.
 */
app.use(notFoundHandler);

/**
 * Register the global error handler LAST.
 * Express requires error handlers to have 4 parameters to be recognized.
 */
app.use(errorHandler);

// Start the server — default port is 3000, overridable via PORT env var
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Open http://localhost:${PORT} in your browser to see available endpoints.`);
});

module.exports = app; // Export for testing
```

> **Why export `app`?** Testing frameworks (like Supertest) need the app instance to make HTTP requests without starting a real server. Exporting it enables both direct execution (`node src/app.js`) and programmatic testing.
>
> **Why `res.on('finish')` for logging?** The response might not be sent immediately (e.g., streaming). Listening for the `finish` event ensures we log after the full response is delivered, giving us the accurate status code.

