## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * Por que um middleware dedicado para erros?
 * -------------------------------------------
 * No Express, middlewares de erro têm uma assinatura diferente (4 parâmetros
 * em vez de 3): (err, req, res, next). Eles funcionam como um "guardião central"
 * que captura erros de todas as rotas e padroniza a resposta JSON.
 *
 * Padrão async/await + Express:
 * -------------------------------------------
 * Express não trata automaticamente rejeições de Promises em rotas assíncronas.
 * Por isso, usamos o wrapper express-async-errors ou um middleware que captura
 * erros de promessas. Aqui implementamos manualmente para fins educacionais.
 */

const {
  AppError,
  InternalServerError,
} = require('../classes/errors');

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err — Instância de erro capturada (pode ser AppError ou Error nativo)
 * @param {import('express').Request} req — Objeto de requisição Express
 * @param {import('express').Response} res — Objeto de resposta Express
 * @param {import('express').NextFunction} next — Função para encadear middlewares
 *
 * Comportamento:
 *   - Se err for instância de AppError → responde com statusCode e mensagem do erro
 *   - Se err for Error nativo (bug inesperado) → responde 500 genérico
 *   - Em desenvolvimento, inclui o stack trace na resposta para depuração
 */
const errorHandler = (err, req, res, next) => {
  // Determina o statusCode: usa o do erro operacional ou 500 para bugs
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // Em desenvolvimento, expomos o stack trace para facilitar debugging.
  // Em produção, isso seria omitido por segurança (não vazar caminhos internos).
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Monta a resposta JSON padronizada
  const response = {
    success: false,
    statusCode,
    message: err.message,
    // Inclui campo errorType para facilitar identificação pelo cliente
    errorType: err.constructor.name,
  };

  // Adiciona stack trace apenas em desenvolvimento
  if (isDevelopment && err.stack) {
    response.stack = err.stack;
  }

  // Log do erro no servidor — essencial para monitoramento e debugging
  // Em produção, envie isso para um serviço como Sentry ou ELK Stack
  console.error(`[ERROR] ${new Date().toISOString()}`, {
    method: req.method,
    url: req.originalUrl,
    errorType: err.constructor.name,
    message: err.message,
    ...(isDevelopment && { stack: err.stack }),
  });

  // Envia a resposta JSON
  res.status(statusCode).json(response);
};

/**
 * Middleware para capturar erros de funções assíncronas.
 *
 * Problema: Express não captura automaticamente rejeições de Promises.
 * Se uma rota faz await e a Promise é rejeitada, o servidor crasha.
 *
 * Solução: Envolver cada handler assíncrono com esta função que converte
 * rejeições em chamadas a next(err), permitindo que o errorHandler capture.
 *
 * @param {Function} fn — Função assíncrona do handler Express
 * @returns {Function} Handler Express com tratamento de erros embutido
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    // Retorna a Promise e captura rejeições, passando para next(err)
    fn(req, res, next).catch(next);
  };
};

/**
 * Middleware de validação de campos obrigatórios.
 *
 * Verifica se todos os campos especificados estão presentes no corpo da requisição.
 * Lança BadRequestError se algum campo estiver ausente ou vazio.
 *
 * @param {string[]} fields — Array de nomes de campos obrigatórios
 * @returns {Function} Middleware Express
 */
const validateFields = (fields) => {
  return (req, res, next) => {
    // Filtra campos que estão ausentes ou são strings vazias
    const missingFields = fields.filter((field) => {
      const value = req.body[field];
      return value === undefined || value === null || value === '';
    });

    if (missingFields.length > 0) {
      // Retorna erro 400 com lista dos campos faltantes
      return next(
        new Error(`Campos obrigatórios ausentes: ${missingFields.join(', ')}`)
      );
    }

    next(); // Todos os campos presentes, segue para o próximo middleware/rota
  };
};

module.exports = { errorHandler, asyncHandler, validateFields };
```

**Explicação:** O `asyncHandler` é uma peça crucial. Sem ele, qualquer erro em uma rota assíncrona causaria um crash no servidor (unhandled promise rejection). O wrapper `.catch(next)` converte a rejeição da Promise em um erro que o Express pode encadear até o middleware de tratamento de erros. O `validateFields` é um middleware utilitário reutilizável que evita repetição de lógica de validação em cada rota POST/PUT.

