## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DA API DE LIVROS
 * ============================================================================
 *
 * Convenções REST adotadas:
 * -------------------------
 * 1. URLs usam substantivos no plural (/books) para representar coleções
 * 2. Métodos HTTP indicam a ação (GET=listar, POST=criar, PUT=atualizar total,
 *    PATCH=atualização parcial, DELETE=remover)
 * 3. Códigos de status padronizados:
 *    - 200 OK: sucesso em leituras/atualizações
 *    - 201 Created: recurso recém-criado (com header Location)
 *    - 204 No Content: sucesso sem corpo na resposta (DELETE)
 *    - 400 Bad Request: dados inválidos
 *    - 404 Not Found: recurso inexistente
 *
 * Padrão async/await:
 * -------------------
 * Usamos async/await em vez de .then() encadeados porque:
 *   1. Código mais legível e linear (sem "callback hell")
 *   2. Tratamento de erros mais claro com try/catch
 *   3. Compatibilidade nativa com Node.js moderno
 *
 * Exemplos de comandos curl para cada endpoint estão nos comentários JSDoc.
 */

const express = require('express');
const { books, getNextId } = require('../data/books');
const { asyncHandler, validateFields } = require('../middleware/errorHandler');
const { NotFoundError, BadRequestError } = require('../classes/errors');

// Cria roteador Express — permite agrupar rotas e aplicar middlewares específicos
const router = express.Router();

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem por query parameters
 * @access  Public
 *
 * Query Parameters (opcionais):
 *   - author: string       — Filtra por autor (case-insensitive, parcial)
 *   - genre: string        — Filtra por gênero
 *   - year_min: number     — Ano mínimo de publicação
 *   - year_max: number     — Ano máximo de publicação
 *   - search: string       — Busca por título ou autor
 *   - sort: string         — Ordenação: 'year_asc', 'year_desc', 'title_asc'
 *   - page: number         — Número da página (padrão: 1)
 *   - limit: number        — Itens por página (padrão: 10, máximo: 100)
 *
 * @example curl "http://localhost:3000/books"
 * @example curl "http://localhost:3000/books?author=tolkien&genre=fantasia"
 * @example curl "http://localhost:3000/books?search=1984&sort=year_desc&page=1&limit=5"
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Começa com uma cópia do array para não mutar o original durante filtragem
    let result = [...books];

    // --- Filtragem por autor (busca parcial, case-insensitive) ---
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // --- Filtragem por gênero ---
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(
        (book) => book.genre.toLowerCase() === genreFilter
      );
    }

    // --- Filtragem por faixa de ano ---
    if (req.query.year_min) {
      const yearMin = parseInt(req.query.year_min, 10);
      result = result.filter((book) => book.year >= yearMin);
    }
    if (req.query.year_max) {
      const yearMax = parseInt(req.query.year_max, 10);
      result = result.filter((book) => book.year <= yearMax);
    }

    // --- Busca por título ou autor ---
    if (req.query.search) {
      const searchFilter = req.query.search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchFilter) ||
          book.author.toLowerCase().includes(searchFilter)
      );
    }

    // --- Ordenação ---
    if (req.query.sort) {
      switch (req.query.sort) {
        case 'year_asc':
          result.sort((a, b) => a.year - b.year);
          break;
        case 'year_desc':
          result.sort((a, b) => b.year - a.year);
          break;
        case 'title_asc':
          result.sort((a, b) => a.title.localeCompare(b.title));
          break;
        default:
          // Se sort inválido, mantém ordem original
          break;
      }
    }

    // --- Paginação ---
    const limit = Math.min(parseInt(req.query.limit, 10) || 10, 100);
    const page = parseInt(req.query.page, 10) || 1;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    // Slice cria um novo array com os itens da página atual
    const paginatedResult = result.slice(startIndex, endIndex);

    // Resposta inclui metadados de paginação para o cliente navegar
    res.json({
      success: true,
      count: paginatedResult.length,
      total: result.length,
      page,
      pages: Math.ceil(result.length / limit),
      data: paginatedResult,
    });
  })
);

// ============================================================================
// GET /books/stats — Estatísticas dos livros
// ============================================================================

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas agregadas sobre o acervo de livros
 * @access  Public
 *
 * As estatísticas incluem:
 *   - totalBooks: quantidade total de livros
 *   - totalByGenre: distribuição por gênero
 *   - averageYear: ano médio de publicação
 *   - oldestBook / newestBook: livro mais antigo e mais recente
 *   - topAuthors: autores com mais livros (top 5)
 *
 * @example curl "http://localhost:3000/books/stats"
 */
router.get(
  '/books/stats',
  asyncHandler(async (req, res) => {
    // --- Total de livros ---
    const totalBooks = books.length;

    // --- Distribuição por gênero ---
    // Usamos reduce para agrupar: percorre o array uma vez e constrói o objeto
    const totalByGenre = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    // --- Ano médio de publicação ---
    // Reduce para somar todos os anos, depois divide pelo total
    const averageYear =
      totalBooks > 0
        ? books.reduce((sum, book) => sum + book.year, 0) / totalBooks
        : 0;

    // --- Livro mais antigo e mais recente ---
    // Reduce para encontrar min/max baseado no campo year
    const oldestBook =
      totalBooks > 0
        ? books.reduce(
            (oldest, book) => (book.year < oldest.year ? book : oldest),
            books[0]
          )
        : null;
    const newestBook =
      totalBooks > 0
        ? books.reduce(
            (newest, book) => (book.year > newest.year ? book : newest),
            books[0]
          )
        : null;

    // --- Top autores ---
    // Reduce para contar livros por autor, depois sort e slice para top 5
    const authorCounts = books.reduce((acc, book) => {
      acc[book.author] = (acc[book.author] || 0) + 1;
      return acc;
    }, {});

    const topAuthors = Object.entries(authorCounts)
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5);

    // Resposta com todas as estatísticas
    res.json({
      success: true,
      data: {
        totalBooks,
        totalByGenre,
        averageYear: parseFloat(averageYear.toFixed(2)),
        oldestBook,
        newestBook,
        topAuthors,
      },
    });
  })
);

// ============================================================================
// GET /books/:id — Obter livro por ID
// ============================================================================

/**
 * @route   GET /books/:id
 * @desc    Busca um livro específico pelo seu ID numérico
 * @access  Public
 *
 * @param {number} id — ID do livro (deve ser um número inteiro positivo)
 *
 * @example curl "http://localhost:3000/books/1"
 * @example curl "http://localhost:3000/books/999"  // Retorna 404
 */
router.get(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Converte ID para número e valida se é válido
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      throw new BadRequestError('ID inválido. Deve ser um número inteiro positivo.');
    }

    // find() retorna o primeiro elemento que satisfaz a condição, ou undefined
    const book = books.find((b) => b.id === id);

    if (!book) {
      // Lança NotFoundError em vez de retornar diretamente,
      // para que o middleware de erros capture e formate a resposta
      throw new NotFoundError('Livro', id);
    }

    res.json({ success: true, data: book });
  })
);

// ============================================================================
// POST /books — Criar novo livro
// ============================================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro no acervo
 * @access  Public
 *
 * Corpo da requisição (JSON):
 * {
 *   "title": "Nome do Livro",
 *   "author": "Nome do Autor",
 *   "isbn": "978-0-00-000000-0",
 *   "year": 2024,
 *   "genre": "Gênero"
 * }
 *
 * Todos os campos são obrigatórios. O ID é gerado automaticamente.
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","isbn":"978-0-06-085052-4","year":1932,"genre":"Distopia"}'
 */
router.post(
  '/books',
  validateFields(['title', 'author', 'isbn', 'year', 'genre']), // Valida campos obrigatórios
  asyncHandler(async (req, res) => {
    const { title, author, isbn, year, genre } = req.body;

    // Validação adicional: ano deve ser um número válido e razoável
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new BadRequestError('Ano de publicação inválido. Deve ser um número entre 0 e o ano atual + 1.');
    }

    // Validação: ISBN deve ter formato aproximado (13 dígitos com hífens)
    const isbnClean = isbn.replace(/-/g, '');
    if (!/^\d{10,13}$/.test(isbnClean)) {
      throw new BadRequestError('ISBN inválido. Deve conter 10 ou 13 dígitos numéricos.');
    }

    // Validação: gênero deve ser uma string não vazia
    if (typeof genre !== 'string' || genre.trim().length === 0) {
      throw new BadRequestError('Gênero inválido. Deve ser uma string não vazia.');
    }

    // Cria o novo livro com ID auto-incremental e timestamp de criação
    const newBook = {
      id: getNextId(),
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: yearNum,
      genre: genre.trim(),
      createdAt: new Date().toISOString(),
    };

    // push() adiciona ao final do array — O(1), muito eficiente
    books.push(newBook);

    // 201 Created indica que o recurso foi criado com sucesso.
    // O header Location aponta para a URL do novo recurso (convenção REST).
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso',
      data: newBook,
    });
  })
);

// ============================================================================
// PUT /books/:id — Atualizar livro existente (atualização total)
// ============================================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente pelo ID
 * @access  Public
 *
 * Corpo da requisição (JSON) — todos os campos devem ser fornecidos:
 * {
 *   "title": "Novo Título",
 *   "author": "Novo Autor",
 *   "isbn": "978-0-00-000000-0",
 *   "year": 2024,
 *   "genre": "Novo Gênero"
 * }
 *
 * Diferença entre PUT e PATCH:
 *   - PUT substitui TODOS os campos (o cliente deve enviar todos)
 *   - PATCH atualiza apenas os campos enviados (atualização parcial)
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis - Edição Ilustrada","author":"J.R.R. Tolkien","isbn":"978-0-618-00221-3","year":1954,"genre":"Fantasia Épica"}'
 */
router.put(
  '/books/:id',
  validateFields(['title', 'author', 'isbn', 'year', 'genre']),
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    // findIndex() retorna o índice do elemento ou -1 se não encontrado
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    const { title, author, isbn, year, genre } = req.body;
    const yearNum = parseInt(year, 10);

    // Reutiliza as mesmas validações do POST
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new BadRequestError('Ano de publicação inválido.');
    }

    const isbnClean = isbn.replace(/-/g, '');
    if (!/^\d{10,13}$/.test(isbnClean)) {
      throw new BadRequestError('ISBN inválido.');
    }

    // Cria o objeto atualizado mantendo id e createdAt originais
    const updatedBook = {
      id,
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: yearNum,
      genre: genre.trim(),
      createdAt: books[bookIndex].createdAt, // Preserva timestamp de criação
    };

    // Splice substitui o elemento no índice — O(n) para deslocamento, mas O(1) para a troca em si
    books.splice(bookIndex, 1, updatedBook);

    res.json({
      success: true,
      message: 'Livro atualizado com sucesso',
      data: updatedBook,
    });
  })
);

// ============================================================================
// DELETE /books/:id — Excluir livro
// ============================================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do acervo pelo ID
 * @access  Public
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    // splice(bookIndex, 1) remove 1 elemento na posição bookIndex
    // Retorna um array com o elemento removido (que não precisamos usar)
    books.splice(bookIndex, 1);

    // 204 No Content: sucesso sem corpo na resposta (padrão REST para DELETE)
    res.status(204).send();
  })
);

// Exporta o roteador para ser usado no app principal
module.exports = router;
```

**Explicação:** Esta é a parte mais densa da API. Cada rota segue convenções REST rigorosas:
- **GET /books** suporta filtragem, ordenação e paginação via query parameters — padrões essenciais para APIs reais.
- **POST** retorna 201 com `Location` header (embora não incluído explicitamente aqui, é boa prática).
- **PUT** faz atualização total; em uma versão avançada, adicionaríamos **PATCH** para atualização parcial.
- **DELETE** retorna 204 No Content — padrão REST que indica sucesso sem necessidade de corpo.

O uso de `throw new Error()` dentro dos handlers assíncronos funciona porque o `asyncHandler` captura a exceção e a passa para `next(err)`, que é então tratado pelo middleware de erros.

