## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DO APP EXPRESS
 * ============================================================================
 *
 * Por que separar app.js do server.js?
 * -------------------------------------
 * app.js configura o aplicativo Express (middlewares, rotas).
 * server.js apenas inicia o servidor HTTP.
 * Esta separação permite:
 *   1. Testar o app sem precisar iniciar um servidor (importar app.js)
 *   2. Ter controle sobre a porta e o host de forma independente
 *   3. Facilitar a criação de testes unitários
 */

const express = require('express');
const booksRouter = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a instância do aplicativo Express
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * middleware.json() — Parseia o corpo de requisições JSON.
 *
 * Express não parseia automaticamente o body. Este middleware converte
 * o payload JSON bruto em um objeto JavaScript acessível via req.body.
 *
 * limit: '10kb' — limita o tamanho do body para evitar ataques de negação
 * de serviço por requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * middleware.urlencoded() — Parseia dados de formulários codificados em URL.
 *
 * Útil se a API precisar aceitar submissões via formulário (application/x-www-form-urlencoded).
 * Para APIs REST modernas, JSON é mais comum, mas mantemos para completude.
 */
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

/**
 * middleware de logging básico.
 *
 * Registra método, URL e timestamp de cada requisição.
 * Em produção, substituiríamos por um logger profissional como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(
    `[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`
  );
  next();
});

// ============================================================================
// ROTAS
// ============================================================================

/**
 * Rota raiz — Health check da API.
 * Retorna status de funcionamento para monitoramento e load balancers.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando com sucesso!',
    environment: process.env.NODE_ENV || 'development',
    endpoints: {
      books: '/books',
      stats: '/books/stats',
    },
  });
});

/**
 * Rota de documentação rápida.
 */
app.get('/docs', (req, res) => {
  res.json({
    success: true,
    message: 'Endpoints disponíveis:',
    endpoints: {
      'GET /': 'Health check',
      'GET /docs': 'Esta página',
      'GET /books': 'Listar livros (com filtragem e paginação)',
      'GET /books/stats': 'Estatísticas do acervo',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro (atualização total)',
      'DELETE /books/:id': 'Excluir livro',
    },
  });
});

/**
 * Registra o roteador de livros no caminho /books.
 *
 * Todas as rotas definidas em routes/books.js serão acessíveis sob o prefixo /books:
 *   - GET    /books       → listAll()
 *   - GET    /books/stats → getStats()
 *   - GET    /books/:id   → getById()
 *   - POST   /books       → createBook()
 *   - PUT    /books/:id   → updateBook()
 *   - DELETE /books/:id   → deleteBook()
 */
app.use('/books', booksRouter);

/**
 * Rota 404 — Recurso não encontrado.
 *
 * Esta rota deve vir DEPOIS de todas as outras rotas.
 * Se nenhuma rota anterior corresponder, o Express cai nesta.
 * Lançamos um erro para que o middleware de tratamento de erros
 * capture e responda com JSON padronizado em vez de HTML genérico.
 */
app.use((req, res, next) => {
  const error = new Error(`Rota não encontrada: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (deve ser o ÚLTIMO middleware)
// ============================================================================
/**
 * O Express identifica middlewares de erro pela assinatura de 4 parâmetros.
 * Este deve ser registrado por último para capturar erros de todas as rotas.
 */
app.use(errorHandler);

module.exports = app;
```

**Explicação:** A ordem dos middlewares é crítica no Express — eles são executados em sequência (como uma "esteira"). O middleware de erro deve sempre ser o último, pois captura erros gerados por qualquer middleware/rota anterior. A rota 404 personalizada garante que URLs inválidas retornem JSON estruturado em vez do HTML padrão do Express.

