```javascript
/**
 * ============================================================================
 * INICIALIZAÇÃO DO SERVIDOR HTTP
 * ============================================================================
 *
 * Por que usar process.env.PORT com fallback?
 * --------------------------------------------
 * Em ambientes de nuvem (Heroku, Railway, Render), a porta é definida pela
 * variável de ambiente PORT. Em desenvolvimento local, usamos 3000 como padrão.
 * Isso garante portabilidade entre ambientes sem modificar o código.
 */

const app = require('./app');

// Define a porta: usa variável de ambiente ou fallback para 3000
const PORT = process.env.PORT || 3000;

// Cria o servidor HTTP a partir do app Express
// express() retorna um função que já é um servidor HTTP, mas explicitar
// torna o código mais claro e permite adicionar lógica de listen separada
const server = app.listen(PORT, () => {
  console.log(`╔══════════════════════════════════════════════════════════╗`);
  console.log(`║         API de Livros — Servidor Iniciado!              ║`);
  console.log(`╠══════════════════════════════════════════════════════════╣`);
  console.log(`║  Ambiente: ${process.env.NODE_ENV || 'development'.padEnd(42)}║`);
  console.log(`║  Porta:    ${PORT.toString().padEnd(46)}║`);
  console.log(`║  Base URL: http://localhost:${PORT}${' '.repeat(18)}║`);
  console.log(`╠══════════════════════════════════════════════════════════╣`);
  console.log(`║  Endpoints:                                             ║`);
  console.log(`║    GET    /              → Health check                 ║`);
  console.log(`║    GET    /docs          → Documentação rápida          ║`);
  console.log(`║    GET    /books         → Listar livros                ║`);
  console.log(`║    GET    /books/stats   → Estatísticas                 ║`);
  console.log(`║    GET    /books/:id     → Obter livro                  ║`);
  console.log(`║    POST   /books         → Criar livro                  ║`);
  console.log(`║    PUT    /books/:id     → Atualizar livro              ║`);
  console.log(`║    DELETE /books/:id     → Excluir livro                ║`);
  console.log(`╚══════════════════════════════════════════════════════════╝`);
});

// Tratamento de erros não capturados no nível do processo
process.on('uncaughtException', (err) => {
  console.error('❌ Uncaught Exception:', err.message);
  console.error(err.stack);
  // Em produção, faríamos shutdown graceful aqui
  process.exit(1);
});

process.on('unhandledRejection', (err) => {
  console.error('❌ Unhandled Rejection:', err.message);
  console.error(err.stack);
  // Encerra o servidor de forma segura
  server.close(() => {
    process.exit(1);
  });
});

module.exports = server;
```

**Explicação:** O `server.js` é a porta de entrada da aplicação. Os handlers `uncaughtException` e `unhandledRejection` são medidas de segurança que capturam erros não tratados no nível do processo Node.js, evitando que o servidor fique em estado inconsistente. Em produção, o ideal seria usar um cluster manager como PM2 que reinicia automaticamente o processo.

