## Arquivo 2: `src/middleware/errors.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UMA CLASSE DE ERRO PERSONALIZADA?
 * ------------------------------------------
 * Criamos uma classe Error customizada (AppError) para que possamos anexar
 * propriedades extras como statusCode e isOperational. Isso nos permite:
 *   - Diferenciar erros do aplicativo (operacionais) de bugs inesperados
 *     (erros não-operacionais / internos do servidor).
 *   - Enviar respostas HTTP adequadas sem expor detalhes sensíveis ao cliente.
 *   - Centralizar o tratamento em um único middleware, evitando repetição.
 *
 * POR QUE UM MIDDLEWARE DE ERROS?
 * --------------------------------
 * Express suporta middlewares de erro com a assinatura (err, req, res, next).
 * Quando qualquer rota ou middleware chama next(err), esse middleware é
 * acionado. Isso evita que tenhamos que repetir blocos try/catch em cada rota.
 */

/**
 * Classe base para erros operacionais da aplicação.
 * Erros operacionais são aqueles esperados — entrada inválida, recurso não encontrado, etc.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível pelo usuário final.
   * @param {number} statusCode - Código HTTP correspondente (400, 404, 500, etc.).
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error nativa

    this.statusCode = statusCode;
    this.isOperational = true; // Indica que é um erro esperado, não um bug

    // Mantém o stack trace limpo — removemos o frame do próprio AppError
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Middleware principal de tratamento de erros.
 *
 * POR QUE VERIFICAR `err.isOperational`?
 * ---------------------------------------
 * Erros operacionais (4xx) devem ser retornados ao cliente com a mensagem original.
 * Erros não-operacionais (5xx, bugs inesperados) devem logar o stack trace no
 * servidor mas retornar uma mensagem genérica para o cliente — nunca expor detalhes
 * internos da aplicação em produção.
 *
 * @param {Error} err - A instância de erro capturada pelo Express.
 * @param {import('express').Request} req - Objeto de requisição.
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para o próximo middleware.
 */
const errorHandler = (err, req, res, next) => {
  // Se não houver statusCode definido, assume erro interno do servidor
  err.statusCode = err.statusCode || 500;
  err.isOperational = err.isOperational !== false;

  if (err.isOperational) {
    // Erro operacional: retorna mensagem ao cliente + código HTTP adequado
    res.status(err.statusCode).json({
      status: 'error',
      message: err.message,
    });
  } else {
    // Erro não-operacional (bug): log completo no servidor, resposta genérica ao cliente
    console.error('❌ ERRO NÃO OPERACIONAL:', err);
    res.status(500).json({
      status: 'error',
      message: 'Erro interno do servidor. Tente novamente mais tarde.',
    });
  }
};

/**
 * Middleware para erros de "Rota Não Encontrada" (404).
 *
 * POR QUE COLOCAR ESTE MIDDLEWARE NO FINAL DAS ROTAS?
 * ----------------------------------------------------
 * Ele só será acionado se nenhuma rota corresponder à URL solicitada.
 * Se o colocássemos no início, capturaria todas as requisições antes que
 * as rotas tivessem chance de responder.
 */
const notFoundHandler = (req, res, next) => {
  // Criamos uma instância de AppError com status 404
  next(new AppError(`Rota não encontrada: ${req.method} ${req.originalUrl}`, 404));
};

module.exports = { AppError, errorHandler, notFoundHandler };
```

