## Arquivo 3: `src/data/books.js`

```javascript
/**
 * ============================================================================
 * ARMAZENAMENTO EM MEMÓRIA (Array)
 * ============================================================================
 *
 * POR QUE USAR UM ARRAY?
 * -----------------------
 * Para este exemplo educacional, um array é a escolha mais simples e direta:
 *   - Inserção no final: O(1) com push()
 *   - Busca por ID: O(n) com findIndex() — aceitável para poucos registros
 *   - Atualização/Exclusão: O(n) com splice() — também aceitável para escala pequena
 *
 * Em produção, usaríamos um banco de dados (SQL ou NoSQL) porque:
 *   - Arrays em memória são perdidos ao reiniciar o servidor.
 *   - Não há persistência, concorrência segura ou indexação eficiente.
 *
 * POR QUE CADA LIVRO TEM PROPRIEDADES ESPECÍFICAS?
 * -------------------------------------------------
 *   - id: Identificador único gerado automaticamente (evita colisões com IDs externos).
 *   - title: Obrigatório, string simples para busca e exibição.
 *   - author: Autor do livro.
 *   - genre: Gênero literário — útil para filtragem na lista.
 *   - year: Ano de publicação — número para ordenação e validação.
 *   - createdAt / updatedAt: Timestamps para auditoria e controle de versão.
 */

/**
 * Array que armazena todos os livros em memória.
 * @type {Array<{id: number, title: string, author: string, genre: string, year: number, createdAt: string, updatedAt: string}>}
 */
const books = [];

/**
 * Gera um ID único baseado no timestamp atual.
 *
 * POR QUE `Date.now()` EM VEZ DE UM CONTADOR?
 * --------------------------------------------
 * Um contador simples (1, 2, 3...) funcionaria, mas Date.now() garante
 * unicidade mesmo se o servidor for reiniciado e o array for recriado.
 * Em um sistema real, usaríamos UUIDs ou IDs do banco de dados.
 *
 * @returns {number} Timestamp atual como ID único.
 */
function generateId() {
  return Date.now();
}

/**
 * Retorna uma cópia profunda (deep copy) de todos os livros.
 *
 * POR QUE RETORNAR CÓPIAS E NÃO REFERÊNCIAS DIRETAS?
 * ---------------------------------------------------
 * Se retornássemos o array original, qualquer consumidor poderia modificá-lo
 * acidentalmente (mutação externa). Retornar cópias protege a integridade dos dados.
 * JSON.parse(JSON.stringify()) é uma forma simples de deep clone para objetos
 * sem funções ou referências circulares — suficiente para este exemplo.
 *
 * @returns {Array} Cópia de todos os livros.
 */
function getAllBooks() {
  return JSON.parse(JSON.stringify(books));
}

/**
 * Encontra um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser buscado.
 * @returns {Object|null} Livro encontrado ou null se não existir.
 */
function findBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Adiciona um novo livro ao array.
 *
 * @param {Object} bookData - Dados do livro a ser criado.
 * @returns {Object} O livro criado com timestamps e ID gerados.
 */
function createBook(bookData) {
  const now = new Date().toISOString();
  const newBook = {
    id: generateId(),
    ...bookData, // Espalha os campos fornecidos pelo usuário
    createdAt: now,
    updatedAt: now,
  };
  books.push(newBook);
  return JSON.parse(JSON.stringify(newBook));
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados (partial update).
 * @returns {Object|null} Livro atualizado ou null se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  books[index] = {
    ...books[index], // Mantém todos os campos existentes
    ...updates,      // Sobrescreve com os novos valores
    updatedAt: new Date().toISOString(), // Atualiza timestamp de modificação
  };

  return JSON.parse(JSON.stringify(books[index]));
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} True se foi removido, False se não encontrado.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // splice remove o elemento na posição index
  return true;
}

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * @returns {Object} Estatísticas: total de livros, média de anos, gêneros com contagem.
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      totalBooks: 0,
      averageYear: null,
      genres: {},
    };
  }

  // Reduz o array para calcular a soma dos anos de publicação
  const sumYears = books.reduce((acc, book) => acc + book.year, 0);

  // Reduz para contar livros por gênero
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  return {
    totalBooks: total,
    averageYear: parseFloat((sumYears / total).toFixed(2)),
    genres,
  };
}

module.exports = {
  getAllBooks,
  findBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

