## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DA API DE LIVROS
 * ============================================================================
 *
 * POR QUE USAR `express.Router()`?
 * ---------------------------------
 * O Router permite encapsular um conjunto de rotas em um módulo separado,
 * facilitando a manutenção e a escalabilidade. Cada rota é uma função que
 * recebe (req, res, next) — o padrão Express.
 *
 * POR QUE USAR async/await EM VEZ DE PROMISES .then()?
 * -----------------------------------------------------
 * async/await torna o código mais legível ao eliminar o encadeamento de
 * promessas. Além disso, erros em funções async são automaticamente
 * rejeitados como promessas, o que permite que o middleware de erro do
 * Express os capture via next(err).
 *
 * POR QUE VALIDAR DADOS DE ENTRADA?
 * ----------------------------------
 * Nunca confie nos dados enviados pelo cliente. A validação previne:
 *   - Campos obrigatórios ausentes
 *   - Tipos de dados incorretos
 *   - Valores fora de intervalo (ex: ano negativo)
 *   - Injeção de scripts via strings maliciosas
 */

const express = require('express');
const router = express.Router();
const { AppError } = require('../middleware/errors');
const {
  getAllBooks,
  findBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../data/books');

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================
/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem por gênero e/ou ano mínimo.
 * @access  Public
 *
 * @query {string} [genre] - Filtra por gênero literário (ex: "ficcao", "historia").
 * @query {number} [minYear] - Filtra livros publicados a partir deste ano.
 *
 * @example curl "http://localhost:3000/books?genre=romance"
 * @example curl "http://localhost:3000/books?minYear=2000"
 * @example curl "http://localhost:3000/books?genre=ficcao&minYear=2010"
 */
router.get('/', (req, res, next) => {
  try {
    let result = getAllBooks();

    // Filtragem por gênero — case-insensitive para melhor UX
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter((book) => book.genre.toLowerCase() === genreFilter);
    }

    // Filtragem por ano mínimo
    if (req.query.minYear) {
      const minYear = parseInt(req.query.minYear, 10);
      if (isNaN(minYear)) {
        return next(new AppError('O parâmetro minYear deve ser um número válido.', 400));
      }
      result = result.filter((book) => book.year >= minYear);
    }

    // Se nenhum livro for encontrado após a filtragem, retornamos 200 com array vazio
    // (não 404 — 404 seria para recurso inexistente, não para lista vazia).
    res.status(200).json({
      status: 'success',
      count: result.length,
      data: result,
    });
  } catch (error) {
    next(error); // Encaminha erro ao middleware de tratamento
  }
});

// ============================================================================
// GET /books/stats — Estatísticas dos livros
// ============================================================================
/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas agregadas sobre os livros.
 * @access  Public
 *
 * @returns {Object} totalBooks, averageYear, genres (contagem por gênero).
 *
 * @example curl "http://localhost:3000/books/stats"
 */
router.get('/stats', (req, res, next) => {
  try {
    const stats = getStats();
    res.status(200).json({
      status: 'success',
      data: stats,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================================
/**
 * @route   GET /books/:id
 * @desc    Retorna um único livro baseado no ID fornecido.
 * @access  Public
 *
 * @param {number} id - ID numérico do livro.
 *
 * @example curl "http://localhost:3000/books/1700000000000"
 */
router.get('/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Validação básica do parâmetro de rota
    if (isNaN(id)) {
      return next(new AppError('O ID deve ser um número válido.', 400));
    }

    const book = findBookById(id);
    if (!book) {
      // Usamos AppError para erros esperados — o middleware os trata como 4xx
      return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
    }

    res.status(200).json({
      status: 'success',
      data: book,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// POST /books — Criar um novo livro
// ============================================================================
/**
 * @route   POST /books
 * @desc    Cria um novo livro no sistema.
 * @access  Public
 *
 * @body {string} title - Título do livro (obrigatório, mínimo 1 caractere).
 * @body {string} author - Autor do livro (obrigatório, mínimo 1 caractere).
 * @body {string} genre - Gênero literário (obrigatório, mínimo 1 caractere).
 * @body {number} year - Ano de publicação (obrigatório, número entre 0 e ano atual+1).
 *
 * @returns {Object} O livro criado com ID e timestamps.
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","genre":"fantasia","year":1954}'
 */
router.post('/', (req, res, next) => {
  try {
    const { title, author, genre, year } = req.body;

    // Validação de campos obrigatórios
    if (!title || typeof title !== 'string' || title.trim().length === 0) {
      return next(new AppError('O campo "title" é obrigatório e deve ser uma string não vazia.', 400));
    }
    if (!author || typeof author !== 'string' || author.trim().length === 0) {
      return next(new AppError('O campo "author" é obrigatório e deve ser uma string não vazia.', 400));
    }
    if (!genre || typeof genre !== 'string' || genre.trim().length === 0) {
      return next(new AppError('O campo "genre" é obrigatório e deve ser uma string não vazia.', 400));
    }
    if (year === undefined || year === null) {
      return next(new AppError('O campo "year" é obrigatório.', 400));
    }

    const yearNum = parseInt(year, 10);
    const currentYear = new Date().getFullYear();
    if (isNaN(yearNum) || yearNum < 0 || yearNum > currentYear + 1) {
      return next(new AppError(`O campo "year" deve ser um número entre 0 e ${currentYear + 1}.`, 400));
    }

    // Cria o livro com os dados validados
    const newBook = createBook({
      title: title.trim(),
      author: author.trim(),
      genre: genre.trim().toLowerCase(),
      year: yearNum,
    });

    // 201 Created é o código HTTP padrão para recursos criados com sucesso
    res.status(201).json({
      status: 'success',
      message: 'Livro criado com sucesso.',
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================================
/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente.
 * @access  Public
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @body {string} [title] - Novo título.
 * @body {string} [author] - Novo autor.
 * @body {string} [genre] - Novo gênero.
 * @body {number} [year] - Novo ano de publicação.
 *
 * @returns {Object} O livro atualizado.
 *
 * @example curl -X PUT http://localhost:3000/books/1700000000000 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Novo Título","author":"Novo Autor","genre":"ficcao","year":2023}'
 */
router.put('/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return next(new AppError('O ID deve ser um número válido.', 400));
    }

    // Verifica se o livro existe antes de tentar atualizar
    const existingBook = findBookById(id);
    if (!existingBook) {
      return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
    }

    const updates = {};

    // Validação condicional — só valida campos que foram fornecidos
    if (req.body.title !== undefined) {
      if (typeof req.body.title !== 'string' || req.body.title.trim().length === 0) {
        return next(new AppError('O campo "title" deve ser uma string não vazia.', 400));
      }
      updates.title = req.body.title.trim();
    }

    if (req.body.author !== undefined) {
      if (typeof req.body.author !== 'string' || req.body.author.trim().length === 0) {
        return next(new AppError('O campo "author" deve ser uma string não vazia.', 400));
      }
      updates.author = req.body.author.trim();
    }

    if (req.body.genre !== undefined) {
      if (typeof req.body.genre !== 'string' || req.body.genre.trim().length === 0) {
        return next(new AppError('O campo "genre" deve ser uma string não vazia.', 400));
      }
      updates.genre = req.body.genre.trim().toLowerCase();
    }

    if (req.body.year !== undefined) {
      const yearNum = parseInt(req.body.year, 10);
      const currentYear = new Date().getFullYear();
      if (isNaN(yearNum) || yearNum < 0 || yearNum > currentYear + 1) {
        return next(new AppError(`O campo "year" deve ser um número entre 0 e ${currentYear + 1}.`, 400));
      }
      updates.year = yearNum;
    }

    // Se nenhum campo válido foi fornecido, retorna erro
    if (Object.keys(updates).length === 0) {
      return next(new AppError('Nenhum campo válido para atualização foi fornecido.', 400));
    }

    const updatedBook = updateBook(id, updates);

    res.status(200).json({
      status: 'success',
      message: 'Livro atualizado com sucesso.',
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id — Excluir um livro
// ============================================================================
/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do sistema pelo ID.
 * @access  Public
 *
 * @param {number} id - ID do livro a ser removido.
 *
 * @returns {Object} Mensagem de confirmação.
 *
 * @example curl -X DELETE http://localhost:3000/books/1700000000000
 */
router.delete('/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return next(new AppError('O ID deve ser um número válido.', 400));
    }

    const existingBook = findBookById(id);
    if (!existingBook) {
      return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
    }

    deleteBook(id);

    // 204 No Content é o código padrão para exclusões bem-sucedidas sem corpo de resposta.
    // Aqui optamos por 200 com mensagem para manter a consistência com os outros endpoints.
    res.status(200).json({
      status: 'success',
      message: `Livro com ID ${id} foi removido com sucesso.`,
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

