## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DO APP EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * app.js configura a aplicação (middlewares, rotas) enquanto server.js
 * apenas inicia o servidor HTTP. Essa separação permite:
 *   - Testar a aplicação sem precisar iniciar um servidor (importar app.js).
 *   - Reutilizar a configuração do app em diferentes contextos (HTTP, testes).
 *
 * POR QUE `express.json()`?
 * -------------------------
 * O Express não faz parsing automático de JSON no corpo das requisições.
 * Sem este middleware, req.body seria undefined para requisições POST/PUT.
 */

const express = require('express');
const { errorHandler, notFoundHandler } = require('./middleware/errors');
const booksRouter = require('./routes/books');

const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * Middleware para parsing de JSON no corpo das requisições.
 * Limitamos a 10kb para evitar requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware simples de logging — útil para depuração.
 * Registra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next(); // Sempre chama next() para continuar a cadeia de middlewares
});

// ============================================================================
// ROTAS
// ============================================================================

/**
 * Rota raiz — serve como health check e documentação básica.
 */
app.get('/', (req, res) => {
  res.json({
    status: 'success',
    message: 'API de Livros — exemplo educacional Node.js + Express.',
    endpoints: {
      'GET /books': 'Listar todos os livros (com filtragem opcional)',
      'GET /books/stats': 'Estatísticas dos livros',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro',
    },
  });
});

/**
 * Mount da rota de livros no caminho /books.
 * Isso significa que todas as rotas definidas em books.js
 * serão acessíveis sob o prefixo /books (ex: /books, /books/123).
 */
app.use('/books', booksRouter);

// ============================================================================
// MIDDLEWARES DE ERRO — DEVEM SEMPRE VIR POR ÚLTIMO
// ============================================================================

/**
 * Middleware 404 para rotas não encontradas.
 * Deve vir ANTES do middleware de erro geral.
 */
app.use(notFoundHandler);

/**
 * Middleware global de tratamento de erros.
 * Captura erros de todas as rotas e middlewares anteriores.
 * A assinatura (err, req, res, next) com 4 parâmetros é o que identifica
 * um middleware de erro no Express — se tivesse 3 ou menos, seria tratado
 * como middleware normal.
 */
app.use(errorHandler);

module.exports = app;
```

