## File 2: `src/models/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 * 
 * WHY IN-MEMORY? For an educational example, an in-memory array lets us focus on
 * learning REST API patterns without the complexity of setting up a database.
 * The array is initialized with sample data so you can test endpoints immediately.
 * 
 * DATA STRUCTURE CHOICES:
 * - Array of objects: Simple, ordered, supports filtering and searching natively.
 * - Each book has a unique 'id' (number): Easier to work with than UUIDs for learning.
 *   In production, you'd use auto-incrementing integers or UUIDs from a database.
 * 
 * LIMITATIONS OF THIS APPROACH:
 * - Data is lost when the server restarts (no persistence).
 * - Not thread-safe (not an issue for this single-process example).
 * - Scales poorly for large datasets (O(n) lookups vs O(1) with indexed DB).
 */

// ============================================================================
// SAMPLE DATA — Pre-populated so you can test GET endpoints immediately.
// In production, this would come from a database seed or migration.
// ============================================================================
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Classic Fiction",
    publishedYear: 1925,
    isbn: "978-0743273565",
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z")
  },
  {
    id: 2,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Southern Gothic",
    publishedYear: 1960,
    isbn: "978-0061120084",
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z")
  },
  {
    id: 3,
    title: "1984",
    author: "George Orwell",
    genre: "Dystopian Fiction",
    publishedYear: 1949,
    isbn: "978-0451524935",
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z")
  },
  {
    id: 4,
    title: "Pride and Prejudice",
    author: "Jane Austen",
    genre: "Romance Fiction",
    publishedYear: 1813,
    isbn: "978-0141439518",
    createdAt: new Date("2024-01-01T00:00:00Z"),
    updatedAt: new Date("2024-01-01T00:00:00Z")
  }
];

// ============================================================================
// NEXT ID TRACKER — Ensures unique IDs when creating new books.
// In a database, this would be handled by an auto-increment column or sequence.
// We start at max(existing ids) + 1 to handle any gaps from deletions.
// ============================================================================
let nextId = Math.max(...books.map(book => book.id)) + 1;

// ============================================================================
// EXPORTED FUNCTIONS — Each function is documented with JSDoc for clarity.
// These operate directly on the in-memory array, making the data flow obvious.
// ============================================================================

/**
 * Retrieves all books from the in-memory store.
 * 
 * @returns {Array<Object>} A copy of the books array to prevent external mutation.
 * @example
 * // Returns: [{ id: 1, title: "...", ... }, ...]
 */
function getAllBooks() {
  return [...books]; // Return a shallow copy — prevents callers from mutating the store directly
}

/**
 * Finds a single book by its unique ID.
 * 
 * @param {number} id - The numeric ID of the book to find.
 * @returns {Object|null} The book object if found, null otherwise.
 * @example
 * getBookById(1) // Returns: { id: 1, title: "The Great Gatsby", ... }
 * getBookById(99) // Returns: null
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * Creates a new book and adds it to the store.
 * 
 * @param {Object} bookData - The book data to create (title, author, genre, etc.).
 * @returns {Object} The newly created book with assigned ID and timestamps.
 * @throws Will throw if required fields are missing (handled by route validation).
 * @example
 * // Input:  { title: "Brave New World", author: "Aldous Huxley", genre: "Dystopian" }
 * // Output: { id: 5, title: "Brave New World", ..., createdAt: Date, updatedAt: Date }
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Auto-increment ID — simple and predictable for learning
    ...bookData,  // Spread the provided data into the book object
    createdAt: new Date(), // Record creation timestamp
    updatedAt: new Date()  // Initialize update timestamp (same as created initially)
  };

  books.push(newBook); // Add to in-memory store

  return { ...newBook }; // Return a copy to prevent external mutation
}

/**
 * Updates an existing book by its ID.
 * 
 * @param {number} id - The numeric ID of the book to update.
 * @param {Object} updates - Partial book data to merge with existing fields.
 * @returns {Object|null} The updated book if found, null if not found.
 * @example
 * // Input:  id=1, updates={ title: "The Great Gatsby (Updated)" }
 * // Output: { id: 1, title: "The Great Gatsby (Updated)", ..., updatedAt: Date }
 */
function updateBook(id, updates) {
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) return null; // Book not found

  // Merge existing data with updates — only overwrite provided fields
  books[bookIndex] = {
    ...books[bookIndex],       // Keep all existing fields
    ...updates,                // Overwrite with new values
    id: id,                    // Ensure ID cannot be changed (security)
    updatedAt: new Date()      // Record update timestamp
  };

  return { ...books[bookIndex] }; // Return a copy
}

/**
 * Deletes a book from the store by its ID.
 * 
 * @param {number} id - The numeric ID of the book to delete.
 * @returns {boolean} True if the book was deleted, false if not found.
 * @example
 * deleteBook(1) // Returns: true (book removed from array)
 * deleteBook(99) // Returns: false (no such book)
 */
function deleteBook(id) {
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) return false; // Book not found

  books.splice(bookIndex, 1); // Remove exactly one element at the found index
  return true;
}

/**
 * Calculates aggregate statistics about all books in the store.
 * 
 * @returns {Object} Statistics including total count, genre distribution, and year range.
 * @example
 * getStats() // Returns:
 * // {
 * //   totalBooks: 4,
 * //   genres: { "Classic Fiction": 1, "Dystopian Fiction": 1, ... },
 * //   oldestYear: 1813,
 * //   newestYear: 1960,
 * //   averagePublishedYear: 1914.25
 * // }
 */
function getStats() {
  if (books.length === 0) {
    return {
      totalBooks: 0,
      genres: {},
      oldestYear: null,
      newestYear: null,
      averagePublishedYear: null
    };
  }

  // Count books per genre — useful for understanding the collection's diversity
  const genres = {};
  let oldestYear = Infinity;
  let newestYear = -Infinity;
  let totalYear = 0;

  for (const book of books) {
    // Tally each genre occurrence
    genres[book.genre] = (genres[book.genre] || 0) + 1;

    // Track year range
    if (book.publishedYear < oldestYear) oldestYear = book.publishedYear;
    if (book.publishedYear > newestYear) newestYear = book.publishedYear;
    totalYear += book.publishedYear;
  }

  return {
    totalBooks: books.length,
    genres,
    oldestYear,
    newestYear,
    averagePublishedYear: parseFloat((totalYear / books.length).toFixed(2))
  };
}

// ============================================================================
// MODULE EXPORTS — Makes these functions available to route handlers.
// Using named exports is clearer than a single default export for this module.
// ============================================================================
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

**Key Design Decisions:**
- **Shallow copies on return**: We spread arrays/objects (`[...books]`, `{ ...book }`) to prevent external code from accidentally mutating the internal state. This is a defensive programming pattern.
- **`nextId` counter**: Simple auto-increment avoids collisions without needing a database sequence. In production, you'd use UUIDs or let the DB handle it.
- **Timestamps on every mutation**: `createdAt` and `updatedAt` fields are standard in real APIs for audit trails and cache invalidation.

