## File 3: `src/middleware/errorHandler.js` — Custom Error Classes & Middleware

```javascript
/**
 * @fileoverview Custom error classes and Express middleware for centralized error handling.
 * 
 * WHY CUSTOM ERROR CLASSES? Built-in JavaScript errors (Error, TypeError) don't carry
 * enough context for API responses. Our custom classes include:
 * - HTTP status code (for the response)
 * - Error type/category (for client-side handling)
 * - Validation details (for 400 Bad Request with field-level feedback)
 * 
 * WHY CENTRALIZED ERROR HANDLING? Without this middleware, every route would need its
 * own try/catch block. Express's error-handling middleware (4-argument functions) catches
 * all errors — both thrown synchronously and passed via next(err) from async handlers.
 * This follows the DRY principle and ensures consistent error responses.
 */

// ============================================================================
// CUSTOM ERROR CLASSES — Each extends Error and adds API-specific properties.
// ============================================================================

/**
 * Base error class for all API errors.
 * 
 * @extends Error
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default: 500).
   * @param {string} type - Error category for client-side handling.
   */
  constructor(message, statusCode = 500, type = 'internal_error') {
    super(message); // Call parent constructor with the message

    // Preserve proper stack trace — required because we're overriding the constructor
    Object.setPrototypeOf(this, ApiError.prototype);

    this.statusCode = statusCode; // HTTP status for the response
    this.type = type;             // Error category (e.g., 'not_found', 'validation_error')
    this.isOperational = true;    // Marks as expected error (vs. programming bugs)
  }
}

/**
 * 404 Not Found — Resource does not exist.
 * Used when a requested book ID doesn't match any record.
 */
class NotFoundError extends ApiError {
  constructor(resource, id) {
    super(
      `${resource} with id ${id} not found`, // Dynamic message based on resource type
      404,                                  // HTTP 404 status code
      'not_found'                           // Error category for clients
    );
  }
}

/**
 * 400 Bad Request — Invalid input data.
 * Used when POST/PUT requests contain missing or malformed fields.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message - General error description.
   * @param {Array<Object>} details - Array of field-level validation errors.
   * @example
   * new ValidationError("Invalid book data", [
   *   { field: "title", message: "Title is required" },
   *   { field: "author", message: "Author must be a string" }
   * ])
   */
  constructor(message, details = []) {
    super(message, 400, 'validation_error');
    this.details = details; // Field-specific errors for client-side form feedback
  }
}

/**
 * 500 Internal Server Error — Unexpected server failure.
 * Used as a fallback when an unhandled exception occurs.
 */
class InternalError extends ApiError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500, 'internal_error');
  }
}

// ============================================================================
// ERROR HANDLING MIDDLEWARE — Express's 4-argument function signature.
// 
 * EXPRESS MIDDLEWARE SIGNATURES:
 * - Normal middleware: (req, res, next) => { ... }
 * - Error middleware:  (err, req, res, next) => { ... }
 * 
 * The 'next' parameter is omitted in error middleware because errors have already
 * been caught. Express automatically routes errors to these handlers.
// ============================================================================

/**
 * Centralized error-handling middleware for all Express routes.
 * 
 * This function MUST be registered last (after all routes) so it catches
 * errors from any route. Registering it early would cause it to intercept
 * requests before they reach the actual route handlers.
 * 
 * @param {Error} err - The error object thrown or passed via next(err).
 * @param {Object} req - Express request object (available for logging context).
 * @param {Object} res - Express response object (used to send error response).
 * @param {Function} next - Express next function (not used in error middleware).
 * 
 * RESPONSE FORMAT: All errors return a consistent JSON structure so clients can
 * parse them uniformly regardless of the error type.
 */
function errorHandler(err, req, res, next) {
  // Log the full error for server-side debugging (stack trace + metadata)
  console.error(`[ERROR] ${new Date().toISOString()}`, {
    message: err.message,
    statusCode: err.statusCode,
    type: err.type,
    stack: err.stack, // Full stack trace for developers only — never sent to clients
    path: req.path,   // Which endpoint triggered the error
    method: req.method // HTTP method used
  });

  // Determine if this is an operational API error or an unexpected crash
  const isOperational = err.isOperational === true;

  // Build a consistent error response object
  const errorResponse = {
    success: false,           // Standard field for clients to check
    error: {
      message: err.message,   // Human-readable description
      type: err.type          // Category for client-side routing/handling
    }
  };

  // Add validation details if this is a ValidationError (400)
  // This lets clients show field-specific errors in their forms
  if (err instanceof ValidationError && err.details.length > 0) {
    errorResponse.error.details = err.details;
  }

  // For non-operational errors (programming bugs), don't leak internal details
  // Instead, return a generic message to avoid exposing stack traces to clients
  if (!isOperational) {
    errorResponse.error.message = 'An unexpected server error occurred';
    console.error('Non-operational error — investigate:', err.stack);
  }

  // Send the response with the appropriate status code
  // Default to 500 if err.statusCode is undefined (safety net)
  res.status(err.statusCode || 500).json(errorResponse);
}

// ============================================================================
// MODULE EXPORTS
// ============================================================================
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  InternalError,
  errorHandler
};
```

**Why This Pattern?** Express's error middleware is a **catch-all** that prevents you from needing try/catch in every route. When an async route handler throws, Node.js wraps it and passes it to `next(err)`. Our middleware catches all such errors in one place, ensuring consistent JSON error responses like:

```json
{
  "success": false,
  "error": {
    "message": "Book with id 99 not found",
    "type": "not_found"
  }
}
```

