```javascript
/**
 * @fileoverview REST API routes for book management (CRUD operations).
 * 
 * ROUTE ORGANIZATION: We use Express Router to create a modular route handler.
 * This keeps the main app.js clean and allows these routes to be tested independently.
 * 
 * HTTP METHOD CONVENTIONS (REST):
 * - GET    /books       → List all books (with optional query filters)
 * - GET    /books/:id   → Get a single book by ID
 * - POST   /books       → Create a new book
 * - PUT    /books/:id   → Fully update an existing book
 * - DELETE /books/:id   → Delete a book
 * 
 * WHY PUT vs PATCH? We use PUT for full updates because:
 * - PUT requires all fields to be present (idempotent, predictable)
 * - PATCH would require partial-update logic which adds complexity
 * - For learning purposes, PUT demonstrates the concept more clearly
 * 
 * ASYNC/AWAIT PATTERN: All route handlers are async functions that use await.
 * This is cleaner than .then() chains and makes error handling with try/catch natural.
 * Even though our model uses synchronous operations (in-memory array), using async
 * handlers prepares you for production where database calls ARE asynchronous.
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance

// Import our in-memory data store and error classes
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require('../models/books');
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ============================================================================
// HELPER: Validate book creation/update data.
 * 
 * This centralizes validation logic so every route that creates/updates books
 * uses the same rules. DRY principle — change validation in one place.
 * 
 * @param {Object} data - The request body to validate.
 * @param {boolean} isUpdate - True for PUT (partial), false for POST (full).
 * @returns {Array<Object>} Array of validation error details (empty if valid).
// ============================================================================

/**
 * Validates book data for creation or update operations.
 * 
 * @param {Object} data - The request body containing book fields.
 * @param {boolean} isUpdate - Whether this is an update (allows partial data).
 * @returns {Array<Object>} Array of validation error objects, empty if valid.
 */
function validateBookData(data, isUpdate = false) {
  const errors = [];

  // Title: Required for creation, optional for updates
  if (!isUpdate && !data.title) {
    errors.push({ field: 'title', message: 'Title is required' });
  } else if (typeof data.title !== 'string' || data.title.trim().length === 0) {
    errors.push({ field: 'title', message: 'Title must be a non-empty string' });
  }

  // Author: Required for creation, optional for updates
  if (!isUpdate && !data.author) {
    errors.push({ field: 'author', message: 'Author is required' });
  } else if (typeof data.author !== 'string') {
    errors.push({ field: 'author', message: 'Author must be a string' });
  }

  // Genre: Optional but should be a string if provided
  if (data.genre !== undefined && typeof data.genre !== 'string') {
    errors.push({ field: 'genre', message: 'Genre must be a string' });
  }

  // PublishedYear: Must be a positive integer if provided
  if (data.publishedYear !== undefined) {
    const year = parseInt(data.publishedYear, 10);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      errors.push({ field: 'publishedYear', message: 'PublishedYear must be a valid year' });
    }
  }

  // ISBN: Must follow standard format if provided (simplified check)
  if (data.isbn !== undefined && typeof data.isbn === 'string') {
    const isbnPattern = /^\d{3}[-]?\d{1}[-]?\d{5}[-]?\d{1}$/;
    if (!isbnPattern.test(data.isbn.replace(/-/g, ''))) {
      errors.push({ field: 'isbn', message: 'ISBN must be a valid format (e.g., 978-0743273565)' });
    }
  }

  return errors;
}

// ============================================================================
// GET /books — List all books with optional filtering.
 * 
 * QUERY PARAMETERS (optional):
 * - genre: Filter by book genre (e.g., ?genre=Dystopian)
 * - author: Filter by author name (partial match, case-insensitive)
 * - minYear: Filter books published after this year (e.g., ?minYear=1950)
 * - maxYear: Filter books published before this year (e.g., ?maxYear=1900)
 * 
 * WHY QUERY PARAMETERS? RESTful APIs use URL query strings for filtering because:
 * - They keep the resource path clean (/books, not /books/genre/dystopian)
 * - Multiple filters can be combined (?genre=Dystopian&minYear=1950)
 * - They're cacheable and bookmarkable
// ============================================================================

/**
 * GET /books — Retrieve all books with optional filtering.
 * 
 * @route GET /books
 * @param {string} [query.genre] - Filter by genre (exact match).
 * @param {string} [query.author] - Filter by author name (partial, case-insensitive).
 * @param {number} [query.minYear] - Minimum published year.
 * @param {number} [query.maxYear] - Maximum published year.
 * @returns {Object} Response with success flag and array of books.
 * 
 * @example
 * // GET /books
 * // Returns all 4 books
 * 
 * // GET /books?genre=Dystopian
 * // Returns: [{ id: 3, title: "1984", genre: "Dystopian Fiction", ... }]
 * 
 * // GET /books?author=orwell&minYear=1900
 * // Returns books by Orwell published after 1900
 */
router.get('/books', (req, res) => {
  try {
    // Get all books from the in-memory store
    let result = getAllBooks();

    // Apply filters if query parameters are provided
    // Each filter is applied sequentially — they compose naturally

    // Filter by genre (exact match, case-sensitive for simplicity)
    if (req.query.genre) {
      result = result.filter(book => book.genre === req.query.genre);
    }

    // Filter by author (partial match, case-insensitive)
    if (req.query.author) {
      const authorLower = req.query.author.toLowerCase();
      result = result.filter(book => 
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // Filter by minimum published year
    if (req.query.minYear) {
      const minYear = parseInt(req.query.minYear, 10);
      result = result.filter(book => book.publishedYear >= minYear);
    }

    // Filter by maximum published year
    if (req.query.maxYear) {
      const maxYear = parseInt(req.query.maxYear, 10);
      result = result.filter(book => book.publishedYear <= maxYear);
    }

    // Send the response with HTTP 200 OK
    // We wrap in { success: true, data: ... } for a consistent API response format
    res.json({
      success: true,
      count: result.length,           // How many books match the filters
      data: result                    // The actual book objects
    });
  } catch (error) {
    // This should never happen with in-memory operations, but good practice
    next(error); // Pass to our centralized error handler
  }
});

// ============================================================================
// GET /books/:id — Get a single book by its ID.
 * 
 * URL PARAMETER:
 * - id: The numeric ID of the book (e.g., /books/1)
 * 
 * WHY USE :id IN THE PATH? REST convention places resource identifiers in the URL
 * path, not as query parameters. This makes URLs human-readable and cacheable.
// ============================================================================

/**
 * GET /books/:id — Retrieve a single book by ID.
 * 
 * @route GET /books/:id
 * @param {number} params.id - The numeric ID of the book to retrieve.
 * @returns {Object} Response with success flag and book object.
 * @throws NotFoundError if no book exists with the given ID.
 * 
 * @example
 * // GET /books/1
 * // Returns: { success: true, data: { id: 1, title: "The Great Gatsby", ... } }
 * 
 * // GET /books/99
 * // Returns: { success: false, error: { message: "Book with id 99 not found", type: "not_found" } }
 */
router.get('/books/:id', (req, res) => {
  try {
    // Parse the ID from the URL parameter and convert to integer
    const id = parseInt(req.params.id, 10);

    // Check for valid integer — prevents NaN or non-numeric IDs
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', [
        { field: 'id', message: 'ID must be a numeric value' }
      ]);
    }

    // Look up the book in our data store
    const book = getBookById(id);

    // If not found, throw our custom NotFoundError (caught by error handler)
    if (!book) {
      throw new NotFoundError('Book', id);
    }

    // Send the response with HTTP 200 OK
    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error); // Pass to centralized error handler
  }
});

// ============================================================================
// POST /books — Create a new book.
 * 
 * REQUEST BODY (JSON):
 * - title: string (required)
 * - author: string (required)
 * - genre: string (optional)
 * - publishedYear: number (optional)
 * - isbn: string (optional, validated format)
 * 
 * WHY POST? REST convention uses POST for creating new resources because:
 * - The client doesn't know the resource ID yet (server assigns it)
 * - POST is not idempotent (creating the same data twice creates two records)
 * - This matches the semantic meaning: "create a new book"
// ============================================================================

/**
 * POST /books — Create a new book.
 * 
 * @route POST /books
 * @param {Object} body.title - Book title (required).
 * @param {Object} body.author - Book author (required).
 * @param {string} [body.genre] - Book genre.
 * @param {number} [body.publishedYear] - Publication year.
 * @param {string} [body.isbn] - ISBN number.
 * @returns {Object} Response with success flag and created book object.
 * @throws ValidationError if required fields are missing or invalid.
 * 
 * @example
 * // POST /books
 * // Body: { "title": "Brave New World", "author": "Aldous Huxley", "genre": "Dystopian" }
 * // Returns: { success: true, data: { id: 5, title: "Brave New World", ... } }
 * 
 * // POST /books (missing author)
 * // Returns: { success: false, error: { message: "Invalid book data", details: [...] } }
 */
router.post('/books', (req, res) => {
  try {
    // Extract the request body — Express parses JSON automatically with express.json() middleware
    const { title, author, genre, publishedYear, isbn } = req.body;

    // Validate the incoming data using our shared validation function
    const validationErrors = validateBookData(req.body, false);

    // If any validation errors exist, throw a ValidationError (caught by error handler)
    if (validationErrors.length > 0) {
      throw new ValidationError('Invalid book data', validationErrors);
    }

    // Create the book in our data store
    const newBook = createBook({
      title: title.trim(),           // Trim whitespace from strings
      author: author.trim(),
      genre,                         // Optional — undefined if not provided
      publishedYear: publishedYear ? parseInt(publishedYear, 10) : undefined,
      isbn                             // Optional — validated format in validateBookData
    });

    // Send HTTP 201 Created — this is the standard status for successful resource creation
    // 201 tells clients "a new resource was created at this endpoint"
    res.status(201).json({
      success: true,
      message: 'Book created successfully',
      data: newBook
    });
  } catch (error) {
    next(error); // Pass to centralized error handler
  }
});

// ============================================================================
// PUT /books/:id — Fully update an existing book.
 * 
 * REQUEST BODY (JSON): All fields should be provided for a complete replacement.
 * - title: string (required)
 * - author: string (required)
 * - genre: string (optional)
 * - publishedYear: number (optional)
 * - isbn: string (optional)
 * 
 * WHY PUT? We use PUT instead of PATCH because:
 * - PUT implies a complete replacement of the resource
 * - It's idempotent (calling it twice with same data has same effect)
 * - For learning, it demonstrates the concept more clearly than partial updates
// ============================================================================

/**
 * PUT /books/:id — Fully update an existing book.
 * 
 * @route PUT /books/:id
 * @param {number} params.id - The numeric ID of the book to update.
 * @param {Object} body.title - New book title (required).
 * @param {Object} body.author - New book author (required).
 * @param {string} [body.genre] - New book genre.
 * @param {number} [body.publishedYear] - New publication year.
 * @param {string} [body.isbn] - New ISBN number.
 * @returns {Object} Response with success flag and updated book object.
 * @throws NotFoundError if no book exists with the given ID.
 * @throws ValidationError if required fields are missing or invalid.
 * 
 * @example
 * // PUT /books/1
 * // Body: { "title": "The Great Gatsby (Revised)", "author": "F. Scott Fitzgerald" }
 * // Returns: { success: true, data: { id: 1, title: "The Great Gatsby (Revised)", ... } }
 */
router.put('/books/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', [
        { field: 'id', message: 'ID must be a numeric value' }
      ]);
    }

    // Check if the book exists before attempting update
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book', id);
    }

    // Validate the incoming data (PUT requires full data, so isUpdate=false)
    const validationErrors = validateBookData(req.body, false);
    if (validationErrors.length > 0) {
      throw new ValidationError('Invalid book data', validationErrors);
    }

    // Perform the update in our data store
    const updatedBook = updateBook(id, {
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      genre: req.body.genre,
      publishedYear: req.body.publishedYear ? parseInt(req.body.publishedYear, 10) : undefined,
      isbn: req.body.isbn
    });

    // Send HTTP 200 OK with the updated resource
    res.json({
      success: true,
      message: 'Book updated successfully',
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id — Delete a book by its ID.
 * 
 * WHY DELETE? REST convention uses DELETE for removing resources because:
 * - It's semantically clear: "delete this resource"
 * - It should be idempotent (deleting an already-deleted resource is a no-op)
 * - The response typically includes 204 No Content or the deleted resource
// ============================================================================

/**
 * DELETE /books/:id — Delete a book by ID.
 * 
 * @route DELETE /books/:id
 * @param {number} params.id - The numeric ID of the book to delete.
 * @returns {Object} Response with success flag and deletion confirmation.
 * @throws NotFoundError if no book exists with the given ID.
 * 
 * @example
 * // DELETE /books/1
 * // Returns: { success: true, message: "Book deleted successfully" }
 * 
 * // DELETE /books/99
 * // Returns: { success: false, error: { message: "Book with id 99 not found", type: "not_found" } }
 */
router.delete('/books/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', [
        { field: 'id', message: 'ID must be a numeric value' }
      ]);
    }

    // Check if the book exists before attempting deletion
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book', id);
    }

    // Perform the deletion in our data store
    const deleted = deleteBook(id);

    // Send HTTP 200 OK with confirmation
    // Alternative: use 204 No Content (no body) for a cleaner response
    res.json({
      success: true,
      message: 'Book deleted successfully',
      data: existingBook // Return the deleted book so client knows what was removed
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// MODULE EXPORTS — Export the router for use in app.js.
 * 
 * We export 'router' (not individual routes) because Express expects a Router
 * instance that can be mounted with app.use('/api', router).
// ============================================================================
module.exports = router;
```

**Route Design Notes:**
- **Consistent response format**: Every route returns `{ success: true/false, ... }` so clients can check the `success` flag uniformly.
- **HTTP status codes matter**: 200 OK for reads/updates, 201 Created for new resources, 404 Not Found for missing resources. These are REST conventions that API consumers rely on.
- **Error propagation via `next(error)`**: Instead of try/catch in every route, we let errors bubble up to our centralized error handler. This is the Express way.

