## File 6: `src/app.js` — Main Application Entry Point

```javascript
/**
 * @fileoverview Main Express application that wires together routes, middleware, and configuration.
 * 
 * APPLICATION ARCHITECTURE:
 * 1. Create Express app instance
 * 2. Register middleware (body parser, error handler)
 * 3. Mount route handlers
 * 4. Start the HTTP server
 * 
 * MIDDLEWARE ORDER MATTERS in Express — it executes in registration order:
 * - express.json() must come BEFORE routes that read req.body
 * - errorHandler must come AFTER all routes (it's a catch-all)
 * 
 * WHY SEPARATE SERVER.JS? We keep app.js for configuration and server.js for
 * the listen call. This separation makes testing easier (you can import app
 * without starting the server).
 */

const express = require('express');

// Import our route handlers
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import error handling middleware
const { errorHandler } = require('./middleware/errorHandler');

// ============================================================================
// CREATE EXPRESS APPLICATION
 * 
 * The app object is the heart of every Express application. It provides methods
 * for routing, middleware registration, and template rendering.
// ============================================================================
const app = express();

// ============================================================================
// MIDDLEWARE REGISTRATION — Order matters!
 * 
 * MIDDLEWARE EXECUTION FLOW:
 * Request → [express.json()] → [bookRoutes] → [statsRoutes] → [errorHandler]
 * 
 * Each piece of middleware can:
 * - Modify req/res objects
 * - End the request-response cycle (send a response)
 * - Call next() to pass control to the next middleware
// ============================================================================

/**
 * Body parser middleware — parses incoming JSON requests.
 * 
 * Without this, req.body would be undefined and POST/PUT requests couldn't
 * read the JSON payload. Express 4.x requires this as a separate middleware.
 * 
 * LIMITATION: Only handles application/json content type. For file uploads,
 * you'd need additional middleware like multer.
 */
app.use(express.json());

/**
 * Content-Type sniffing — ensures clients send proper Content-Type headers.
 * This is optional but helpful for debugging and API documentation.
 */
app.use((req, res, next) => {
  // Log every request for debugging (in production, use a proper logging library)
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next(); // Pass control to the next middleware/route
});

// ============================================================================
// ROUTE MOUNTING — Connect route handlers to URL paths.
 * 
 * WHY USE app.use() INSTEAD OF app.get()/app.post()? Because our routes are
 * Express Router instances that contain multiple HTTP methods. app.use() mounts
 * the entire router at the given path prefix.
 * 
 * ROUTE STRUCTURE:
 * - /api/books/* → All book CRUD operations
 * - /api/stats   → Statistics endpoint
// ============================================================================

/**
 * Mount book routes at /api/books.
 * 
 * This means all routes in books.js are prefixed with /api/books:
 * - GET    /api/books       (was router.get('/books'))
 * - GET    /api/books/:id   (was router.get('/books/:id'))
 * - POST   /api/books       (was router.post('/books'))
 * - PUT    /api/books/:id   (was router.put('/books/:id'))
 * - DELETE /api/books/:id   (was router.delete('/books/:id'))
 */
app.use('/api', bookRoutes);

/**
 * Mount stats routes at /api/stats.
 * 
 * This means the stats route is available at:
 * - GET /api/stats
 */
app.use('/api', statsRoutes);

// ============================================================================
// ROOT ENDPOINT — Health check and API documentation entry point.
 * 
 * This provides a simple way to verify the server is running and gives
 * clients an overview of available endpoints.
// ============================================================================

/**
 * GET / — Root endpoint with API information.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API',
    description: 'Educational REST API for managing books using Node.js and Express.js',
    endpoints: {
      books: {
        list: 'GET /api/books',
        getById: 'GET /api/books/:id',
        create: 'POST /api/books',
        update: 'PUT /api/books/:id',
        delete: 'DELETE /api/books/:id'
      },
      stats: {
        getStats: 'GET /api/stats'
      }
    },
    version: '1.0.0'
  });
});

// ============================================================================
// 404 HANDLER — Catch-all for undefined routes.
 * 
 * This middleware runs AFTER all route handlers. If no route matches the
 * request path, Express falls through to this handler and returns 404.
 * 
 * IMPORTANT: This must be registered AFTER all routes, or it would intercept
 * every request before reaching the actual handlers.
// ============================================================================

/**
 * Catches requests to undefined routes and returns 404 Not Found.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Route ${req.method} ${req.path} not found`,
      type: 'not_found'
    }
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE — MUST be last (after all routes).
 * 
 * Express identifies error middleware by its 4-argument signature:
 * (err, req, res, next) => { ... }
 * 
 * Any route or middleware that calls next(error) will have the error
 * caught and handled by this function.
// ============================================================================
app.use(errorHandler);

// ============================================================================
// EXPORT — Makes the app available for server.js to start listening.
 * 
 * Exporting 'app' (not starting the server here) allows:
 * - Testing frameworks to import the app without starting a server
 * - Multiple servers to share the same configuration
 * - Easier debugging and modular development
// ============================================================================
module.exports = app;
```

