/**
 * @fileoverview HTTP server startup script.
 * 
 * This file is separate from app.js to allow the Express app to be imported
 * and tested without starting an actual HTTP server. The listen call here
 * keeps the server lifecycle isolated.
 */

const app = require('./app'); // Import the configured Express app

// ============================================================================
// SERVER CONFIGURATION
 * 
 * PORT: We use 3000 as the default, but allow override via environment variable.
 * This is useful for deployment (Heroku sets PORT automatically) and testing.
 * 
 * HOST: 'localhost' binds to the local machine only. For production, you'd
 * typically bind to '0.0.0.0' to accept external connections.
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

/**
 * Start the HTTP server and log startup information.
 */
app.listen(PORT, HOST, () => {
  console.log(`========================================`);
  console.log(`  Book REST API Server`);
  console.log(`  Running at: http://${HOST}:${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    http://${HOST}:${PORT}/api/books       - List all books`);
  console.log(`  GET    http://${HOST}:${PORT}/api/books/:id   - Get book by ID`);
  console.log(`  POST   http://${HOST}:${PORT}/api/books       - Create new book`);
  console.log(`  PUT    http://${HOST}:${PORT}/api/books/:id   - Update book`);
  console.log(`  DELETE http://${HOST}:${PORT}/api/books/:id   - Delete book`);
  console.log(`  GET    http://${HOST}:${PORT}/api/stats       - Get statistics`);
  console.log(`\nTry: curl http://${HOST}:${PORT}/api/books\n`);
});

// ============================================================================
// GRACEFUL SHUTDOWN — Clean up on process termination.
 * 
 * This ensures the server stops accepting new connections and waits for
 * in-flight requests to complete before exiting.
// ============================================================================

/**
 * Handle graceful shutdown signals (Ctrl+C, kill signal).
 */
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Shutting down gracefully...`);

  // Close the server — stop accepting new connections
  const server = app.server;
  if (server) {
    server.close(() => {
      console.log('Server closed. Exiting process.');
      process.exit(0);
    });

    // Force exit after 10 seconds if graceful shutdown fails
    setTimeout(() => {
      console.error('Could not close connections in time. Forcing exit.');
      process.exit(1);
    }, 10000);
  } else {
    process.exit(0);
  }
};

// Register shutdown handlers for common termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Export the server instance for testing
module.exports = app;
```

