## Arquivo 2: `src/store/books.js`

```javascript
/**
 * @fileoverview Store em memória para persistência de livros.
 *
 * POR QUE UM ARRAY EM MEMÓRIA?
 * -----------------------------
 * Para este exemplo educacional, um array simples é a escolha ideal porque:
 *   1. Não requer instalação de banco de dados (zero configuração).
 *   2. Permite focar nos conceitos de REST, rotas e middleware sem distrações.
 *   3. Operações de leitura/escrita são O(1) para push/pop e O(n) para busca —
 *      aceitável para datasets pequenos (< milhares de registros).
 *
 * LIMITAÇÕES (para conhecimento futuro):
 *   - Dados são perdidos ao reiniciar o servidor (não há persistência disk-based).
 *   - Não suporta concorrência real (sem locking ou transações).
 *   - Em produção, substitua por MongoDB, PostgreSQL, etc.
 */

// ─── Estado do Store ───────────────────────────────────────────────
/**
 * Array que armazena todos os livros.
 *
 * Escolha de estrutura: ARRAY vs MAP vs SET
 *   - ARRAY: mantém ordem de inserção (útil para listagem cronológica).
 *   - Cada elemento é um objeto com propriedades tipadas para validação clara.
 *   - Usamos um contador `nextId` em vez de `Date.now()` para IDs previsíveis
 *     e fáceis de testar (evita colisão e garante monotonicidade).
 */
const books = [];

/**
 * Contador sequencial para geração de IDs únicos.
 * Começa em 1 para facilitar a leitura dos dados iniciais.
 */
let nextId = 1;

// ─── Dados Iniciais (Seed) ─────────────────────────────────────────
/**
 * Livros de exemplo para popular o store ao iniciar.
 * Isso permite testar endpoints imediatamente sem precisar fazer POSTs manuais.
 */
const seedBooks = [
  {
    id: 1,
    titulo: 'O Senhor dos Anéis',
    autor: 'J.R.R. Tolkien',
    ano: 1954,
    genero: 'Fantasia',
    isbn: '978-0618640157'
  },
  {
    id: 2,
    titulo: '1984',
    autor: 'George Orwell',
    ano: 1949,
    genero: 'Distopia',
    isbn: '978-0451524935'
  },
  {
    id: 3,
    titulo: 'Dom Casmurro',
    autor: 'Machado de Assis',
    ano: 1899,
    genero: 'Romance',
    isbn: '978-8525046870'
  }
];

// Popula o store com os dados iniciais
books.push(...seedBooks);
nextId = seedBooks.length + 1; // Próximo ID será 4

// ─── Funções do Store ──────────────────────────────────────────────

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista de objetos livro.
 */
function findAll() {
  return books;
}

/**
 * Busca um livro pelo ID.
 *
 * POR QUE find() em vez de loop manual?
 *   - Array.prototype.find() é nativo, legível e retorna undefined se não encontrar.
 *   - Evita código boilerplate com for/while e variáveis de controle.
 * @param {number} id - ID numérico do livro.
 * @returns {Object|undefined} O livro encontrado ou undefined.
 */
function findById(id) {
  return books.find(book => book.id === id);
}

/**
 * Adiciona um novo livro ao store e retorna o objeto criado com ID atribuído.
 *
 * Padrão adotado: O ID é gerado internamente (nextId++) para garantir unicidade.
 * Se o cliente enviar um `id` no corpo da requisição, ele é ignorado — isso evita
 * colisão de IDs e mantém a responsabilidade de geração de identidade no servidor,
 * que é a convenção REST recomendada (recursos são criados pelo servidor).
 * @param {Object} livroData - Dados do novo livro (sem id).
 * @returns {Object} O livro criado com ID atribuído.
 */
function create(livroData) {
  const novoLivro = {
    id: nextId++,
    ...livroData
  };
  books.push(novoLivro);
  return novoLivro;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * POR QUE usar Object.assign() em vez de mutação direta?
 *   - Cria uma cópia do objeto atual e sobrescreve apenas as propriedades fornecidas,
 *     preservando campos que o cliente não enviou (comportamento PATCH-like).
 *   - Se quiséssemos um comportamento REPLACE completo (sobrescrever tudo), usaríamos
 *     assignment direta. Aqui optamos por atualização parcial, mais flexível.
 * @param {number} id - ID do livro a atualizar.
 * @param {Object} updates - Campos a atualizar.
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado.
 */
function update(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Atualiza apenas as propriedades fornecidas (partial update)
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Remove um livro pelo ID.
 * @param {number} id - ID do livro a remover.
 * @returns {boolean} True se removido, False se não encontrado.
 */
function remove(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o catálogo de livros.
 *
 * POR QUE calcular no store e não na rota?
 *   - Separação de responsabilidades: o store conhece os dados, a rota apenas
 *     orquestra a resposta HTTP. Isso mantém as rotas limpas e testáveis.
 * @returns {Object} Estatísticas do catálogo.
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para agregação
  const generos = books.reduce((acc, book) => {
    acc[book.genero] = (acc[book.genero] || 0) + 1;
    return acc;
  }, {});

  // Ano mais antigo e mais recente
  const anos = books.map(book => book.ano);
  const anoMaisAntigo = total > 0 ? Math.min(...anos) : null;
  const anoMaisRecente = total > 0 ? Math.max(...anos) : null;

  return {
    total,
    porGenero: generos,
    anoMaisAntigo,
    anoMaisRecente
  };
}

// ─── Exportações (Módulo CommonJS) ──────────────────────────────────
/**
 * Exportamos todas as funções do store como um objeto.
 * Isso permite importar tudo com uma única linha: `const store = require('./store')`.
 */
module.exports = {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats
};
```

