## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware de tratamento de erros centralizado.
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * --------------------------------
 * Em Express, middlewares de erro têm a assinatura única (err, req, res, next).
 * Eles capturam erros lançados em rotas, middlewares anteriores ou callbacks async,
 * evitando que um erro não tratado cause o crash do processo Node.js.
 *
 * PADRÃO ADOTADO: Classes de Erro Personalizadas
 *   - Cada tipo de erro (NotFound, BadRequest, etc.) carrega seu próprio código HTTP.
 *   - Isso elimina a necessidade de `if/else` para verificar tipos de erro no handler.
 *   - Facilita a adição de novos tipos de erro no futuro.
 */

// ─── Classes de Erro Personalizadas ────────────────────────────────

/**
 * Classe base para erros da API.
 * Extende Error nativo do JavaScript e adiciona propriedades HTTP.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP de status (padrão: 500).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // Marca como erro esperado da aplicação

    // Mantém o stack trace correto mesmo com classes ES6
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 400 — Bad Request.
 * Usado quando o cliente envia dados inválidos (campos ausentes, tipos errados).
 */
class BadRequestError extends ApiError {
  constructor(message = 'Requisição mal formulada') {
    super(message, 400);
  }
}

/**
 * Erro 404 — Not Found.
 * Usado quando o recurso solicitado não existe no store.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404);
  }
}

// ─── Middleware de Tratamento de Erros ──────────────────────────────

/**
 * Middleware central que captura e responde erros de forma padronizada.
 *
 * POR QUE verificar `err.isOperational`?
 *   - Erros operacionais (nosso ApiError) recebem resposta HTTP adequada.
 *   - Erros não-operacionais (bugs, exceptions inesperadas) logamos internamente
 *     e retornamos 500 genérico para não vazar informações sensíveis ao cliente.
 *
 * @param {Error} err - Objeto de erro capturado.
 * @param {Object} req - Objeto de requisição Express.
 * @param {Object} res - Objeto de resposta Express.
 * @param {Function} next - Função next do Express (não usada aqui, convenção).
 */
function errorHandler(err, req, res, next) {
  // Log interno para debugging (em produção, use um logger como Winston)
  console.error(`[ERROR] ${err.statusCode || err.code || 500} — ${err.message}`);

  // Estrutura de resposta padronizada para todos os erros da API
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode || 500
    }
  };

  // Em desenvolvimento, incluímos o stack trace para facilitar debugging
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.error.stack = err.stack;
  }

  res.status(response.error.statusCode).json(response);
}

// ─── Middleware de Validação de JSON ────────────────────────────────

/**
 * Middleware que intercepta requisições com corpo (POST/PUT/PATCH)
 * e valida se o conteúdo é JSON válido.
 *
 * POR QUE validar antes das rotas?
 *   - Evita que rotas processem req.body como undefined quando o cliente
 *     envia Content-Type incorreto ou payload malformado.
 *   - Retorna 400 imediatamente, sem gastar ciclos de processamento.
 */
function validateJson(req, res, next) {
  // Apenas requisições com corpo precisam de validação
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.headers['content-type'];

    if (!contentType || !contentType.includes('application/json')) {
      return next(new BadRequestError(
        'Content-Type deve ser application/json'
      ));
    }
  }
  next();
}

// ─── Exportações ─────────────────────────────────────────────────────
module.exports = {
  ApiError,
  BadRequestError,
  NotFoundError,
  errorHandler,
  validateJson
};
```

