## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas REST para o recurso /books.
 *
 * CONVENÇÕES REST ADOTADAS:
 * --------------------------
 *   - GET    /books       → Listar todos (com filtragem opcional via query params)
 *   - GET    /books/:id    → Obter um específico
 *   - POST   /books        → Criar novo recurso
 *   - PUT    /books/:id    → Atualizar completamente (ou parcialmente)
 *   - DELETE /books/:id    → Remover recurso
 *   - GET    /stats        → Estatísticas agregadas (recurso derivado)
 *
 * PADRÃO async/await:
 *   - Mesmo sendo operações síncronas (array em memória), usamos async/await
 *     para manter a consistência da assinatura das rotas. No futuro, ao migrar
 *     para um banco de dados real (async por natureza), as rotas não precisarão
 *     ser modificadas.
 *
 * EXEMPLOS DE CURL:
 * -----------------
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Filtrar por gênero
 *   curl "http://localhost:3000/books?genero=Fantasia"
 *
 *   # Buscar por ID
 *   curl http://localhost:3000/books/1
 *
 *   # Criar livro
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"titulo":"Duna","autor":"Frank Herbert","ano":1965,"genero":"Ficção Científica","isbn":"978-0441172719"}'
 *
 *   # Atualizar livro (PUT parcial)
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"ano":1955}'
 *
 *   # Excluir livro
 *   curl -X DELETE http://localhost:3000/books/1
 *
 *   # Estatísticas
 *   curl http://localhost:3000/stats
 */

const express = require('express');
const router = express.Router();
const store = require('../store/books');
const { BadRequestError, NotFoundError } = require('../middleware/errorHandler');

// ─── GET /books — Listar todos os livros (com filtragem) ──────────

/**
 * Lista todos os livros com suporte a filtragem por query parameters.
 *
 * FILTRAGEM:
 *   - ?genero=Fantasia       → Filtra por gênero (case-insensitive)
 *   - ?autor=Tolkien         → Filtra por autor (parcial, case-insensitive)
 *   - ?ano=1954              → Busca exata por ano
 *   - Múltiplos filtros podem ser combinados (AND lógico)
 *
 * EXEMPLO: curl "http://localhost:3000/books?genero=Ficção+Científica&ano=1965"
 */
router.get('/books', async (req, res) => {
  let resultado = store.findAll();

  // Filtragem por gênero — busca exata case-insensitive
  if (req.query.genero) {
    const generoBusca = req.query.genero.toLowerCase();
    resultado = resultado.filter(book =>
      book.genero.toLowerCase() === generoBusca
    );
  }

  // Filtragem por autor — busca parcial case-insensitive
  if (req.query.autor) {
    const autorBusca = req.query.autor.toLowerCase();
    resultado = resultado.filter(book =>
      book.autor.toLowerCase().includes(autorBusca)
    );
  }

  // Filtragem por ano — busca exata
  if (req.query.ano) {
    const anoBusca = parseInt(req.query.ano, 10);
    resultado = resultado.filter(book => book.ano === anoBusca);
  }

  // Resposta padronizada com campo "data" para consistência da API
  res.json({
    success: true,
    count: resultado.length,
    data: resultado
  });
});

// ─── GET /books/:id — Obter livro por ID ──────────────────────────

/**
 * Retorna um único livro pelo seu ID numérico.
 *
 * VALIDAÇÃO DO ID:
 *   - Verifica se o parâmetro :id é um número inteiro positivo.
 *   - Se inválido, lança BadRequestError em vez de deixar o store lidar com NaN.
 */
router.get('/books/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validação do parâmetro de rota — evita que IDs como "abc" cheguem ao store
  if (isNaN(id) || id < 1) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  const livro = store.findById(id);

  // Se não encontrado, lançamos NotFoundError em vez de retornar undefined
  // Isso garante que o middleware de erro trate a resposta corretamente
  if (!livro) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  res.json({
    success: true,
    data: livro
  });
});

// ─── POST /books — Criar novo livro ───────────────────────────────

/**
 * Cria um novo livro no store.
 *
 * VALIDAÇÕES:
 *   - Todos os campos obrigatórios são verificados antes de persistir.
 *   - O ISBN é validado quanto ao formato (13 dígitos, hífens permitidos).
 *   - O ano deve ser um número entre 0 e o ano atual (evita dados absurdos).
 *
 * POR QUE validar no route e não no store?
 *   - A rota conhece o contrato da API (quais campos são obrigatórios).
 *   - O store é genérico e reutilizável — ele apenas armazena/recupera dados.
 *   - Essa separação permite testar validações independentemente do store.
 */
router.post('/books', async (req, res) => {
  const { titulo, autor, ano, genero, isbn } = req.body;

  // Validação de campos obrigatórios
  if (!titulo || !autor || !ano || !genero) {
    throw new BadRequestError(
      'Campos obrigatórios: titulo, autor, ano, genero'
    );
  }

  // Validação do tipo e faixa do ano
  const anoNum = parseInt(ano, 10);
  if (isNaN(anoNum) || anoNum < 0 || anoNum > new Date().getFullYear() + 1) {
    throw new BadRequestError('Ano deve ser um número válido entre 0 e o ano atual');
  }

  // Validação opcional do ISBN (formato básico: 13 dígitos com hífens)
  if (isbn && !/^\d{3}-?\d{1}-?-\d{5}-?\d$/.test(isbn.replace(/-/g, ''))) {
    throw new BadRequestError('ISBN deve conter 13 dígitos');
  }

  const novoLivro = store.create({
    titulo,
    autor,
    ano: anoNum,
    genero,
    isbn: isbn || null
  });

  // 201 Created é o código HTTP semântico para recursos criados com sucesso.
  // Diferente de 200 OK, indica que uma nova entidade foi criada.
  res.status(201).json({
    success: true,
    data: novoLivro
  });
});

// ─── PUT /books/:id — Atualizar livro existente ───────────────────

/**
 * Atualiza um livro existente pelo ID.
 *
 * COMPORTAMENTO:
 *   - Aceita atualização parcial (apenas os campos enviados são modificados).
 *   - Se o cliente quiser atualizar todos os campos, pode enviar o objeto completo.
 *   - Validações similares às do POST são aplicadas aos campos enviados.
 */
router.put('/books/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  // Verifica se o livro existe ANTES de processar atualizações
  const livroExistente = store.findById(id);
  if (!livroExistente) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  const { titulo, autor, ano, genero, isbn } = req.body;

  // Constrói o objeto de atualização apenas com campos presentes no body
  const updates = {};
  if (titulo !== undefined) updates.titulo = titulo;
  if (autor !== undefined) updates.autor = autor;
  if (ano !== undefined) {
    const anoNum = parseInt(ano, 10);
    if (isNaN(anoNum) || anoNum < 0 || anoNum > new Date().getFullYear() + 1) {
      throw new BadRequestError('Ano deve ser um número válido entre 0 e o ano atual');
    }
    updates.ano = anoNum;
  }
  if (genero !== undefined) updates.genero = genero;
  if (isbn !== undefined) {
    if (!/^\d{3}-?\d{1}-?-\d{5}-?\d$/.test(isbn.replace(/-/g, ''))) {
      throw new BadRequestError('ISBN deve conter 13 dígitos');
    }
    updates.isbn = isbn;
  }

  // Se nenhum campo válido foi enviado, retorna erro
  if (Object.keys(updates).length === 0) {
    throw new BadRequestError('Nenhum campo válido para atualização fornecido');
  }

  const livroAtualizado = store.update(id, updates);

  res.json({
    success: true,
    data: livroAtualizado
  });
});

// ─── DELETE /books/:id — Excluir livro ────────────────────────────

/**
 * Remove um livro pelo ID.
 *
 * RESPOSTA:
 *   - 200 OK com o livro removido no corpo (útil para confirmação).
 *   - Alternativamente, poderíamos usar 204 No Content (sem body),
 *     mas incluir o recurso removido ajuda em debugging e testes.
 */
router.delete('/books/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  const livroExistente = store.findById(id);
  if (!livroExistente) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  store.remove(id);

  res.json({
    success: true,
    message: `Livro "${livroExistente.titulo}" removido com sucesso`,
    data: livroExistente
  });
});

// ─── GET /stats — Estatísticas do catálogo ────────────────────────

/**
 * Retorna estatísticas agregadas sobre o catálogo de livros.
 *
 * DADOS RETORNADOS:
 *   - total: quantidade total de livros
 *   - porGenero: contagem de livros por gênero
 *   - anoMaisAntigo / anoMaisRecente: faixa temporal do acervo
 */
router.get('/stats', async (req, res) => {
  const stats = store.getStats();

  res.json({
    success: true,
    data: stats
  });
});

// ─── Exportação do Router ──────────────────────────────────────────
module.exports = router;
```

