## Arquivo 5: `src/app.js`

```javascript
/**
 * @fileoverview Configuração da aplicação Express.
 *
 * POR QUE separar app.js de server.js?
 * -------------------------------------
 *   - app.js configura a aplicação (middlewares, rotas, CORS).
 *   - server.js apenas inicia o servidor HTTP e define a porta.
 *   - Essa separação permite testar a aplicação sem precisar iniciar o servidor,
 *     e facilita a injeção de dependências em testes unitários.
 */

const express = require('express');
const booksRoutes = require('./routes/books');
const { errorHandler, validateJson } = require('./middleware/errorHandler');

const app = express();

// ─── Middlewares Globais ────────────────────────────────────────────

/**
 * express.json() — Parser de corpo JSON.
 *
 * POR QUE é necessário?
 *   - Express não parseia automaticamente o body das requisições.
 *   - Sem este middleware, req.body seria undefined em POST/PUT.
 *   - O limite de 100kb previne ataques de negação de serviço por payloads gigantes.
 */
app.use(express.json({ limit: '100kb' }));

/**
 * Middleware de validação de Content-Type para requisições com corpo.
 * Aplicado antes das rotas para rejeitar rapidamente requests malformados.
 */
app.use(validateJson);

// ─── Rotas ──────────────────────────────────────────────────────────

/**
 * Mount das rotas de livros no caminho /books.
 * Todas as rotas definidas em routes/books.js ficam disponíveis sob este prefixo.
 */
app.use('/books', booksRoutes);

// Rota raiz para verificação de saúde da API
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — exemplo educacional',
    endpoints: {
      'GET /books': 'Listar todos os livros',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro',
      'DELETE /books/:id': 'Excluir livro',
      'GET /stats': 'Estatísticas do catálogo'
    }
  });
});

// ─── Middleware de Tratamento de Erros (DEVE ser o último middleware) ─

/**
 * POR QUE errorHandler deve ser o ÚLTIMO middleware?
 *   - Express executa middlewares na ordem em que são registrados.
 *   - O middleware de erro só é acionado quando next(err) é chamado
 *     ou quando um erro é lançado dentro de uma rota async.
 *   - Se colocado antes das rotas, ele consumiria todas as requisições
 *     sem permitir que as rotas funcionem normalmente.
 */
app.use(errorHandler);

// ─── Exportação ─────────────────────────────────────────────────────
module.exports = app;
```

