## File 2: `middleware/errorHandler.js`

```javascript
/**
 * Custom error classes and global error-handling middleware.
 *
 * Why custom errors?
 * - They carry structured information (statusCode, isOperational) that the
 *   global handler can use to format consistent JSON responses.
 * - Separating "operational" errors (expected, client-caused) from "bugs"
 *   (unexpected server crashes) lets us log differently and avoid leaking
 *   stack traces to API consumers.
 */

/**
 * Base class for all application errors.
 * Extends Error so instanceof checks work naturally.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (e.g., 400, 404).
   */
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    // Marks the error as expected/operational vs. an unexpected bug.
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Thrown when a requested resource does not exist.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

/**
 * Thrown when client input fails validation.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * Global Express error-handling middleware.
 * Must be registered AFTER all routes (Express convention).
 * Signature requires 4 parameters: (err, req, res, next).
 */
function errorHandler(err, req, res, next) {
  // If the error is our custom AppError, use its statusCode and message.
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      message: err.message,
    });
  }

  // For unexpected errors (bugs), log the stack for debugging but return a
  // generic 500 so we don't leak internal details to clients.
  console.error('Unhandled error:', err);
  return res.status(500).json({
    success: false,
    message: 'Internal server error',
  });
}

module.exports = { AppError, NotFoundError, ValidationError, errorHandler };
```

**Key design choices:**  
- `AppError` is the base class so every custom error shares `statusCode` and `isOperational`.  
- The global middleware checks `instanceof AppError` to distinguish expected errors from bugs.  
- Stack traces are only logged server-side; clients never see them (security best practice).

