## File 3: `routes/books.js`

```javascript
/**
 * Book management routes.
 *
 * Why separate route file?
 * - Keeps the main app clean and makes it easy to add more resources later
 *   (e.g., authors, reviews) by creating additional route modules.
 * - Express's Router object gives us a self-contained namespace for handlers.
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError } = require('../middleware/errorHandler');

const router = express.Router();

// ---------------------------------------------------------------------------
// In-memory data store
// ---------------------------------------------------------------------------
/**
 * Array of book objects stored in memory.
 *
 * Why an array?
 * - Simple to iterate for filtering and statistics.
 * - No database setup required, making the example runnable anywhere.
 *
 * Limitations (for educational awareness):
 * - Data is lost when the server restarts.
 * - Not thread-safe; concurrent writes can cause race conditions.
 * - Performance degrades with large datasets (O(n) lookups).
 */
let books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: 'To Kill a Mockingbird', author: 'Harper Lee', genre: 'Fiction', publishedYear: 1960, rating: 4.8 },
  { id: 3, title: 'A Brief History of Time', author: 'Stephen Hawking', genre: 'Science', publishedYear: 1988, rating: 4.7 },
];

// Simple auto-incrementing ID generator.
let nextId = 4;

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Validates required fields for a book object.
 * @param {object} body - Request body to validate.
 * @throws {ValidationError} if any required field is missing or invalid.
 */
function validateBookBody(body) {
  const errors = [];
  if (!body.title || typeof body.title !== 'string') errors.push('title is required and must be a string');
  if (!body.author || typeof body.author !== 'string') errors.push('author is required and must be a string');
  if (!body.genre || typeof body.genre !== 'string') errors.push('genre is required and must be a string');
  if (typeof body.publishedYear !== 'number' || body.publishedYear < 1000 || body.publishedYear > new Date().getFullYear() + 1) {
    errors.push('publishedYear must be a number between 1000 and current year+1');
  }
  if (typeof body.rating !== 'number' || body.rating < 0 || body.rating > 5) {
    errors.push('rating must be a number between 0 and 5');
  }
  if (errors.length > 0) throw new ValidationError(errors.join('; '));
}

/**
 * Validates that the :id parameter is a positive integer.
 * @param {string} idStr - The URL parameter string.
 * @throws {ValidationError} if invalid.
 */
function validateId(idStr) {
  const id = Number(idStr);
  if (!Number.isInteger(id) || id < 1) throw new ValidationError('Invalid book ID');
  return id;
}

// ---------------------------------------------------------------------------
// GET /books - List all books with optional filtering
// ---------------------------------------------------------------------------
/**
 * @route GET /books
 * @description Returns a list of all books. Supports query parameters:
 *              ?genre=<string> and ?author=<string> for case-insensitive filtering.
 * @param {object} req - Express request object.
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response with success flag and book array.
 *
 * Example curl:
 *   curl http://localhost:3000/books?genre=Fiction
 *   curl http://localhost:3000/books?author=hawking
 */
router.get('/books', async (req, res, next) => {
  try {
    let result = books;

    // Filter by genre if provided. Case-insensitive exact match.
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(book => book.genre.toLowerCase() === genreFilter);
    }

    // Filter by author if provided. Case-insensitive partial match.
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book => book.author.toLowerCase().includes(authorFilter));
    }

    res.json({ success: true, data: result });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// GET /books/:id - Get a single book by ID
// ---------------------------------------------------------------------------
/**
 * @route GET /books/:id
 * @description Returns the book with the specified numeric ID.
 * @param {object} req - Express request object.
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response with success flag and single book object.
 *
 * Example curl:
 *   curl http://localhost:3000/books/1
 */
router.get('/books/:id', async (req, res, next) => {
  try {
    const id = validateId(req.params.id);
    const book = books.find(b => b.id === id);
    if (!book) throw new NotFoundError('Book');
    res.json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// POST /books - Create a new book
// ---------------------------------------------------------------------------
/**
 * @route POST /books
 * @description Creates a new book from the request body.
 *              Required fields: title, author, genre, publishedYear, rating.
 * @param {object} req - Express request object (expects JSON body).
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response with success flag and created book object.
 *
 * Example curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.6}'
 */
router.post('/books', async (req, res, next) => {
  try {
    validateBookBody(req.body);
    const newBook = { id: nextId++, ...req.body };
    books.push(newBook);
    // 201 Created is the standard status for resource creation.
    res.status(201).json({ success: true, data: newBook });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// PUT /books/:id - Update an existing book (full replacement)
// ---------------------------------------------------------------------------
/**
 * @route PUT /books/:id
 * @description Replaces the entire book object with the provided fields.
 *              All required fields must be present in the body.
 * @param {object} req - Express request object.
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response with success flag and updated book object.
 *
 * Example curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald","genre":"Classic","publishedYear":1925,"rating":4.7}'
 */
router.put('/books/:id', async (req, res, next) => {
  try {
    const id = validateId(req.params.id);
    const index = books.findIndex(b => b.id === id);
    if (index === -1) throw new NotFoundError('Book');
    validateBookBody(req.body);
    // Preserve the original ID; replace all other fields.
    const updatedBook = { id, ...req.body };
    books[index] = updatedBook;
    res.json({ success: true, data: updatedBook });
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// DELETE /books/:id - Delete a book by ID
// ---------------------------------------------------------------------------
/**
 * @route DELETE /books/:id
 * @description Removes the book with the specified ID from storage.
 * @param {object} req - Express request object.
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response confirming deletion.
 *
 * Example curl:
 *   curl -X DELETE http://localhost:3000/books/2
 */
router.delete('/books/:id', async (req, res, next) => {
  try {
    const id = validateId(req.params.id);
    const index = books.findIndex(b => b.id === id);
    if (index === -1) throw new NotFoundError('Book');
    // Splice removes the element in-place and returns the removed item.
    books.splice(index, 1);
    // 204 No Content is conventional for successful DELETE with no body.
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// GET /stats - Return aggregate statistics about the book collection
// ---------------------------------------------------------------------------
/**
 * @route GET /stats
 * @description Computes and returns summary statistics:
 *              totalBooks, averageRating, genreDistribution, topAuthor.
 * @param {object} req - Express request object.
 * @param {object} res - Express response object.
 * @param {function} next - Express next middleware function.
 * @returns {object} JSON response with success flag and stats object.
 *
 * Example curl:
 *   curl http://localhost:3000/stats
 */
router.get('/stats', async (req, res, next) => {
  try {
    const totalBooks = books.length;

    // Guard against division by zero when collection is empty.
    const averageRating = totalBooks > 0
      ? Math.round((books.reduce((sum, b) => sum + b.rating, 0) / totalBooks) * 100) / 100
      : 0;

    // Count occurrences of each genre.
    const genreDistribution = {};
    books.forEach(book => {
      genreDistribution[book.genre] = (genreDistribution[book.genre] || 0) + 1;
    });

    // Find the author with the most books.
    const authorCounts = {};
    books.forEach(book => {
      authorCounts[book.author] = (authorCounts[book.author] || 0) + 1;
    });
    const topAuthor = Object.entries(authorCounts).sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;

    res.json({
      success: true,
      data: { totalBooks, averageRating, genreDistribution, topAuthor },
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

**Why these patterns?**  
- **Async/await on every handler**: Even though in-memory operations are synchronous, wrapping handlers in `async` makes the code ready for future database calls without refactoring. It also lets us use `try/catch` cleanly with Express's error middleware.  
- **Validation before processing**: We validate IDs and bodies early so invalid requests fail fast with clear 400 errors instead of cryptic runtime exceptions.  
- **HTTP status codes**: `201 Created` for POST, `204 No Content` for DELETE (no body needed), `404 Not Found` when a resource is missing. These follow REST conventions so clients can rely on standard behavior.  
- **Filtering logic**: Genre uses exact case-insensitive match; author uses partial match (`includes`) because users may type only part of a name.

