## Arquivo 2: `src/data/booksData.js`

```javascript
/**
 * @fileoverview Módulo de dados em memória para a API de livros.
 *
 * Este arquivo contém todos os dados persistentes da aplicação, armazenados
 * em arrays e objetos JavaScript simples. Em uma aplicação real, estes dados
 * seriam persistidos em um banco de dados (MongoDB, PostgreSQL, etc.).
 *
 * Escolha da estrutura de dados:
 * - Usamos um array `books` para armazenar os livros porque a ordem de inserção
 *   pode ser relevante e arrays oferecem acesso por índice.
 * - Cada livro é um objeto com propriedades tipadas (id numérico, título/string, etc.)
 *   para facilitar validação e documentação JSDoc.
 * - O array `stats` é calculado sob demanda a partir dos dados, evitando
 *   inconsistência entre estado armazenado e estado real.
 */

/**
 * Array principal que armazena todos os livros da API.
 * @type {Array<Book>}
 *
 * Por que um array? Arrays em JavaScript são dinâmicos (não precisam de tamanho fixo),
 * suportam métodos úteis como filter(), map(), find() e oferecem performance O(n)
 * para buscas lineares — aceitável para datasets pequenos em exemplos educacionais.
 */
const books = [
  {
    id: 1,
    title: "O Senhor dos Anéis",
    author: "J.R.R. Tolkien",
    year: 1954,
    genre: "Fantasia",
    isbn: "978-0-618-12416-3",
    createdAt: new Date("2024-01-15T10:00:00Z"),
  },
  {
    id: 2,
    title: "1984",
    author: "George Orwell",
    year: 1949,
    genre: "Distopia",
    isbn: "978-0-451-52493-5",
    createdAt: new Date("2024-01-16T14:30:00Z"),
  },
  {
    id: 3,
    title: "Dom Casmurro",
    author: "Machado de Assis",
    year: 1899,
    genre: "Romance",
    isbn: "978-0-7432-7356-5",
    createdAt: new Date("2024-02-01T09:15:00Z"),
  },
  {
    id: 4,
    title: "O Pequeno Príncipe",
    author: "Antoine de Saint-Exupéry",
    year: 1943,
    genre: "Fábula",
    isbn: "978-0-15-601219-5",
    createdAt: new Date("2024-02-10T16:45:00Z"),
  },
];

/**
 * Contador sequencial para geração de IDs únicos.
 *
 * Por que um contador em vez de Date.now()? Números sequenciais são mais previsíveis,
 * fáceis de testar e seguem a convenção REST de IDs inteiros. Em produção, UUIDs ou
 * ObjectId do MongoDB seriam preferidos para evitar colisões em sistemas distribuídos.
 */
let nextId = 5;

/**
 * Retorna uma cópia profunda (deep copy) de todos os livros.
 *
 * Por que retornar cópias? Se retornássemos a referência direta ao array, qualquer
 * consumidor poderia modificar os dados internos sem passar pelos handlers da API,
 * violando o princípio de encapsulamento e controle de mutação.
 *
 * @returns {Array<Book>} Cópia independente dos livros.
 */
function getAllBooks() {
  return books.map((book) => ({ ...book }));
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * Algoritmo: busca linear O(n). Para datasets grandes, uma Map<id, Book> seria
 * mais eficiente (O(1)), mas para este exemplo educacional a simplicidade do array
 * é preferível.
 *
 * @param {number} id - ID numérico do livro a ser buscado.
 * @returns {Book | undefined} O livro encontrado ou undefined se não existir.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adiciona um novo livro ao array e retorna o livro criado.
 *
 * Padrão adotado: atribuímos o ID automaticamente usando o contador `nextId`
 * porque é responsabilidade do servidor gerenciar identificador único, não do cliente.
 * Isso evita colisões de ID e segue a convenção REST de recursos gerenciados pelo servidor.
 *
 * @param {CreateBookDto} bookData - Dados do novo livro (sem id).
 * @returns {Book} O livro criado com ID atribuído.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    title: bookData.title,
    author: bookData.author,
    year: bookData.year,
    genre: bookData.genre,
    isbn: bookData.isbn,
    createdAt: new Date(), // Data/hora atual do servidor
  };
  books.push(newBook);
  return { ...newBook }; // Retorna cópia para não expor referência interna
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * Estratégia de atualização: substituição completa (full update) via PUT, conforme
 * convenção REST. O cliente deve enviar todos os campos; campos ausentes serão
 * definidos como undefined. Para atualizações parciais, usaríamos PATCH.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Partial<Book>} updates - Campos a serem atualizados.
 * @returns {Book | null} O livro atualizado ou null se não encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Mescla os dados existentes com as atualizações
  books[index] = { ...books[index], ...updates };
  return { ...books[index] };
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} true se o livro foi encontrado e removido, false caso contrário.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove exatamente um elemento no índice encontrado
  return true;
}

/**
 * Calcula e retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Por que calcular sob demanda? Manter estatísticas pré-calculadas exigiria
 * atualizá-las em cada operação CRUD, introduzindo complexidade desnecessária
 * e risco de inconsistência. Para datasets pequenos, o custo computacional é
 * desprezível.
 *
 * @returns {Stats} Objeto com métricas agregadas do acervo.
 */
function getStats() {
  const totalBooks = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para agregação
  const genreCounts = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Ano mais antigo e mais recente no acervo
  const years = books.map((b) => b.year);
  const oldestYear = Math.min(...years);
  const newestYear = Math.max(...years);

  // Autor com mais livros (pode haver empate, mas retornamos o primeiro encontrado)
  const authorCounts = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});
  const topAuthor = Object.entries(authorCounts).reduce(
    (max, [author, count]) => (count > max.count ? { author, count } : max),
    { author: "", count: 0 }
  );

  return {
    totalBooks,
    genres: genreCounts,
    oldestYear,
    newestYear,
    topAuthor: topAuthor.author || "N/A",
    topAuthorBookCount: topAuthor.count,
  };
}

/**
 * Exporta todas as funções como um módulo CommonJS.
 *
 * Por que exports nominais em vez de module.exports = { ... }? A forma explícita
 * facilita a importação seletiva (tree-shaking em bundlers) e torna o código mais
 * legível ao mostrar exatamente quais símbolos estão sendo exportados.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

