## Arquivo 3: `src/middleware/errorMiddleware.js`

```javascript
/**
 * @fileoverview Middleware de tratamento de erros para a API de livros.
 *
 * Em Express.js, middlewares de erro têm uma assinatura especial com 4 parâmetros:
 * (err, req, res, next). O framework os identifica automaticamente e os encadeia
 * apenas quando um erro é passado via next(err) ou lançado de forma síncrona/assíncrona.
 *
 * Padrão adotado: Classe Error personalizada + middleware genérico.
 * Isso permite que diferentes partes da aplicação lancem erros tipados, e o
 * middleware centralize a formatação da resposta de erro, garantindo consistência
 * no formato JSON retornado ao cliente.
 */

/**
 * Classe base para erros personalizados da API.
 *
 * Herda de Error nativo para manter compatibilidade com stack traces e instanceof.
 * O campo `statusCode` é adicionado para que o middleware possa determinar o código
 * HTTP apropriado (400, 404, 500, etc.) baseado no tipo de erro.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500).
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor da classe Error nativa
    this.statusCode = statusCode;
    this.isOperational = true; // Marca como erro operacional (não bug do servidor)
  }
}

/**
 * Classe para erros de recurso não encontrado.
 *
 * Convenção REST: 404 Not Found indica que o recurso solicitado existe na URI,
 * mas o identificador específico não corresponde a nenhum registro.
 */
class NotFoundError extends ApiError {
  constructor(resource, id) {
    super(`${resource} com ID ${id} não encontrado`, 404);
  }
}

/**
 * Classe para erros de validação de entrada.
 *
 * Convenção REST: 400 Bad Request indica que o cliente enviou dados inválidos.
 * O middleware incluirá detalhes do campo inválido na resposta.
 */
class ValidationError extends ApiError {
  constructor(message, field) {
    super(message, 400);
    this.field = field; // Campo específico que falhou na validação
  }
}

/**
 * Middleware genérico de tratamento de erros do Express.
 *
 * Posicionamento: deve ser o ÚLTIMO middleware registrado (após todas as rotas).
 * O Express executa middlewares em ordem FIFO; ao colocá-lo por último, garantimos
 * que ele capture erros de qualquer rota ou middleware anterior.
 *
 * Formato da resposta de erro (padrão REST):
 * {
 *   success: false,
 *   error: {
 *     message: "...",
 *     statusCode: 404,
 *     field: "..."  // apenas para ValidationError
 *   }
 * }
 *
 * @param {Error} err - Instância de ApiError (ou Error genérico).
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
function errorHandler(err, req, res, next) {
  // Se o erro não for uma instância de ApiError, trata como erro interno do servidor
  if (!(err instanceof ApiError)) {
    console.error("[ERRO NÃO OPERACIONAL]", err); // Log para depuração
    return res.status(500).json({
      success: false,
      error: {
        message: "Erro interno do servidor. Tente novamente mais tarde.",
        statusCode: 500,
      },
    });
  }

  // Resposta padronizada para erros operacionais (4xx)
  res.status(err.statusCode).json({
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode,
      ...(err.field && { field: err.field }), // Inclui campo apenas se existir
    },
  });
}

/**
 * Middleware de validação de campos obrigatórios.
 *
 * Padrão adotado: validação explícita no middleware em vez de dentro do handler.
 * Isso separa responsabilidades (Single Responsibility Principle): o handler foca
 * na lógica de negócio, enquanto o middleware cuida da integridade dos dados.
 *
 * @param {...string} fields - Nomes dos campos obrigatórios a verificar.
 * @returns {Function} Middleware Express que valida os campos.
 */
function requireFields(...fields) {
  return (req, res, next) => {
    // Verifica se todos os campos obrigatórios estão presentes e não são vazios
    const missing = fields.filter((field) => {
      const value = req.body[field];
      return value === undefined || value === null || value === "";
    });

    if (missing.length > 0) {
      // Lança ValidationError com detalhes do primeiro campo faltante
      throw new ValidationError(
        `Campos obrigatórios ausentes: ${missing.join(", ")}`,
        missing[0]
      );
    }

    next(); // Campos válidos — prossegue para o handler
  };
}

/**
 * Middleware de validação do ID na URL (parâmetro de rota).
 *
 * Em REST, IDs são parte da URI e devem ser inteiros positivos.
 * Express não faz parsing automático de tipos, então verificamos manualmente.
 *
 * @returns {Function} Middleware que valida o parâmetro :id.
 */
function validateIdParam() {
  return (req, res, next) => {
    const id = parseInt(req.params.id, 10); // Converte string para número inteiro

    if (isNaN(id) || id < 1) {
      throw new ValidationError("ID deve ser um número inteiro positivo", "id");
    }

    // Substitui o parâmetro string pelo número convertido para uso nos handlers
    req.params.id = id;
    next();
  };
}

/**
 * Middleware de logging de requisições (opcional, para depuração).
 *
 * Registra método, URL e timestamp de cada requisição. Útil para monitoramento
 * e debugging, mas pode ser removido em produção para reduzir verbosidade nos logs.
 *
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
function requestLogger(req, res, next) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.originalUrl}`);
  next();
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler,
  requireFields,
  validateIdParam,
  requestLogger,
};
```

> **Explicação do padrão de middleware:** O Express usa o padrão "middleware chain" — cada função recebe `(req, res, next)` e decide se encerra a cadeia (enviando resposta) ou chama `next()` para passar ao próximo middleware. Middlewares de erro têm 4 parâmetros e só são invocados quando `next(err)` é chamado. As classes de erro personalizadas permitem tratamento diferenciado por tipo, enquanto o middleware centraliza a formatação JSON da resposta.

