## Arquivo 4: `src/routes/booksRoutes.js`

```javascript
/**
 * @fileoverview Rotas REST para o recurso "livros".
 *
 * Convenções REST adotadas:
 * - GET    /books       → Listar todos (com filtragem opcional)
 * - GET    /books/:id   → Obter um específico
 * - POST   /books       → Criar novo
 * - PUT    /books/:id   → Atualizar completo (substituição)
 * - DELETE /books/:id   → Remover
 *
 * Por que PUT e não PATCH? PUT implica substituição completa do recurso.
 * Se o cliente omitir um campo, ele será removido. Para atualizações parciais,
 * criaríamos rotas separadas com PATCH — mas para este exemplo, mantemos a simplicidade.
 *
 * Padrão de resposta: { success: boolean, data?: T, error?: ErrorDetail }
 * Este formato unificado facilita o consumo pelo cliente e permite distinguir
 * claramente entre sucesso e falha sem precisar analisar códigos HTTP isoladamente.
 */

const express = require("express");
const router = express.Router(); // Cria um roteador independente (boa prática para modularidade)

// Importação dos dados em memória
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require("../data/booksData");

// Importação dos middlewares de validação e erro
const {
  requireFields,
  validateIdParam,
  NotFoundError,
  ValidationError,
} = require("../middleware/errorMiddleware");

/**
 * @swagger
 * /books:
 *   get:
 *     summary: Listar todos os livros com filtragem opcional
 *     parameters:
 *       - in: query
 *         name: genre
 *         schema:
 *           type: string
 *         description: Filtrar por gênero literário
 *       - in: query
 *         name: author
 *         schema:
 *           type: string
 *         description: Filtrar por autor (busca parcial, case-insensitive)
 *       - in: query
 *         name: minYear
 *         schema:
 *           type: integer
 *         description: Ano mínimo de publicação
 *       - in: query
 *         name: maxYear
 *         schema:
 *           type: integer
 *         description: Ano máximo de publicação
 *     responses:
 *       200:
 *         description: Lista de livros retornada com sucesso
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 success:
 *                   type: boolean
 *                   example: true
 *                 data:
 *                   type: array
 *                   items:
 *                     $ref: '#/components/schemas/Book'
 */

/**
 * GET /books — Listar todos os livros.
 *
 * Suporta filtragem via query parameters:
 *   ?genre=Fantasia          → Filtra por gênero exato
 *   ?author=tolkien          → Busca parcial no nome do autor (case-insensitive)
 *   ?minYear=1950            → Livros publicados a partir de 1950
 *   ?maxYear=2000            → Livros publicados até 2000
 *
 * Exemplos de uso:
 *
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fantasia"
 *   curl "http://localhost:3000/books?author=orwell&minYear=1940"
 *
 * @param {import('express').Request} req - Requisição com query parameters.
 * @param {import('express').Response} res - Resposta JSON.
 */
router.get("/books", (req, res) => {
  // Obtém cópia dos dados para não mutar o estado interno
  let result = getAllBooks();

  const { genre, author, minYear, maxYear } = req.query;

  // Filtragem por gênero — comparação exata, case-insensitive
  if (genre) {
    result = result.filter((book) =>
      book.genre.toLowerCase() === genre.toLowerCase()
    );
  }

  // Filtragem por autor — busca parcial (includes) para tolerância a variações
  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // Filtragem por faixa de ano — comparações numéricas
  if (minYear) {
    const min = parseInt(minYear, 10);
    result = result.filter((book) => book.year >= min);
  }

  if (maxYear) {
    const max = parseInt(maxYear, 10);
    result = result.filter((book) => book.year <= max);
  }

  // Resposta padronizada com metadados de paginação (futuro)
  res.json({
    success: true,
    data: result,
    meta: {
      count: result.length,
      totalDisponiveis: getAllBooks().length,
      filtrosAplicados: { genre, author, minYear, maxYear },
    },
  });
});

/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Obter um livro pelo ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     responses:
 *       200:
 *         description: Livro encontrado
 *       404:
 *         description: Livro não encontrado
 */

/**
 * GET /books/:id — Obter um livro específico.
 *
 * Exemplos de uso:
 *
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404
 *
 * @param {import('express').Request} req - Requisição com params.id.
 * @param {import('express').Response} res - Resposta JSON.
 * @param {import('express').NextFunction} next - Next do Express.
 */
router.get("/books/:id", validateIdParam(), (req, res, next) => {
  const book = getBookById(req.params.id);

  if (!book) {
    // Lança NotFoundError para ser capturado pelo middleware de erro
    throw new NotFoundError("Livro", req.params.id);
  }

  res.json({ success: true, data: book });
});

/**
 * @swagger
 * /books:
 *   post:
 *     summary: Criar um novo livro
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, year, genre]
 *             properties:
 *               title: { type: string }
 *               author: { type: string }
 *               year: { type: integer }
 *               genre: { type: string }
 *               isbn: { type: string }
 *     responses:
 *       201:
 *         description: Livro criado com sucesso
 *       400:
 *         description: Dados de entrada inválidos
 */

/**
 * POST /books — Criar um novo livro.
 *
 * Campos obrigatórios: title, author, year, genre
 * Campo opcional: isbn (padrão ISO)
 *
 * Exemplos de uso:
 *
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Distopia"}'
 *
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Memórias Póstumas de Brás Cubas","author":"Machado de Assis","year":1881,"genre":"Romance","isbn":"978-0-7432-7357-2"}'
 *
 * @param {import('express').Request} req - Corpo da requisição com dados do livro.
 * @param {import('express').Response} res - Resposta JSON.
 * @param {import('express').NextFunction} next - Next do Express.
 */
router.post(
  "/books",
  // Middleware de validação: campos obrigatórios antes de processar
  requireFields("title", "author", "year", "genre"),
  (req, res, next) => {
    const { title, author, year, genre, isbn } = req.body;

    // Validação adicional do ano — deve ser um número válido e razoável
    if (typeof year !== "number" || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError(
        `Ano inválido: ${year}. Deve ser um número entre 0 e ${new Date().getFullYear() + 1}`,
        "year"
      );
    }

    // Validação do ISBN — formato básico (13 dígitos com hífens permitidos)
    if (isbn && !/^\d{3}-?\d{1}-?-\d{5}-?\d{2}-?\d{1}$/.test(isbn.replace(/-/g, ""))) {
      throw new ValidationError(
        "ISBN inválido. Formato esperado: XXX-X-XXX-XXXXX-XX-X",
        "isbn"
      );
    }

    const newBook = createBook({ title, author, year, genre, isbn });

    // Código 201 Created indica recurso criado com sucesso (convenção REST)
    res.status(201).json({
      success: true,
      data: newBook,
      message: "Livro criado com sucesso",
    });
  }
);

/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Atualizar um livro existente (substituição completa)
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author, year, genre]
 *             properties:
 *               title: { type: string }
 *               author: { type: string }
 *               year: { type: integer }
 *               genre: { type: string }
 *               isbn: { type: string }
 *     responses:
 *       200:
 *         description: Livro atualizado
 *       404:
 *         description: Livro não encontrado
 */

/**
 * PUT /books/:id — Atualizar um livro existente.
 *
 * Nota importante sobre PUT vs PATCH:
 * - PUT = substituição completa. Todos os campos obrigatórios devem ser enviados.
 * - PATCH = atualização parcial. Apenas os campos desejados são enviados.
 *
 * Para este exemplo, usamos PUT com todos os campos obrigatórios para manter
 * a simplicidade e seguir estritamente a semântica REST.
 *
 * Exemplos de uso:
 *
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"O Senhor dos Anéis (Ed. Definitiva)","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia","isbn":"978-0-618-12416-3"}'
 *
 * @param {import('express').Request} req - Params e corpo da requisição.
 * @param {import('express').Response} res - Resposta JSON.
 * @param {import('express').NextFunction} next - Next do Express.
 */
router.put(
  "/books/:id",
  validateIdParam(),
  requireFields("title", "author", "year", "genre"),
  (req, res, next) => {
    const { title, author, year, genre, isbn } = req.body;

    // Validação do ano
    if (typeof year !== "number" || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError(
        `Ano inválido: ${year}`,
        "year"
      );
    }

    const updatedBook = updateBook(req.params.id, { title, author, year, genre, isbn });

    if (!updatedBook) {
      throw new NotFoundError("Livro", req.params.id);
    }

    res.json({
      success: true,
      data: updatedBook,
      message: "Livro atualizado com sucesso",
    });
  }
);

/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Excluir um livro
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     responses:
 *       200:
 *         description: Livro excluído com sucesso
 *       404:
 *         description: Livro não encontrado
 */

/**
 * DELETE /books/:id — Excluir um livro.
 *
 * Exemplos de uso:
 *
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404
 *
 * @param {import('express').Request} req - Params da requisição.
 * @param {import('express').Response} res - Resposta JSON.
 * @param {import('express').NextFunction} next - Next do Express.
 */
router.delete("/books/:id", validateIdParam(), (req, res, next) => {
  const deleted = deleteBook(req.params.id);

  if (!deleted) {
    throw new NotFoundError("Livro", req.params.id);
  }

  // Código 200 OK com mensagem de confirmação (alternativa: 204 No Content sem body)
  res.json({
    success: true,
    message: `Livro com ID ${req.params.id} foi excluído com sucesso`,
  });
});

/**
 * @swagger
 * /stats:
 *   get:
 *     summary: Retornar estatísticas do acervo de livros
 *     responses:
 *       200:
 *         description: Estatísticas calculadas
 */

/**
 * GET /stats — Estatísticas agregadas do acervo.
 *
 * Retorna métricas como total de livros, distribuição por gênero,
 * faixa de anos publicada e autor mais prolifico.
 *
 * Exemplos de uso:
 *
 *   curl http://localhost:3000/stats
 *
 * @param {import('express').Request} req - Requisição.
 * @param {import('express').Response} res - Resposta JSON.
 */
router.get("/stats", (req, res) => {
  const stats = getStats();

  res.json({
    success: true,
    data: stats,
  });
});

module.exports = router;
```

> **Explicação do padrão de rotas:** Cada rota Express é uma função que recebe `(req, res, next)`. Middlewares como `validateIdParam()` e `requireFields()` são aplicados antes do handler principal, criando uma cadeia de responsabilidades. O uso de `throw` em vez de `res.status().json()` permite que o erro seja capturado pelo middleware de erro global, mantendo os handlers limpos e focados na lógica de negócio.

