## Arquivo 5: `src/app.js`

```javascript
/**
 * @fileoverview Configuração da aplicação Express.
 *
 * Este arquivo centraliza a configuração do servidor Express, incluindo:
 * - Middlewares globais (JSON parsing, logging)
 * - Registro de rotas
 * - Middleware de tratamento de erros
 * - CORS básico para desenvolvimento
 *
 * Padrão adotado: Separar configuração da aplicação (app.js) do ponto de entrada (index.js).
 * Isso permite testar a configuração da aplicação isoladamente e facilita a troca
 * do servidor HTTP (HTTP nativo vs HTTPS com certificados).
 */

const express = require("express");
const cors = require("cors"); // Nota: em produção real, instalar 'cors' via npm

// Importação das rotas de livros
const booksRoutes = require("./routes/booksRoutes");

/**
 * Cria e configura a instância da aplicação Express.
 *
 * Por que criar a app aqui? A função `express()` cria uma nova instância isolada,
 * permitindo múltiplas aplicações no mesmo processo se necessário (ex: microserviços).
 *
 * @returns {import('express').Application} Instância configurada do Express.
 */
function createApp() {
  const app = express();

  // ========================================
  // Middlewares Globais
  // ========================================

  /**
   * Middleware CORS — permite requisições de origens diferentes.
   *
   * Em desenvolvimento, '*' (qualquer origem) é aceitável.
   * Em produção, restrinja a domínios específicos por segurança.
   */
  app.use(cors());

  /**
   * Middleware de parsing de JSON.
   *
   * Express não faz parsing automático do corpo das requisições.
   * Este middleware converte o body JSON em objeto JavaScript (req.body).
   * Limite de 10kb para evitar payloads excessivamente grandes.
   */
  app.use(express.json({ limit: "10kb" }));

  /**
   * Middleware de logging de requisições.
   *
   * Registra método, URL e timestamp de cada requisição no console.
   * Útil para debugging e monitoramento em tempo real.
   */
  app.use(require("./middleware/errorMiddleware").requestLogger);

  // ========================================
  // Rotas da API
  // ========================================

  /**
   * Rota raiz — health check da API.
   *
   * Padrão REST: endpoints de saúde/info retornam metadados sobre o serviço.
   */
  app.get("/", (req, res) => {
    res.json({
      success: true,
      message: "API de Livros — Servidor rodando com sucesso!",
      version: "1.0.0",
      endpoints: {
        books: "GET /books, GET /books/:id, POST /books, PUT /books/:id, DELETE /books/:id",
        stats: "GET /stats",
      },
    });
  });

  /**
   * Mount das rotas de livros no prefixo /api.
   *
   * Por que usar prefixo /api? Separa rotas da API das rotas internas/healthcheck,
   * facilitando versionamento futuro (ex: /api/v2/) e documentação.
   */
  app.use("/api", booksRoutes);

  // ========================================
  // Tratamento de Rotas Não Encontradas (404)
  // ========================================

  /**
   * Middleware para rotas inexistentes.
   *
   * Posicionamento: após todas as rotas definidas, mas ANTES do middleware de erro.
   * Captura requisições para URLs que não correspondem a nenhuma rota registrada.
   */
  app.use((req, res, next) => {
    const { NotFoundError } = require("./middleware/errorMiddleware");
    throw new NotFoundError("Recurso", req.originalUrl);
  });

  // ========================================
  // Middleware de Tratamento de Erros (GLOBAL)
  // ========================================

  /**
   * Middleware de erro — deve ser o ÚLTIMO middleware registrado.
   *
   * Captura todos os erros lançados por middlewares e handlers anteriores,
   * incluindo erros síncronos (throw) e assíncronos (promises rejeitadas).
   */
  app.use(require("./middleware/errorMiddleware").errorHandler);

  return app;
}

module.exports = createApp;
```

> **Explicação do padrão de configuração:** O Express executa middlewares em ordem estrita. Por isso, a sequência é crítica: (1) CORS → (2) JSON parsing → (3) Logging → (4) Rotas → (5) 404 handler → (6) Error handler. Inverter a ordem do error handler colocá-lo-ia antes das rotas, impedindo que capturasse erros delas. O prefixo `/api` nas rotas é uma convenção amplamente adotada que facilita versionamento e documentação.

