## Arquivo 6: `src/index.js`

```javascript
/**
 * @fileoverview Ponto de entrada da aplicação.
 *
 * Responsável por:
 * - Criar a instância do servidor HTTP
 * - Definir a porta de escuta
 * - Log de inicialização
 *
 * Padrão adotado: Porta configurável via variável de ambiente (PORT) com fallback
 * para 3000. Isso permite executar múltiplas instâncias em portas diferentes
 * e segue a convenção Twelve-Factor App para configuração.
 */

const createApp = require("./app");

// Cria a aplicação Express configurada
const app = createApp();

// Define a porta: variável de ambiente PORT ou padrão 3000
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor HTTP e faz log de inicialização.
 *
 * O callback de 'listening' é executado apenas após o servidor começar
 * a aceitar conexões, garantindo que a porta esteja realmente disponível.
 */
const server = app.listen(PORT, () => {
  console.log(`╔══════════════════════════════════════════════════╗`);
  console.log(`║     API de Livros — Servidor Iniciado!          ║`);
  console.log(`╠══════════════════════════════════════════════════╣`);
  console.log(`║  Endereço:   http://localhost:${PORT}            ║`);
  console.log(`║  Health Check: http://localhost:${PORT}/         ║`);
  console.log(`║  Livros:     http://localhost:${PORT}/api/books  ║`);
  console.log(`║  Stats:      http://localhost:${PORT}/api/stats  ║`);
  console.log(`╚══════════════════════════════════════════════════╝`);
});

// Tratamento de erros não capturados no processo
process.on("uncaughtException", (err) => {
  console.error("[UNCAUGHT EXCEPTION]", err);
  server.close(() => process.exit(1)); // Fecha o servidor antes de sair
});

process.on("unhandledRejection", (reason, promise) => {
  console.error("[UNHANDLED REJECTION]", reason);
});

module.exports = server;
```

